INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'vemâ es''elüküm `aleyhi min ecr. in ecriye illâ `alâ rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'etütrakûne fî mâ hâhünâ âminîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'fî cennâtiv ve`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'vezürû`iv venaḫlin ṭal`uhâ heḍîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'vetenḥitûne mine-lcibâli büyûten fârihîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'fetteḳu-llâhe veeṭî`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'velâ tüṭî`û emra-lmüsrifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'elleẕîne yüfsidûne fi-l''arḍi velâ yuṣliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'ḳâlû innemâ ente mine-lmüseḥḥarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'mâ ente illâ beşerum miŝlünâ. fe''ti biâyetin in künte mine-ṣṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, 'ḳâle hâẕihî nâḳatül lehâ şirbüv veleküm şirbü yevmim ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'velâ temessûhâ bisûin feye''ḫuẕeküm `aẕâbü yevmin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'fe`aḳarûhâ feaṣbeḥû nâdimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'feeḫaẕehümü-l`aẕâb. inne fî ẕâlike leâyeh. vemâ kâne ekŝeruhüm mü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'veinne rabbeke lehüve-l`azîzü-rraḥîm.', '');
