INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'vemâ es''elüküm `aleyhi min ecr. in ecriye illâ `alâ rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'ete''tûne-ẕẕükrâne mine-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'veteẕerûne mâ ḫaleḳa leküm rabbüküm min ezvâciküm. bel entüm ḳavmün `âdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'ḳâlû leil lem tentehi yâ lûṭu letekûnenne mine-lmuḫracîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, 'ḳâle innî li`ameliküm mine-lḳâlîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'rabbi neccinî veehlî mimmâ ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'fenecceynâhü veehlehû ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'illâ `acûzen fi-lgâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'ŝümme demmerne-l''âḫarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'veemṭarnâ `aleyhim meṭarâ. fesâe meṭaru-lmünẕerîn.', '');
