INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'vezinû bilḳisṭâsi-lmüsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'velâ tebḫasü-nnâse eşyâehüm velâ ta`ŝev fi-l''arḍi müfsidîn.', '');
