INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'feesḳiṭ `aleynâ kisefem mine-ssemâi in künte mine-ṣṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, 'ḳâle rabbî a`lemü bimâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'fekeẕẕebûhü feeḫaẕehüm `aẕâbü yevmi-żżulleh. innehû kâne `aẕâbe yevmin `ażîm.', '');
