INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'veinne rabbeke lehüve-l`azîzü-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'veinnehû letenzîlü rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'nezele bihi-rrûḥu-l''emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, '`alâ ḳalbike litekûne mine-lmünẕirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'bilisânin `arabiyyim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'veinnehû lefî zübüri-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'evelem yekül lehüm âyeten ey ya`lemehû `ulemâü benî isrâîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'velev nezzelnâhü `alâ ba`ḍi-l''a`cemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'feḳara''ehû `aleyhim mâ kânû bihî mü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'keẕâlike seleknâhü fî ḳulûbi-lmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'lâ yü''minûne bihî ḥattâ yeravu-l`aẕâbe-l''elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'feye''tiyehüm bagtetev vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'feyeḳûlû hel naḥnü münżarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'efebi`aẕâbinâ yesta`cilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'eferaeyte im metta`nâhüm sinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'ŝümme câehüm mâ kânû yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'mâ agnâ `anhüm mâ kânû yümette`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'vemâ ehleknâ min ḳaryetin illâ lehâ münẕirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'ẕikrâ. vemâ künnâ żâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'vemâ tenezzelet bihi-şşeyâṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'vemâ yembegî lehüm vemâ yesteṭî`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'innehüm `ani-ssem`i lema`zûlûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'felâ ted`u me`a-llâhi ilâhen âḫara fetekûne mine-lmü`aẕẕebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'veenẕir `aşîrateke-l''aḳrabîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'vaḫfiḍ cenâḥake limeni-ttebe`ake mine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'fein `aṣavke feḳul innî berîüm mimmâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'vetevekkel `ale-l`azîzi-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'elleẕî yerâke ḥîne teḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'veteḳallübeke fi-ssâcidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'innehû hüve-ssemî`u-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'hel ünebbiüküm `alâ men tenezzelü-şşeyâṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'tenezzelü `alâ külli effâkin eŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'yülḳûne-ssem`a veekŝeruhüm kâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'veşşu`arâü yettebi`uhümü-lgâvûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'elem tera ennehüm fî külli vâdiy yehîmûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'veennehüm yeḳûlûne mâ lâ yef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'ille-lleẕîne âmenû ve`amilu-ṣṣâliḥâti veẕekerü-llâhe keŝîrav venteṣarû mim ba`di mâ żulimû. veseya`lemü-lleẕîne żalemû eyye münḳalebiy yenḳalibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'ṭâ-sîn. tilke âyâtü-lḳur''âni vekitâbim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'hüdev vebüşrâ lilmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'elleẕîne yüḳîmûne-ṣṣalâte veyü''tûne-zzekâte vehüm bil''âḫirati hüm yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'inne-lleẕîne lâ yü''minûne bil''âḫirati zeyyennâ lehüm a`mâlehüm fehüm ya`mehûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'ülâike-lleẕîne lehüm sûü-l`aẕâbi vehüm fi-l''âḫirati hümü-l''aḫserûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'veinneke letüleḳḳe-lḳur''âne mil ledün ḥakîmin `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, 'iẕ ḳâle mûsâ liehlihî innî ânestü nârâ. seâtîküm minhâ biḫaberin ev âtîküm bişihâbin ḳabesil le`alleküm taṣṭalûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'felemmâ câehâ nûdiye em bûrike men fi-nnâri vemen ḥavlehâ. vesübḥâne-llâhi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'yâ mûsâ innehû ene-llâhü-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'veelḳi `aṣâk. felemmâ raâhâ tehtezzü keennehâ cânnüv vellâ müdbirav velem yü`aḳḳib. yâ mûsâ lâ teḫaf innî lâ yeḫâfü ledeyye-lmürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'illâ men żaleme ŝümme beddele ḥusnem ba`de sûin feinnî gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'veedḫil yedeke fî ceybike taḫruc beyḍâe min gayri sûin fî tis`i âyâtin ilâ fir`avne veḳavmih. innehüm kânû ḳavmen fâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'felemmâ câethüm âyâtünâ mübṣiraten ḳâlû hâẕâ siḥrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'veceḥadû bihâ vesteyḳanethâ enfüsühüm żulmev ve`ulüvvâ. fenżur keyfe kâne `âḳibetü-lmüfsidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'veleḳad âteynâ dâvûde vesüleymâne `ilmâ. veḳâle-lḥamdü lillâhi-lleẕî feḍḍalenâ `alâ keŝîrim min `ibâdihi-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'veveriŝe süleymânü dâvûde veḳâle yâ eyyühe-nnâsü `ullimnâ menṭiḳa-ṭṭayri veûtînâ min külli şey''. inne hâẕâ lehüve-lfaḍlü-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'veḥuşira lisüleymâne cünûdühû mine-lcinni vel''insi veṭṭayri fehüm yûza`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'ḥattâ iẕâ etev `alâ vâdi-nnemli ḳâlet nemletüy yâ eyyühe-nnemlü-dḫulû mesâkineküm. lâ yaḥṭimenneküm süleymânü vecünûdühû vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'fetebesseme ḍâḥikem min ḳavlihâ veḳâle rabbi evzi`nî en eşküra ni`meteke-lletî en`amte `aleyye ve`alâ vâlideyye veen a`mele ṣâliḥan terḍâhü veedḫilnî biraḥmetike fî `ibâdike-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'vetefeḳḳade-ṭṭayra feḳâle mâ liye lâ era-lhüdhüd. em kâne mine-lgâibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'leü`aẕẕibennehû `aẕâben şedîden ev leeẕbeḥannehû ev leye''tiyennî bisülṭânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'femekeŝe gayra be`îdin feḳâle eḥattü bimâ lem tüḥiṭ bihî veci''tüke min sebeim binebeiy yeḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'innî vecettü-mraeten temlikühüm veûtiyet min külli şey''iv velehâ `arşün `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'vecettühâ veḳavmehâ yescüdûne lişşemsi min dûni-llâhi vezeyyene lehümü-şşeyṭânü a`mâlehüm feṣaddehüm `ani-ssebîli fehüm lâ yehtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'ellâ yescüdû lillâhi-lleẕî yuḫricü-lḫab''e fi-ssemâvâti vel''arḍi veya`lemü mâ tuḫfûne vemâ tü`linûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'allâhü lâ ilâhe illâ hüve rabbü-l`arşi-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, 'ḳâle senenżuru eṣadaḳte em künte mine-lkâẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'iẕheb bikitâbî hâẕâ feelḳih ileyhim ŝümme tevelle `anhüm fenżur mâẕâ yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, 'ḳâlet yâ eyyühe-lmeleü innî ülḳiye ileyye kitâbün kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'innehû min süleymâne veinnehû bismi-llâhi-rraḥmâni-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'ellâ ta`lû `aleyye ve''tûnî müslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'ḳâlet yâ eyyühe-lmeleü eftûnî fî emrî. mâ küntü ḳâṭi`aten emran ḥattâ teşhedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, 'ḳâlû naḥnü ülû ḳuvvetiv veülû be''sin şedîdiv vel''emru ileyki fenżurî mâẕâ te''mürîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'ḳâlet inne-lmülûke iẕâ deḫalû ḳaryeten efsedûhâ vece`alû e`izzete ehlihâ eẕilleh. vekeẕâlike yef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'veinnî mürsiletün ileyhim bihediyyetin fenâżiratüm bime yerci`u-lmürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'felemmâ câe süleymâne ḳâle etümiddûnenî bimâl. femâ etâniye-llâhü ḫayrum mimmâ âtâküm. bel entüm bihediyyetiküm tefraḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'irci` ileyhim felene''tiyennehüm bicünûdil lâ ḳibele lehüm bihâ velenuḫricennehüm minhâ eẕilletev vehüm ṣâgirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'ḳâle yâ eyyühe-lmeleü eyyüküm ye''tînî bi`arşihâ ḳable ey ye''tûnî müslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'ḳâle `ifrîtüm mine-lcinni ene âtîke bihî ḳable en teḳûme mim meḳâmik. veinnî `aleyhi leḳaviyyün emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'ḳâle-lleẕî `indehû `ilmüm mine-lkitâbi ene âtîke bihî ḳable ey yertedde ileyke ṭarfük. felemmâ raâhü müsteḳirran `indehû ḳâle hâẕâ min faḍli rabbî. liyeblüvenî eeşküru em ekfür. vemen şekera feinnemâ yeşküru linefsih. vemen kefera feinne rabbî ganiyyün kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'ḳâle nekkirû lehâ `arşehâ nenżur etehtedî em tekûnü mine-lleẕîne lâ yehtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'felemmâ câet ḳîle ehâkeẕâ `arşük. ḳâlet keennehû hû. veûtîne-l`ilme min ḳablihâ vekünnâ müslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'veṣaddehâ mâ kânet ta`büdü min dûni-llâh. innehâ kânet min ḳavmin kâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'ḳîle lehe-dḫuli-ṣṣarḥ. felemmâ raethü ḥasibethü lüccetev vekeşefet `an sâḳayhâ. ḳâle innehû ṣarḥum mümerradüm min ḳavârîr. ḳâlet rabbi innî żalemtü nefsî veeslemtü me`a süleymâne lillâhi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'veleḳad erselnâ ilâ ŝemûde eḫâhüm ṣâliḥan eni-`büdü-llâhe feiẕâ hüm ferîḳâni yaḫteṣimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, 'ḳâle yâ ḳavmi lime testa`cilûne bisseyyieti ḳable-lḥaseneh. levlâ testagfirûne-llâhe le`alleküm türḥamûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, 'ḳâlu-ṭṭayyernâ bike vebimem me`ak. ḳâle ṭâiruküm `inde-llâhi bel entüm ḳavmün tüftenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'vekâne fi-lmedîneti tis`atü rahṭiy yüfsidûne fi-l''arḍi velâ yuṣliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'ḳâlû teḳâsemû billâhi lenübeyyitennehû veehlehû ŝümme leneḳûlenne liveliyyihî mâ şehidnâ mehlike ehlihî veinnâ leṣâdiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'vemekerû mekrav vemekernâ mekrav vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'fenżur keyfe kâne `âḳibetü mekrihim ennâ demmernâhüm veḳavmehüm ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'fetilke büyûtühüm ḫâviyetem bimâ żalemû. inne fî ẕâlike leâyetel liḳavmiy ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'veenceyne-lleẕîne âmenû vekânû yetteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'velûṭan iẕ ḳâle liḳavmihî ete''tûne-lfâḥişete veentüm tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'einneküm lete''tûne-rricâle şehvetem min dûni-nnisâi. bel entüm ḳavmün techelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'femâ kâne cevâbe ḳavmihî illâ en ḳâlû aḫricû âle lûṭim min ḳaryetiküm. innehüm ünâsüy yeteṭahherûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'feenceynâhü veehlehû ille-mraeteh. ḳaddernâhâ mine-lgâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'veemṭarnâ `aleyhim meṭarâ. fesâe meṭaru-lmünẕerîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'ḳuli-lḥamdü lillâhi veselâmün `alâ `ibâdihi-lleẕîne-ṣṭafâ. ellâhü ḫayrun emmâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'emmen ḫaleḳa-ssemâvâti vel''arḍa veenzele leküm mine-ssemâi mââ. feembetnâ bihî ḥadâiḳa ẕâte behceh. mâ kâne leküm en tümbitû şecerahâ. eilâhüm me`a-llâh. bel hüm ḳavmüy ya`dilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'emmen ce`ale-l''arḍa ḳarârav vece`ale ḫilâlehâ enhârav vece`ale lehâ ravâsiye vece`ale beyne-lbaḥrayni ḥâcizâ. eilâhüm me`a-llâh. bel ekŝeruhüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'emmey yücîbü-lmuḍṭarra iẕâ de`âhü veyekşifü-ssûe veyec`alüküm ḫulefâe-l''arḍ. eilâhüm me`a-llâh. ḳalîlem mâ teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'emmey yehdîküm fî żulümâti-lberri velbaḥri vemey yürsilü-rriyâḥa büşram beyne yedey raḥmetih. eilâhüm me`a-llâh. te`âle-llâhü `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'emmey yebdeü-lḫalḳa ŝümme yü`îdühû vemey yerzüḳuküm mine-ssemâi vel''arḍ. eilâhüm me`a-llâh. ḳul hâtû bürhâneküm in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'ḳul lâ ya`lemü men fi-ssemâvâti vel''arḍi-lgaybe ille-llâh. vemâ yeş`urûne eyyâne yüb`aŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'beli-ddârake `ilmühüm fi-l''âḫirah. bel hüm fî şekkim minhâ. bel hüm minhâ `amûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'veḳâle-lleẕîne keferû eiẕâ künnâ türâbev veâbâünâ einnâ lemuḫracûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'leḳad vu`idnâ hâẕâ naḥnü veâbâünâ min ḳablü in hâẕâ illâ esâṭîru-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'ḳul sîrû fi-l''arḍi fenżurû keyfe kâne `âḳibetü-lmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'velâ taḥzen `aleyhim velâ tekün fî ḍayḳim mimmâ yemkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, 'veyeḳûlûne metâ hâẕe-lva`dü in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'ḳul `asâ ey yekûne radife leküm ba`ḍu-lleẕî testa`cilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'veinne rabbeke leẕû faḍlin `ale-nnâsi velâkinne ekŝerahüm lâ yeşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'veinne rabbeke leya`lemü mâ tükinnü ṣudûruhüm vemâ yü`linûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'vemâ min gâibetin fi-ssemâi vel''arḍi illâ fî kitâbim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'inne hâẕe-lḳur''âne yeḳuṣṣu `alâ benî isrâîle ekŝera-lleẕî hüm fîhi yaḫtelifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'veinnehû lehüdev veraḥmetül lilmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'inne rabbeke yaḳḍî beynehüm biḥukmih. vehüve-l`azîzü-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'fetevekkel `ale-llâh. inneke `ale-lḥaḳḳi-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'inneke lâ tüsmi`u-lmevtâ velâ tüsmi`u-ṣṣumme-ddü`âe iẕâ vellev müdbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'vemâ ente bihâdi-l`umyi `an ḍalâletihim. in tüsmi`u illâ mey yü''minü biâyâtinâ fehüm müslimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'veiẕâ veḳa`a-lḳavlü `aleyhim aḫracnâ lehüm dâbbetem mine-l''arḍi tükellimühüm enne-nnâse kânû biâyâtinâ lâ yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'veyevme naḥşüru min külli ümmetin fevcem mimmey yükeẕẕibü biâyâtinâ fehüm yûza`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'ḥattâ iẕâ câû ḳâle ekeẕẕebtüm biâyâtî velem tüḥîṭû bihâ `ilmen emmâẕâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'veveḳa`a-lḳavlü `aleyhim bimâ żalemû fehüm lâ yenṭiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'elem yerav ennâ ce`alne-lleyle liyeskünû fîhi vennehâra mübṣirâ. inne fî ẕâlike leâyâtil liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'veyevme yünfeḫu fi-ṣṣûri fefezi`a men fi-ssemâvâti vemen fi-l''arḍi illâ men şâe-llâh. veküllün etevhü dâḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'vetera-lcibâle taḥsebühâ câmidetev vehiye temürru merra-sseḥâb. ṣun`a-llâhi-lleẕî etḳane külle şey''. innehû ḫabîrum bimâ tef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'men câe bilḥaseneti felehû ḫayrum minhâ. vehüm min feza`iy yevmeiẕin âminûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'vemen câe bisseyyieti fekübbet vucûhühüm fi-nnâr. hel tüczevne illâ mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'innemâ ümirtü en a`büde rabbe hâẕihi-lbeldeti-lleẕî ḥarramehâ velehû küllü şey''. veümirtü en ekûne mine-lmüslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'veen etlüve-lḳur''ân. femeni-htedâ feinnemâ yehtedî linefsih. vemen ḍalle feḳul innemâ ene mine-lmünẕirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'veḳuli-lḥamdü lillâhi seyürîküm âyâtihî feta`rifûnehâ. vemâ rabbüke bigâfilin `ammâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'ṭâ-sîn-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'tilke âyâtü-lkitâbi-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'netlû `aleyke min nebei mûsâ vefir`avne bilḥaḳḳi liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'inne fir`avne `alâ fi-l''arḍi vece`ale ehlehâ şiye`ay yestaḍ`ifü ṭâifetem minhüm yüẕebbiḥu ebnâehüm veyestaḥyî nisâehüm. innehû kâne mine-lmüfsidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'venürîdü en nemünne `ale-lleẕîne-stuḍ`ifû fi-l''arḍi venec`alehüm eimmetev venec`alehümü-lvâriŝîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'venümekkine lehüm fi-l''arḍi venüriye fir`avne vehâmâne vecünûdehümâ minhüm mâ kânû yaḥẕerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'veevḥaynâ ilâ ümmi mûsâ en arḍi`îh. feiẕâ ḫifti `aleyhi feelḳîhi fi-lyemmi velâ teḫâfî velâ taḥzenî. innâ râddûhü ileyki vecâ`ilûhü mine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'felteḳaṭahû âlü fir`avne liyekûne lehüm `adüvvev veḥazenâ. inne fir`avne vehâmâne vecünûdehümâ kânû ḫâṭiîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'veḳâleti-mraetü fir`avne ḳurratü `aynil lî velek. lâ taḳtülûh. `asâ ey yenfe`anâ ev netteḫiẕehû veledev vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'veaṣbeḥa füâdü ümmi mûsâ fârigâ. in kâdet letübdî bihî levlâ er rabaṭnâ `alâ ḳalbihâ litekûne mine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'veḳâlet liuḫtihî ḳuṣṣîh. febeṣurat bihî `an cünübiv vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'veḥarramnâ `aleyhi-lmerâḍi`a min ḳablü feḳâlet hel edüllüküm `alâ ehli beytiy yekfülûnehû leküm vehüm lehû nâṣiḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'feradednâhü ilâ ümmihî key teḳarra `aynühâ velâ taḥzene velita`leme enne va`de-llâhi ḥaḳḳuv velâkinne ekŝerahüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'velemmâ belega eşüddehû vestevâ âteynâhü ḥukmev ve`ilmâ. vekeẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'vedeḫale-lmedînete `alâ ḥîni gafletim min ehlihâ fevecede fîhâ racüleyni yaḳtetilân. hâẕâ min şî`atihî vehâẕâ min `adüvvih. festegâŝehü-lleẕî min şî`atihî `ale-lleẕî min `adüvvihî fevekezehû mûsâ feḳaḍâ `aleyh. ḳâle hâẕâ min `ameli-şşeyṭân. innehû `adüvvüm müḍillüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, 'ḳâle rabbi innî żalemtü nefsî fagfir lî fegafera leh. innehû hüve-lgafûru-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, 'ḳâle rabbi bimâ en`amte `aleyye felen ekûne żahîral lilmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'feaṣbeḥa fi-lmedîneti ḫâifey yeteraḳḳabü feiẕe-lleẕi-stenṣarahû bil''emsi yestaṣriḫuh. ḳâle lehû mûsâ inneke legaviyyüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'felemmâ en erâde ey yebṭişe billeẕî hüve `adüvvül lehümâ ḳâle yâ mûsâ etürîdü en taḳtülenî kemâ ḳatelte nefsem bil''ems. in türîdü illâ en tekûne cebbâran fi-l''arḍi vemâ türîdü en tekûne mine-lmuṣliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'vecâe racülüm min aḳṣe-lmedîneti yes`â. ḳâle yâ mûsâ inne-lmelee ye''temirûne bike liyaḳtülûke faḫruc innî leke mine-nnâṣiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'feḫarace minhâ ḫâifey yeteraḳḳab. ḳâle rabbi neccinî mine-lḳavmi-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'velemmâ teveccehe tilḳâe medyene ḳâle `asâ rabbî ey yehdiyenî sevâe-ssebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'velemmâ verade mâe medyene vecede `aleyhi ümmetem mine-nnâsi yesḳûn. vevecede min dûnihimü-mraeteyni teẕûdân. ḳâle mâ ḫaṭbükümâ. ḳâletâ lâ nesḳî ḥattâ yuṣdira-rri`âü veebûnâ şeyḫun kebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'feseḳâ lehümâ ŝümme tevellâ ile-żżilli feḳâle rabbi innî limâ enzelte ileyye min ḫayrin feḳîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'fecâethü iḥdâhümâ temşî `ale-stiḥyâ''. ḳâlet inne ebî yed`ûke liyecziyeke ecra mâ seḳayte lenâ. felemmâ câehû veḳaṣṣa `aleyhi-lḳaṣaṣa ḳâle lâ teḫaf. necevte mine-lḳavmi-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'ḳâlet iḥdâhümâ yâ ebeti-ste''cirh. inne ḫayra meni-ste''certe-lḳaviyyü-l''emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, 'ḳâle innî ürîdü en ünkiḥake iḥde-bneteyye hâteyni `alâ en te''cüranî ŝemâniye ḥicec. fein etmemte `aşran femin `indik. vemâ ürîdü en eşüḳḳa `aleyk. setecidünî in şâe-llâhü mine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, 'ḳâle ẕâlike beynî vebeynek. eyyeme-l''eceleyni ḳaḍaytü felâ `udvâne `aleyy. vellâhü `alâ mâ neḳûlü vekîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'felemmâ ḳaḍâ mûse-l''ecele vesâra biehlihî ânese min cânibi-ṭṭûri nârâ. ḳâle liehlihi-mküŝû innî ânestü nâral le`allî âtîküm minhâ biḫaberin ev ceẕvetim mine-nnâri le`alleküm taṣṭalûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'felemmâ etâhâ nûdiye min şâṭii-lvâdi-l''eymeni fi-lbuḳ`ati-lmübâraketi mine-şşecerati ey yâ mûsâ innî ene-llâhü rabbü-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'veen elḳi `aṣâk. felemmâ raâhâ tehtezzü keennehâ cânnüv vellâ müdbirav velem yü`aḳḳib. yâ mûsâ aḳbil velâ teḫaf. inneke mine-l''âminîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'üslük yedeke fî ceybike taḫruc beyḍâe min gayri sû''. vaḍmüm ileyke cenâḥake mine-rrahbi feẕânike bürhânâni mir rabbike ilâ fir`avne vemeleih. innehüm kânû ḳavmen fâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'ḳâle rabbi innî ḳateltü minhüm nefsen feeḫâfü ey yaḳtülûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'veeḫî hârûnü hüve efṣaḥu minnî lisânen feersilhü me`iye rid''ey yüṣaddiḳunî. innî eḫâfü ey yükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, 'ḳâle seneşüddü `aḍudeke bieḫîke venec`alü lekümâ sülṭânen felâ yeṣilûne ileykümâ biâyâtinâ. entümâ vemeni-ttebe`aküme-lgâlibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'felemmâ câehüm mûsâ biâyâtinâ beyyinâtin ḳâlû mâ hâẕâ illâ siḥrum müfterav vemâ semi`nâ bihâẕâ fî âbâine-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'veḳâle mûsâ rabbî a`lemü bimen câe bilhüdâ min `indihî vemen tekûnü lehû `âḳibetü-ddâr. innehû lâ yüfliḥu-żżâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'veḳâle fir`avnü yâ eyyühe-lmeleü mâ `alimtü leküm min ilâhin gayrî. feevḳid lî yâ hâmânü `ale-ṭṭîni fec`al lî ṣarḥal le`allî eṭṭali`u ilâ ilâhi mûsâ veinnî leeżunnühû mine-lkâẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'vestekbera hüve vecünûdühû fi-l''arḍi bigayri-lḥaḳḳi veżannû ennehüm ileynâ lâ yürce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'feeḫaẕnâhü vecünûdehû fenebeẕnâhüm fi-lyemm. fenżur keyfe kâne `âḳibetu-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'vece`alnâhüm eimmetey yed`ûne ile-nnâr. veyevme-lḳiyâmeti lâ yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'veetba`nâhüm fî hâẕihi-ddünyâ la`neten. veyevme-lḳiyâmeti hüm mine-lmaḳbûḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'veleḳad âteynâ mûse-lkitâbe mim ba`di mâ ehlekne-lḳurûne-l''ûlâ beṣâira linnâsi vehüdev veraḥmetel le`allehüm yeteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'vemâ künte bicânibi-lgarbiyyi iẕ ḳaḍaynâ ilâ mûse-l''emra vemâ künte mine-şşâhidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'velâkinnâ enşe''nâ ḳurûnen feteṭâvele `aleyhimü-l`umür. vemâ künte ŝâviyen fî ehli medyene tetlû `aleyhim âyâtinâ velâkinnâ künnâ mürsilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'vemâ künte bicânibi-ṭṭûri iẕ nâdeynâ velâkir raḥmetem mir rabbike litünẕira ḳavmem mâ etâhüm min neẕîrim min ḳablike le`allehüm yeteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'velevlâ en tüṣîbehüm müṣîbetüm bimâ ḳaddemet eydîhim feyeḳûlû rabbenâ levlâ erselte ileynâ rasûlen fenettebi`a âyâtike venekûne mine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'felemmâ câehümü-lḥaḳḳu min `indinâ ḳâlû levlâ ûtiye miŝle mâ ûtiye mûsâ. evelem yekfürû bimâ ûtiye mûsâ min ḳabl. ḳâlû siḥrâni teżâherâ. veḳâlû innâ biküllin kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'ḳul fe''tû bikitâbim min `indi-llâhi hüve ehdâ minhümâ ettebi`hü in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'feil lem yestecîbû leke fa`lem ennemâ yettebi`ûne ehvâehüm. vemen eḍallü mimmeni-ttebe`a hevâhü bigayri hüdem mine-llâh. inne-llâhe lâ yehdi-lḳavme-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'veleḳad veṣṣalnâ lehümü-lḳavle le`allehüm yeteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'elleẕîne âteynâhümü-lkitâbe min ḳablihî hüm bihî yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'veiẕâ yütlâ `aleyhim ḳâlû âmennâ bihî innehü-lḥaḳḳu mir rabbinâ innâ künnâ min ḳablihî müslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'ülâike yü''tevne ecrahüm merrateyni bimâ ṣaberû veyedraûne bilḥaseneti-sseyyiete vemimmâ razaḳnâhüm yünfiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'veiẕâ semi`ü-llagve a`raḍû `anhü veḳâlû lenâ a`mâlünâ veleküm a`mâlüküm. selâmün `aleyküm. lâ nebtegi-lcâhilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'inneke lâ tehdî men aḥbebte velâkinne-llâhe yehdî mey yeşâ''. vehüve a`lemü bilmühtedîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'veḳâlû in nettebi`i-lhüdâ me`ake nüteḫattef min arḍinâ. evelem nümekkil lehüm ḥaramen âminey yücbâ ileyhi ŝemerâtü külli şey''ir rizḳam mil ledünnâ velâkinne ekŝerahüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'vekem ehleknâ min ḳaryetim beṭirat me`îşetehâ. fetilke mesâkinühüm lem tüskem mim ba`dihim illâ ḳalîlâ. vekünnâ naḥnü-lvâriŝîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'vemâ kâne rabbüke mühlike-lḳurâ ḥattâ yeb`aŝe fî ümmihâ rasûley yetlû `aleyhim âyâtinâ. vemâ künnâ mühliki-lḳurâ illâ veehlühâ żâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'vemâ ûtîtüm min şey''in femetâ`u-lḥayâti-ddünyâ vezînetühâ. vemâ `inde-llâhi ḫayruv veebḳâ. efelâ ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'efemev ve`adnâhü va`den ḥasenen fehüve lâḳîhi kemem metta`nâhü metâ`a-lḥayâti-ddünyâ ŝümme hüve yevme-lḳiyâmeti mine-lmuḥḍarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'veyevme yünâdîhim feyeḳûlü eyne şürakâiye-lleẕîne küntüm tez`umûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'ḳâle-lleẕîne ḥaḳḳa `aleyhimü-lḳavlü rabbenâ hâülâi-lleẕîne agveynâ. agveynâhüm kemâ gaveynâ. teberra''nâ ileyk. mâ kânû iyyânâ ya`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, 'veḳîle-d`û şürakâeküm fede`avhüm felem yestecîbû lehüm veraevü-l`aẕâb. lev ennehüm kânû yehtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'veyevme yünâdîhim feyeḳûlü mâẕâ ecebtümü-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'fe`amiyet `aleyhimü-l''embâü yevmeiẕin fehüm lâ yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'feemmâ men tâbe veâmene ve`amile ṣâliḥan fe`asâ ey yekûne mine-lmüfliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'verabbüke yaḫlüḳu mâ yeşâü veyaḫtâr. mâ kâne lehümü-lḫiyerah. sübḥâne-llâhi vete`âlâ `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'verabbüke ya`lemü mâ tükinnü ṣudûruhüm vemâ yü`linûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'vehüve-llâhü lâ ilâhe illâ hû. lehü-lḥamdü fi-l''ûlâ vel''âḫirah. velehü-lḥukmü veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'ḳul era''eytüm in ce`ale-llâhü `aleykümü-lleyle sermeden ilâ yevmi-lḳiyâmeti men ilâhün gayru-llâhi ye''tîküm biḍiyâ''. efelâ tesme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'ḳul era''eytüm in ce`ale-llâhü `aleykümü-nnehâra sermeden ilâ yevmi-lḳiyâmeti men ilâhün gayru-llâhi ye''tîküm bileylin teskünûne fîh. efelâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'vemir raḥmetihî ce`ale lekümü-lleyle vennehâra liteskünû fîhi velitebtegû min faḍlihî vele`alleküm teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'veyevme yünâdîhim feyeḳûlü eyne şürakâiye-lleẕîne küntüm tez`umûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'veneza`nâ min külli ümmetin şehîden feḳulnâ hâtû bürhâneküm fe`alimû enne-lḥaḳḳa lillâhi veḍalle `anhüm mâ kânû yefterûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'inne ḳârûne kâne min ḳavmi mûsâ febegâ `aleyhim. veâteynâhü mine-lkünûzi mâ inne mefâtiḥahû letenûü bil`uṣbeti üli-lḳuvveh. iẕ ḳâle lehû ḳavmühû lâ tefraḥ inne-llâhe lâ yüḥibbü-lferiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, 'vebtegi fîmâ âtâke-llâhü-ddâra-l''âḫirate velâ tense neṣîbeke mine-ddünyâ veaḥsin kemâ aḥsene-llâhü ileyke velâ tebgi-lfesâde fi-l''arḍ. inne-llâhe lâ yüḥibbü-lmüfsidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, 'ḳâle innemâ ûtîtühû `alâ `ilmin `indî. evelem ya`lem enne-llâhe ḳad ehleke min ḳablihî mine-lḳurûni men hüve eşeddü minhü ḳuvvetev veekŝeru cem`â. velâ yüs''elü `an ẕünûbihimü-lmücrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'feḫarace `alâ ḳavmihî fî zînetih. ḳâle-lleẕîne yürîdûne-lḥayâte-ddünyâ yâ leyte lenâ miŝle mâ ûtiye ḳârûnü innehû leẕû ḥażżin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'veḳâle-lleẕîne ûtü-l`ilme veyleküm ŝevâbü-llâhi ḫayrul limen âmene ve`amile ṣâliḥâ. velâ yüleḳḳâhâ ille-ṣṣâbirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'feḫasefnâ bihî vebidârihi-l''arḍa femâ kâne lehû min fietiy yenṣurûnehû min dûni-llâh. vemâ kâne mine-lmünteṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'veaṣbeḥa-lleẕîne temennev mekânehû bil''emsi yeḳûlûne veykeenne-llâhe yebsüṭu-rrizḳa limey yeşâü min `ibâdihî veyaḳdir. levlâ em menne-llâhü `aleynâ leḫasefe binâ. veykeennehû lâ yüfliḥu-lkâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'tilke-ddâru-l''âḫiratü nec`alühâ lilleẕîne lâ yürîdûne `ulüvven fi-l''arḍi velâ fesâdâ. vel`âḳibetü lilmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'men câe bilḥaseneti felehû ḫayrum minhâ. vemen câe bisseyyieti felâ yücze-lleẕîne `amilü-sseyyiâti illâ mâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'inne-lleẕî feraḍa `aleyke-lḳur''âne lerâddüke ilâ me`âd. ḳur rabbî a`lemü men câe bilhüdâ vemen hüve fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'vemâ künte tercû ey yülḳâ ileyke-lkitâbü illâ raḥmetem mir rabbike felâ tekûnenne żahîral lilkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'velâ yeṣuddünneke `an âyâti-llâhi ba`de iẕ ünzilet ileyke ved`u ilâ rabbike velâ tekûnenne mine-lmüşrikîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'velâ ted`u me`a-llâhi ilâhen âḫar. lâ ilâhe illâ hû. küllü şey''in hâlikün illâ vecheh. lehü-lḥukmü veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'elif-lâm-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'eḥasibe-nnâsü ey yütrakû ey yeḳûlû âmennâ vehüm lâ yüftenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'veleḳad fetenne-lleẕîne min ḳablihim feleya`lemenne-llâhü-lleẕîne ṣadeḳû veleya`lemenne-lkâẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'em ḥasibe-lleẕîne ya`melûne-sseyyiâti ey yesbiḳûnâ. sâe mâ yaḥkümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'men kâne yercû liḳâe-llâhi feinne ecele-llâhi leâtin. vehüve-ssemî`u-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'vemen câhede feinnemâ yücâhidü linefsih. inne-llâhe leganiyyün `ani-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'velleẕîne âmenû ve`amilu-ṣṣâliḥâti lenükeffiranne `anhüm seyyiâtihim velenecziyennehüm aḥsene-lleẕî kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'veveṣṣayne-l''insâne bivâlideyhi ḥusnâ. vein câhedâke litüşrike bî mâ leyse leke bihî `ilmün felâ tüṭi`hümâ. ileyye merci`uküm feünebbiüküm bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'velleẕîne âmenû ve`amilu-ṣṣâliḥâti lenüdḫilennehüm fi-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'vemine-nnâsi mey yeḳûlü âmennâ billâhi feiẕâ ûẕiye fi-llâhi ce`ale fitnete-nnâsi ke`aẕâbi-llâh. velein câe naṣrum mir rabbike leyeḳûlünne innâ künnâ me`aküm. eveleyse-llâhü bia`leme bimâ fî ṣudûri-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'veleya`lemenne-llâhü-lleẕîne âmenû veleya`lemenne-lmünâfiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'veḳâle-lleẕîne keferû lilleẕîne âmenü-ttebi`û sebîlenâ velnaḥmil ḫaṭâyâküm. vemâ hüm biḥâmilîne min ḫaṭâyâhüm min şey''. innehüm lekâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'veleyaḥmilünne eŝḳâlehüm eŝḳâlem me`a eŝḳâleküm. veleyüs''elünne yevme-lḳiyâmeti `ammâ kânû yefterûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'veleḳad erselnâ nûḥan ilâ ḳavmihî felebiŝe fîhim elfe senetin illâ ḫamsîne `âmâ. feeḫaẕehümu-ṭṭûfânü vehüm żâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'feenceynâhü veaṣḥâbe-ssefîneti vece`alnâhâ âyetel lil`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'veibrâhime iẕ ḳâle liḳavmihi-`büdü-llâhe vetteḳûh. ẕâliküm ḫayrul leküm in küntüm ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'innemâ ta`büdûne min dûni-llâhi evŝânev vetaḫluḳûne ifkâ. inne-lleẕîne ta`büdûne min dûni-llâhi lâ yemlikûne leküm rizḳan febtegû `inde-llâhi-rrizḳa va`büdûhü veşkürû leh. ileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'vein tükeẕẕibû feḳad keẕẕebe ümemüm min ḳabliküm. vemâ `ale-rrasûli ille-lbelâgu-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'evelem yerav keyfe yübdiü-llâhü-lḫalḳa ŝümme yü`îdüh. inne ẕâlike `ale-llâhi yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'ḳul sîrû fi-l''arḍi fenżurû keyfe bedee-lḫalḳa ŝümme-llâhü yünşiü-nneş''ete-l''âḫirah. inne-llâhe `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'yü`aẕẕibü mey yeşâü veyerḥamü mey yeşâ''. veileyhi tuḳlebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'vemâ entüm bimü`cizîne fi-l''arḍi velâ fi-ssemâ''. vemâ leküm min dûni-llâhi miv veliyyiv velâ neṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'velleẕîne keferû biâyâti-llâhi veliḳâihî ülâike yeisû mir raḥmetî veülâike lehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'femâ kâne cevâbe ḳavmihî illâ en ḳâlu-ḳtülûhü ev ḥarriḳûhü feencâhü-llâhü mine-nnâr. inne fî ẕâlike leâyâtil liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, 'veḳâle inneme-tteḫaẕtüm min dûni-llâhi evŝânem meveddete beyniküm fi-lḥayâti-ddünyâ. ŝümme yevme-lḳiyâmeti yekfüru ba`ḍuküm biba`ḍiv veyel`anü ba`ḍuküm ba`ḍâ. veme''vâküm-nnâru vemâ leküm min nâṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'feâmene lehû lûṭ. veḳâle innî mühâcirun ilâ rabbî. innehû hüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'vevehebnâ lehû isḥâḳa veya`ḳûbe vece`alnâ fî ẕürriyyetehü-nnübüvvete velkitâbe veâteynâhü ecrahû fi-ddünyâ. veinnehû fi-l''âḫirati lemine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'velûṭan iẕ ḳâle liḳavmihî inneküm lete''tûne-lfâḥişeh. mâ sebeḳaküm bihâ min eḥadim mine-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'einneküm lete''tûne-rricâle vetaḳṭa`ûne-ssebîle vete''tûne fî nâdîkümü-lmünker. femâ kâne cevâbe ḳavmihî illâ en ḳâlü-''tinâ bi`aẕâbi-llâhi in künte mine-ṣṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, 'ḳâle rabbi-nṣurnî `ale-lḳavmi-lmüfsidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'velemmâ câet rusülünâ ibrâhîme bilbüşrâ ḳâlû innâ mühlikû ehli hâẕihi-lḳaryeh. inne ehlehâ kânû żâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, 'ḳâle inne fîhâ lûṭâ. ḳâlû naḥnü a`lemü bimen fîhâ. lenünecciyennehû veehlehû ille-mraeteh. kânet mine-lgâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'velemmâ en câet rusülünâ lûṭan sîe bihim veḍâḳa bihim ẕer`av veḳâlû lâ teḫaf velâ taḥzen. innâ müneccûke veehleke ille-mraeteke kânet mine-lgâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'innâ münzilûne `alâ ehli hâẕihi-lḳaryeti riczem mine-ssemâi bimâ kânû yefsüḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'veleḳat teraknâ minhâ âyetem beyyinetel liḳavmiy ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'veilâ medyene eḫâhüm şu`ayben feḳâle yâ ḳavmi-`büdü-llâhe veercü-lyevme-l''âhira velâ ta`ŝev fi-l''arḍi müfsidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'fekeẕẕebûhü feeḫaẕethümü-rracfetü feaṣbeḥû fî dârihim câŝimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 've`âdev veŝemûde veḳat tebeyyene leküm mim mesâkinihim. vezeyyene lehümü-şşeyṭânü a`mâlehüm feṣaddehüm `ani-ssebîli vekânû müstebṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'veḳârûne vefir`avne vehâmâne veleḳad câehüm mûsâ bilbeyyinâti festekberû fi-l''arḍi vemâ kânû sâbiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'feküllen eḫaẕnâ biẕembih. feminhüm men erselnâ `aleyhi ḥâṣibâ. veminhüm men eḫaẕethu-ṣṣayḥah. veminhüm men ḫasefnâ bihi-l''arḍ. veminhüm men agraḳnâ. vemâ kâne-llâhü liyażlimehüm velâkin kânû enfüsehüm yażlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'meŝelü-lleẕîne-tteḫaẕû min dûni-llâhi evliyâe kemeŝeli-l`nkebût. itteḫaẕet beytâ. veinne evhene-lbüyûti lebeytü-l`nkebût. lev kânû ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'inne-llâhe ya`lemü mâ yed`ûne min dûnihî min şey''. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'vetilke-l''emŝâlü naḍribühâ linnâs. vemâ ya`ḳilühâ ille-l`âlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'ḫaleḳa-llâhü-ssemâvâti vel''arḍa bilḥaḳḳ. inne fî ẕâlike leâyetel lilmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'ütlü mâ ûḥiye ileyke mine-lkitâbi veeḳimi-ṣṣalâh. inne-ṣṣalâte tenhâ `ani-lfaḥşâi velmünker. veleẕikru-llâhi ekber. vellâhü ya`lemü mâ taṣne`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'velâ tücâdilû ehle-lkitâbi illâ billetî hiye aḥsen. ille-lleẕîne żalemû minhüm veḳûlû âmennâ billeẕî ünzile ileynâ veünzile ileyküm veileyhâ veilâhüküm vâḥidüv venaḥnü lehû müslimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'vekeẕâlike enzelnâ ileyke-lkitâb. felleẕîne âteynâhümü-lkitâbe yü''minûne bih. vemin hâülâi mey yü''minü bih. vemâ yecḥadü biâyâtinâ ille-lkâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'vemâ künte tetlû min ḳablihî min kitâbiv velâ teḫuṭṭuhû biyemînike iẕel lertâbe-lmübṭilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'bel hüve âyâtüm beyyinâtün fî ṣudûri-lleẕîne ûtü-l`ilm. vemâ yecḥadü biâyâtinâ ille-żżâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'veḳâlû levlâ ünzile `aleyhi âyâtüm mir rabbih. ḳul inneme-l''âyâtü `inde-llâh. veinnemâ ene neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'evelem yekfihim ennâ enzelnâ `aleyke-lkitâbe yütlâ `aleyhim. inne fî ẕâlike leraḥmetev veẕikrâ liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'ḳul kefâ billâhi beynî vebeyneküm şehîdâ. ya`lemü mâ fi-ssemâvâti vel''arḍ. velleẕîne âmenû bilbâṭili vekeferû billâhi ülâike hümü-lḫâsirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'veyesta`cilûneke bil`aẕâb. velevlâ ecelüm müsemmel lecâehüm-l`aẕâb. veleye''tiyennehüm bagtetev vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'yesta`cilûneke bil`aẕâb. veinne cehenneme lemüḥîṭatüm bilkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'yevme yagşâhümü-l`aẕâbü min fevḳihim vemin taḥti ercülihim veyeḳûlü ẕûḳû mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'yâ `ibâdîye-lleẕîne âmenû inne arḍî vâsi`aten feiyyâye fa`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'küllü nefsin ẕâiḳatü-lmevti ŝümme ileynâ türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'velleẕîne âmenû ve`amilu-ṣṣâliḥâti lenübevviennehüm mine-lcenneti gurafen tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ. ni`me ecru-l`âmilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'elleẕîne ṣaberû ve`alâ rabbihim yetevekkelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'vekeeyyim min dâbbetil lâ taḥmilü rizḳahâ. allâhü yerzüḳuhâ veiyyâküm. vehüve-ssemî`u-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'velein seeltehüm men ḫaleḳa-ssemâvâti vel''arḍa veseḫḫara-şşemse velḳamera leyeḳûlünne-llâh. feennâ yü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'allâhü yebsüṭu-rrizḳa limey yeşâü min `ibâdihî veyaḳdiru leh. inne-llâhe bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'velein seeltehüm men nezzele mine-ssemâi mâen feaḥyâ bihi-l''arḍa mim ba`di mevtihâ leyeḳûlünne-llâh. ḳuli-lḥamdü lillâh. bel ekŝeruhüm lâ ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'vemâ hâẕihi-lḥayâtü-ddünyâ illâ lehvüv vele`ib. veinne-ddâra-l''âḫirate lehiye-lḥayevân. lev kânû ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'feiẕâ rakibû fi-lfülki de`avu-llâhe muḫliṣîne lehü-ddîn. felemmâ neccâhüm ile-lberri iẕâ hüm yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'liyekfürû bimâ âteynâhüm veliyetemette`û. fesevfe ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'evelem yerav ennâ ce`alnâ ḥaramen âminev veyüteḫaṭṭafü-nnâsü min ḥavlehüm. efebilbâṭili yü''minûne vebini`meti-llâhi yekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'vemen ażlemü mimmeni-fterâ `ale-llâhi keẕiben ev keẕẕebe bilḥaḳḳi lemmâ câeh. eleyse fî cehenneme meŝvel lilkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'velleẕîne câhedû fînâ lenehdiyennehüm sübülenâ. veinne-llâhe leme`a-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'elif-lâm-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'gulibeti-rrûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'fî edne-l''arḍi vehüm mim ba`di galebihim seyaglibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'fî biḍ`i sinîn. lillâhi-l''emru min ḳablü vemim ba`d. veyevmeiẕiy yefraḥu-lmü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'binaṣri-llâh. yenṣuru mey yeşâ''. vehüve-l`azîzü-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'va`de-llâh. lâ yuḫlifü-llâhü va`dehû velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'ya`lemûne żâhiram mine-lḥayâti-ddünyâ. vehüm `ani-l''âḫirati hüm gâfilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'evelem yetefekkerû fî enfüsihim. mâ ḫaleḳa-llâhü-ssemâvâti vel''arḍa vemâ beynehümâ illâ bilḥaḳḳi veecelim müsemmâ. veinne keŝîram mine-nnâsi biliḳâi rabbihim lekâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'evelem yesîrû fi-l''arḍi feyenżurû keyfe kâne `âḳibetü-lleẕîne min ḳablihim. kânû eşedde minhüm ḳuvvetev veeŝârü-l''arḍa ve`amerûhâ ekŝera mimmâ `amerûhâ vecâethüm rusülühüm bilbeyyinât. femâ kâne-llâhü liyażlimehüm velâkin kânû enfüsehüm yażlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'ŝümme kâne `âḳibete-lleẕîne esâü-ssûâ en keẕẕebû biâyâti-llâhi vekânû bihâ yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'allâhü yebdeü-lḫalḳa ŝümme yü`îdühû ŝümme ileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'veyevme teḳûmü-ssâ`atü yüblisü-lmücrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'velem yekül lehüm min şürakâihim şüf`âü vekânû bişürakâihim kâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'veyevme teḳûmü-ssâ`atü yevmeiẕiy yeteferraḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'feemme-lleẕîne âmenû ve`amilu-ṣṣâliḥâti fehüm fî ravḍatey yuḥberûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'veemme-lleẕîne keferû vekeẕẕebû biâyâtinâ veliḳâi-l''âḫirati feülâike fi-l`aẕâbi muḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'fesübḥâne-llâhi ḥîne tümsûne veḥîne tuṣbiḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'velehü-lḥamdü fi-ssemâvâti vel''arḍi ve`aşiyyev veḥîne tużhirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'yuḫricü-lḥayye mine-lmeyyiti veyuḫricü-lmeyyite mine-lḥayyi veyuḥyi-l''arḍa ba`de mevtihâ. vekeẕâlike tuḫracûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'vemin âyâtihî en ḫaleḳaküm min türâbin ŝümme iẕâ entüm beşerun tenteşirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'vemin âyâtihî en ḫaleḳa leküm min enfüsiküm ezvâcel liteskünû ileyhâ vece`ale beyneküm meveddetev veraḥmeh. inne fî ẕâlike leâyâtil liḳavmiy yetefekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'vemin âyâtihî ḫalḳu-ssemâvâti vel''arḍi vaḫtilâfü elsinetiküm veelvâniküm. inne fî ẕâlike leâyâtil lil''`âlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'vemin âyâtihî menâmüküm billeyli vennehâri vebtigâüküm min faḍlih. inne fî ẕâlike leâyâtil liḳavmiy yesme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'vemin âyâtihî yürîkümü-lberḳa ḫavfev veṭame`av veyünezzilü mine-ssemâi mâen feyuḥyî bihi-l''arḍa ba`de mevtihâ. inne fî ẕâlike leâyâtil liḳavmiy ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'vemin âyâtihî en teḳûme-ssemâü vel''arḍu biemrih. ŝümme iẕâ de`âküm da`vetem mine-l''arḍi iẕâ entüm tuḫracûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'velehû men fi-ssemâvâti vel''arḍ. küllül lehû ḳânitûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'vehüve-lleẕî yebdeü-lḫalḳa ŝümme yü`îdühû vehüve ehvenü `aleyh. velehü-lmeŝelü-l''a`lâ fi-ssemâvâti vel''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'ḍarabe leküm meŝelem min enfüsiküm. hel leküm mim mâ meleket eymânüküm min şürakâe fî mâ razaḳnâküm feentüm fîhi sevâün teḫâfûnehüm keḫîfetiküm enfüseküm. keẕâlike nüfeṣṣilü-l''âyâti liḳavmiy ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'beli-ttebe`a-lleẕîne żalemû ehvâehüm bigayri `ilmin. femey yehdî men eḍalle-llâh. vemâ lehüm min nâṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'feeḳim vecheke lildîni ḥanîfâ. fiṭrate-llâhi-lletî feṭara-nnâse `aleyhâ. lâ tebdîle liḫalḳi-llâh. ẕâlike-ddînü-lḳayyim. velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'münîbîne ileyhi vetteḳûhü veeḳîmu-ṣṣalâte velâ tekûnû mine-lmüşrikîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'mine-lleẕîne ferraḳû dînehüm vekânû şiye`â. küllü ḥizbim bimâ ledeyhim feriḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'veiẕâ messe-nnâse ḍurrun de`av rabbehüm münîbîne ileyhi ŝümme iẕâ eẕâḳahüm minhü raḥmeten iẕâ ferîḳum minhüm birabbihim yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'liyekfürû bimâ âteynâhüm. fetemette`û. fesevfe ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'em enzelnâ `aleyhim sülṭânen fehüve yetekellemü bimâ kânû bihî yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'veiẕâ eẕaḳne-nnâse raḥmeten feriḥû bihâ. vein tüṣibhüm seyyietüm bimâ ḳaddemet eydîhim iẕâ hüm yaḳneṭûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'evelem yerav enne-llâhe yebsüṭu-rrizḳa limey yeşâü veyaḳdir. inne fî ẕâlike leâyâtil liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'feâti ẕe-lḳurbâ ḥaḳḳahû velmiskîne vebne-ssebîl. ẕâlike ḫayrul lilleẕîne yürîdûne veche-llâh. veülâike hümü-lmüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'vemâ âteytüm mir ribel liyerbüve fî emvâli-nnâsi felâ yerbû `inde-llâh. vemâ âteytüm min zekâtin türîdûne veche-llâhi feülâike hümü-lmuḍ`ifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'allâhü-lleẕî ḫaleḳaküm ŝümme razeḳaküm ŝümme yümîtüküm ŝümme yuḥyîküm. hel min şürakâiküm mey yef`alü min ẕâliküm min şey''. sübḥânehû vete`âlâ `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'żahera-lfesâdü fi-lberri velbaḥri bimâ kesebet eydi-nnâsi liyüẕîḳahüm ba`ḍa-lleẕî `amilû le`allehüm yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'ḳul sîrû fi-l''arḍi fenżurû keyfe kâne `âḳibetü-lleẕîne min ḳabl. kâne ekŝeruhüm müşrikîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'feeḳim vecheke lildîni-lḳayyimi min ḳabli ey ye''tiye yevmül lâ meradde lehû mine-llâhi yevmeiẕiy yeṣṣadde`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'men kefera fe`aleyhi küfruh. vemen `amile ṣâliḥan felienfüsihim yemhedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'liyecziye-lleẕîne âmenû ve`amilu-ṣṣâliḥâti min faḍlih. innehû lâ yüḥibbü-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'vemin âyâtihî ey yürsile-rriyâḥa mübeşşirâtiv veliyüẕîḳaküm mir raḥmetihî velitecriye-lfülkü biemrihî velitebtegû min faḍlihî vele`alleküm teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'veleḳad erselnâ min ḳablike rusülen ilâ ḳavmihim fecâûhüm bilbeyyinâti fenteḳamnâ mine-lleẕîne ecramû. vekâne ḥaḳḳan `aleynâ naṣru-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'allâhü-lleẕî yürsilü-rriyâḥa fetüŝîru seḥâben feyebsüṭuhû fi-ssemâi keyfe yeşâü veyec`alühû kisefen fetere-lvedḳa yaḫrucü min ḫilâlih. feiẕâ eṣâbe bihî mey yeşâü min `ibâdihî iẕâ hüm yestebşirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'vein kânû min ḳabli ey yünezzele `aleyhim min ḳablihî lemüblisîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'fenżur ilâ âŝeri raḥmeti-llâhi keyfe yuḥyi-l''arḍa ba`de mevtihâ. inne ẕâlike lemuḥyi-lmevtâ. vehüve `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'velein erselnâ rîḥan feraevhü muṣferral leżallû mim ba`dihî yekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'feinneke lâ tüsmi`u-lmevtâ velâ tüsmi`u-ṣṣumme-ddü`âe iẕâ vellev müdbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'vemâ ente bihâdi-l`umyi `an ḍalâletihim. in tüsmi`u illâ mey yü''minü biâyâtinâ fehüm müslimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'allâhü-lleẕî ḫaleḳaküm min ḍa`fin ŝümme ce`ale mim ba`di ḍa`fin ḳuvveten ŝümme ce`ale mim ba`di ḳuvvetin ḍa`fev veşeybeh. yaḫlüḳu mâ yeşâ''. vehüve-l`alîmü-lḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'veyevme teḳûmü-ssâ`atü yuḳsimü-lmücrimûne mâ lebiŝû gayra sâ`ah. keẕâlike kânû yü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'veḳâle-lleẕîne ûtü-l`ilme vel''îmâne leḳad lebiŝtüm fî kitâbi-llâhi ilâ yevmi-lba`ŝ. fehâẕâ yevmü-lba`ŝi velâkinneküm küntüm lâ ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'feyevmeiẕil lâ yenfe`u-lleẕîne żalemû ma`ẕiratühüm velâ hüm yüsta`tebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'veleḳad ḍarabnâ linnâsi fî hâẕe-lḳur''âni min külli meŝel. velein ci''tehüm biâyetil leyeḳûlenne-lleẕîne keferû in entüm illâ mübṭilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'keẕâlike yaṭbe`u-llâhü `alâ ḳulûbi-lleẕîne lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'faṣbir inne va`de-llâhi ḥaḳḳuv velâ yesteḫiffenneke-lleẕîne lâ yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'elif-lâm-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'tilke âyâtü-lkitâbi-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'hüdev veraḥmetel lilmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'elleẕîne yüḳîmûne-ṣṣalâte veyü''tûne-zzekâte vehüm bil''âḫirati hüm yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'ülâike `alâ hüdem mir rabbihim veülâike hümü-lmüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'vemine-nnâsi mey yeşterî lehve-lḥadîŝi liyüḍille `an sebîli-llâhi bigayri `ilmiv veyetteḫiẕehâ hüzüvâ. ülâike lehüm `aẕâbüm mühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'veiẕâ tütlâ `aleyhi âyâtünâ vellâ müstekbiran keel lem yesma`hâ keenne fî üẕüneyhi vaḳrâ. febeşşirhü bi`aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'inne-lleẕîne âmenû ve`amilu-ṣṣâliḥâti lehüm cennâtü-nne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'ḫâlidîne fîhâ. va`de-llâhi ḥaḳḳâ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'ḫaleḳa-ssemâvâti bigayri `amedin teravnehâ veelḳâ fi-l''arḍi ravâsiye en temîde biküm vebeŝŝe fîhâ min külli dâbbeh. veenzelnâ mine-ssemâi mâen feembetnâ fîhâ min külli zevcin kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'hâẕâ ḫalḳu-llâhi feerûnî mâẕâ ḫaleḳa-lleẕîne min dûnih. beli-żżâlimûne fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'veleḳad âteynâ luḳmâne-lḥikmete eni-şkür lillâh. vemey yeşkür feinnemâ yeşküru linefsih. vemen kefera feinne-llâhe ganiyyün ḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'veiẕ ḳâle luḳmânü libnihî vehüve ye`iżuhû yâ büneyye lâ tüşrik billâh. inne-şşirke leżulmün `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'veveṣṣayne-l''insâne bivâlideyh. ḥamelethü ümmühû vehnen `alâ vehniv vefiṣâlühû fî `âmeyni eni-şkür lî velivâlideyk. ileyye-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'vein câhedâke `alâ en tüşrike bî mâ leyse leke bihî `ilmün felâ tüṭi`hümâ veṣâḥibhümâ fi-ddünyâ ma`rûfâ. vettebi` sebîle men enâbe ileyy. ŝümme ileyye merci`uküm feünebbiüküm bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, 'yâ büneyye innehâ in tekü miŝḳâle ḥabbetim min ḫardelin fetekün fî ṣaḫratin ev fi-ssemâvâti ev fi-l''arḍi ye''ti bihe-llâh. inne-llâhe leṭîfün ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'yâ büneyye eḳimi-ṣṣalâte ve''mür bilma`rûfi venhe `ani-lmünkeri vaṣbir `alâ mâ eṣâbek. inne ẕâlike min `azmi-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'velâ tüṣa``ir ḫaddeke linnâsi velâ temşi fi-l''arḍi meraḥâ. inne-llâhe lâ yüḥibbü külle muḫtâlin feḫûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'vaḳṣid fî meşyike vagḍuḍ min ṣavtik. inne enkera-l''aṣvâti leṣavtü-lḥamîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'elem terav enne-llâhe seḫḫara leküm mâ fi-ssemâvâti vemâ fi-l''arḍi veesbega `aleyküm ni`amehû żâhiratev vebâṭineh. vemine-nnâsi mey yücâdilü fi-llâhi bigayri `ilmiv velâ hüdev velâ kitâbim münîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'veiẕâ ḳîle lehümü-ttebi`û mâ enzele-llâhü ḳâlû bel nettebi`u mâ vecednâ `aleyhi âbâenâ. evelev kâne-şşeyṭânü yed`ûhüm ilâ `aẕâbi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'vemey yüslim vechehû ile-llâhi vehüve muḥsinün feḳadi-stemseke bil`urveti-lvuŝḳâ. veile-llâhi `âḳibetü-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'vemen kefera felâ yaḥzünke küfruh. ileynâ merci`uhüm fenünebbiühüm bimâ `amilû. inne-llâhe `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'nümetti`uhüm ḳalîlen ŝümme naḍṭarruhüm ilâ `aẕâbin galîż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'velein seeltehüm men ḫaleḳa-ssemâvâti vel''arḍa leyeḳûlünne-llâh. ḳuli-lḥamdü lillâh. bel ekŝeruhüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'lillâhi mâ fi-ssemâvâti vel''arḍ. inne-llâhe hüve-lganiyyü-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'velev enne mâ fi-l''arḍi min şeceratin aḳlâmüv velbaḥru yemüddühû mim ba`dihî seb`atü ebḥurim mâ nefidet kelimâtü-llâh. inne-llâhe `azîzün ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'mâ ḫalḳuküm velâ ba`ŝüküm illâ kenefsiv vâḥideh. inne-llâhe semî`um beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'elem tera enne-llâhe yûlicü-lleyle fi-nnehâri veyûlicü-nnehâra fi-lleyli veseḫḫara-şşemse velḳamer. küllüy yecrî ilâ ecelim müsemmev veenne-llâhe bimâ ta`melûne ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'ẕâlike bienne-llâhe hüve-lḥaḳḳu veenne mâ yed`ûne min dûnihi-lbâṭili veenne-llâhe hüve-l`aliyyü-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'elem tera enne-lfülke tecrî fi-lbaḥri bini`meti-llâhi liyüriyeküm min âyâtih. inne fî ẕâlike leâyâtil likülli ṣabbârin şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'veiẕâ gaşiyehüm mevcün keżżuleli de`avu-llâhe muḫliṣîne lehü-ddîn. felemmâ neccâhüm ile-lberri feminhüm muḳteṣid. vemâ yecḥadü biâyâtinâ illâ küllü ḫattârin kefûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'yâ eyyühe-nnâsü-tteḳû rabbeküm vaḫşev yevmel lâ yeczî vâlidün `av veledihi. velâ mevlûdün hüve câzin `av vâlidihî şey''â. inne va`de-llâhi ḥaḳḳun felâ tegurrannekümü-lḥayâtü-ddünyâ. velâ yegurranneküm billâhi-lgarûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'inne-llâhe `indehû `ilmü-ssâ`ah. veyünezzilü-lgayŝ. veya`lemü mâ fi-l''erḥâm. vemâ tedrî nefsüm mâẕâ teksibü gadâ. vemâ tedrî nefsüm bieyyi arḍin temût. inne-llâhe `alîmün ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'elif-lâm-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'tenzîlü-lkitâbi lâ raybe fîhi mir rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'em yeḳûlûne-fterâh. bel hüve-lḥaḳḳu mir rabbike litünẕira ḳavmem mâ etâhüm min neẕîrim min ḳablike le`allehüm yehtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'allâhü-lleẕî ḫaleḳa-ssemâvâti vel''arḍa vemâ beynehümâ fî sitteti eyyâmin ŝümme-stevâ `ale-l`arş. mâ leküm min dûnihî miv veliyyiv velâ şefî`. efelâ teteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'yüdebbiru-l''emra mine-ssemâi ile-l''arḍi ŝümme ya`rucü ileyhi fî yevmin kâne miḳdâruhû elfe senetim mimmâ te`uddûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'ẕâlike `âlimü-lgaybi veşşehâdeti-l`azîzü-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, '-lleẕî aḥsene külle şey''in ḫaleḳahû vebedee ḫalḳa-l''insâni min ṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'ŝümme ce`ale neslehû min sülâletim mim mâim mehîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'ŝümme sevvâhü venefeḫa fîhi mir rûḥihî vece`ale lekümü-ssem`a vel''ebṣâra vel''ef''ideh. ḳalîlem mâ teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'veḳâlû eiẕâ ḍalelnâ fi-l''arḍi einnâ lefî ḫalḳin cedîd. bel hüm biliḳâi rabbihim kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'ḳul yeteveffâküm melekü-lmevti-lleẕî vukkile biküm ŝümme ilâ rabbiküm türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'velev terâ iẕi-lmücrimûne nâkisû ruûsihim `inde rabbihim. rabbenâ ebṣarnâ vesemi`nâ ferci`nâ na`mel ṣâliḥan innâ mûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'velev şi''nâ leâteynâ külle nefsin hüdâhâ velâkin ḥaḳḳa-lḳavlü minnî leemleenne cehenneme mine-lcinneti vennâsi ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, 'feẕûḳû bimâ nesîtüm liḳâe yevmiküm hâẕâ. innâ nesînâküm veẕûḳû `aẕâbe-lḫuldi bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'innemâ yü''minü biâyâtine-lleẕîne iẕâ ẕükkirû bihâ ḫarrû süccedev vesebbeḥû biḥamdi rabbihim vehüm lâ yestekbirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'tetecâfâ cünûbühüm `ani-lmeḍâci`i yed`ûne rabbehüm ḫavfev veṭame`â. vemimmâ razaḳnâhüm yünfiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'felâ ta`lemü nefsüm mâ uḫfiye lehüm min ḳurrati a`yün. cezâem bimâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'efemen kâne mü''minen kemen kâne fâsiḳâ. lâ yestevûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'emme-lleẕîne âmenû ve`amilu-ṣṣâliḥâti felehüm cennâtü-lme''vâ. nüzülem bimâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'veemme-lleẕîne feseḳû feme''vâhümü-nnâr. küllemâ erâdû ey yaḫrucû minhâ ü`îdû fîhâ veḳîle lehüm ẕûḳû `aẕâbe-nnâri-lleẕî küntüm bihî tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'velenüẕîḳannehüm mine-l`aẕâbi-l''ednâ dûne-l`aẕâbi-l''ekberi le`allehüm yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'vemen ażlemü mimmen ẕükkira biâyâti rabbihî ŝümme a`raḍa `anhâ. innâ mine-lmücrimîne münteḳimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'veleḳad âteynâ mûse-lkitâbe felâ tekün fî miryetim mil liḳâehi vece`alnâhü hüdel libenî isrâîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'vece`alnâ minhüm eimmetey yehdûne biemrinâ lemmâ ṣaberû. vekânû biâyâtinâ yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'inne rabbeke hüve yefṣilü beynehüm yevme-lḳiyâmeti fîmâ kânû fîhi yaḫtelifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'evelem yehdi lehüm kem ehleknâ min ḳablihim mine-lḳurûni yemşûne fî mesâkinihim. inne fî ẕâlike leâyât. efelâ yesme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'evelem yerav ennâ nesûḳu-lmâe ile-l''arḍi-lcüruzi fenuḫricü bihî zer`an te''külü minhü en`âmühüm veenfüsühüm. efelâ yübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'veyeḳûlûne metâ hâẕe-lfetḥu in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'ḳul yevme-lfetḥi lâ yenfe`u-lleẕîne keferû îmânühüm velâ hüm yünżarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'fea`riḍ `anhüm venteżir innehüm münteżirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'yâ eyyühe-nnebiyyü-tteḳi-llâhe velâ tüṭi`i-lkâfirîne velmünâfiḳîn. inne-llâhe kâne `alîmen ḥakîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'vettebi` mâ yûḥâ ileyke mir rabbik. inne-llâhe kâne bimâ ta`melûne ḫabîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'vetevekkel `ale-llâh. vekefâ billâhi vekîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'mâ ce`ale-llâhü liracülim min ḳalbeyni fî cevfih. vemâ ce`ale ezvâcekümü-llâî tüżâhirûne minhünne ümmehâtiküm. vemâ ce`ale ed`iyâeküm ebnâeküm. ẕâliküm ḳavlüküm biefvâhiküm. vellâhü yeḳûlü-lḥaḳḳa vehüve yehdi-ssebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'üd`ûhüm liâbâihim hüve aḳseṭu `inde-llâh. feil lem ta`lemû âbâehüm feiḫvânüküm fi-ddîni vemevâlîküm. veleyse `aleyküm cünâḥun fîmâ aḫṭa''tüm bihî velâkim mâ te`ammedet ḳulûbüküm. vekâne-llâhü gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'ennebiyyü evlâ bilmü''minîne min enfüsihim veezvâcühû ümmehâtühüm. veülü-l''erḥâmi ba`ḍuhüm evlâ biba`ḍin fî kitâbi-llâhi mine-lmü''minîne velmühâcirîne illâ en tef`alû ilâ evliyâiküm ma`rûfâ. kâne ẕâlike fi-lkitâbi mesṭûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'veiẕ eḫaẕnâ mine-nnebiyyîne mîŝâḳahüm veminke vemin nûḥiv veibrâhime vemûsâ ve`îse-bni meryem. veeḫaẕnâ minhüm mîŝâḳan galîżâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'liyes''ele-ṣṣâdiḳîne `an ṣidḳihim. vee`adde lilkâfirîne `aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'yâ eyyühe-lleẕîne âmenü-ẕkürû ni`mete-llâhi `aleyküm iẕ câetküm cünûdün feerselnâ `aleyhim rîḥav vecünûdel lem teravhâ. vekâne-llâhü bimâ ta`melûne beṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'iẕ câûküm min fevḳiküm vemin esfele minküm veiẕ zâgati-l''ebṣâru vebelegati-lḳulûbü-lḥanâcira veteżunnûne billâhi-żżunûnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'hünâlike-btüliye-lmü''minûne vezülzilû zilzâlen şedîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'veiẕ yeḳûlü-lmünâfiḳûne velleẕîne fî ḳulûbihim meraḍum mâ ve`adene-llâhü verasûlühû illâ gurûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'veiẕ ḳâleṭ ṭâifetüm minhüm yâ ehle yeŝribe lâ müḳâme leküm ferci`û. veyeste''ẕinü ferîḳum minhümü-nnebiyye yeḳûlûne inne büyûtenâ `avratüv vemâ hiye bi`avrah. iy yürîdûne illâ firârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'velev düḫilet `aleyhim min aḳṭârihâ ŝümme süilü-lfitnete leetevhâ vemâ telebbeŝû bihâ illâ yesîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'veleḳad kânû `âhedü-llâhe min ḳablü lâ yüvellûne-l''edbâr. vekâne `ahdü-llâhi mes''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'ḳul ley yenfe`akümü-lfirâru in ferartüm mine-lmevti evi-lḳatli veiẕel lâ tümette`ûne illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'ḳul men ẕe-lleẕî ya`ṣimüküm mine-llâhi in erâde biküm sûen ev erâde biküm raḥmeh. velâ yecidûne lehüm min dûni-llâhi veliyyev velâ neṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'ḳad ya`lemü-llâhü-lmü`avviḳîne minküm velḳâilîne liiḫvânihim helümme ileynâ. velâ ye''tûne-lbe''se illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, 'eşiḥḥaten `aleyküm. feiẕâ câe-lḫavfü raeytehüm yenżurûne ileyke tedûru a`yünühüm kelleẕî yugşâ `aleyhi mine-lmevt. feiẕâ ẕehebe-lḫavfü seleḳûküm bielsinetin ḥidâdin eşiḥḥaten `ale-lḫayr. ülâike lem yü''minû feaḥbeṭa-llâhü a`mâlehüm. vekâne ẕâlike `ale-llâhi yesîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, 'yaḥsebûne-l''aḥzâbe lem yeẕhebû. veiy ye''ti-l''aḥzâbü yeveddû lev ennehüm bâdûne fi-l''a`râbi yes''elûne `an embâiküm. velev kânû fîküm mâ ḳâtelû illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'leḳad kâne leküm fî rasûli-llâhi üsvetün ḥasenetül limen kâne yercü-llâhe velyevme-l''âhira veẕekera-llâhe keŝîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'velemmâ rae-lmü''minûne-l''aḥzâbe ḳâlû hâẕâ mâ ve`adene-llâhü verasûlühû veṣadeḳa-llâhü verasûlüh. vemâ zâdehüm illâ îmânev veteslîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'mine-lmü''minîne ricâlün ṣadeḳû mâ `âhedü-llâhe `aleyh. feminhüm men ḳaḍâ naḥbehû veminhüm mey yenteżir. vemâ beddelû tebdîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'liyecziye-llâhu-ṣṣâdiḳîne biṣidḳihim veyü`aẕẕibe-lmünâfiḳîne in şâe ev yetûbe `aleyhim. inne-llâhe kâne gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'veradde-llâhü-lleẕîne keferû bigayżihim lem yenâlû ḫayrâ. vekefe-llâhü-lmü''minîne-lḳitâl. vekâne-llâhü ḳaviyyen `azîzâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'veenzele-lleẕîne żâherûhüm min ehli-lkitâbi min ṣayâṣîhim veḳaẕefe fî ḳulûbihimü-rru`be ferîḳan taḳtülûne vete''sirûne ferîḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'veevraŝeküm arḍahüm vediyârahüm veemvâlehüm vearḍal lem teṭaûhâ. vekâne-llâhü `alâ külli şey''in ḳadîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'yâ eyyühe-nnebiyyü ḳul liezvâcike in küntünne türidne-lḥayâte-ddünyâ vezînetehâ fete`âleyne ümetti`künne veüserriḥkünne serâḥan cemîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'vein küntünne türidne-llâhe verasûlehû veddâra-l''âḫirate feinne-llâhe e`adde lilmuḥsinâti minkünne ecran `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'yâ nisâe-nnebiyyi mey ye''ti minkünne bifâḥişetim mübeyyinetiy yüḍâ`af lehe-l`aẕâbü ḍi`feyn. vekâne ẕâlike `ale-llâhi yesîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'vemey yaḳnüt minkünne lillâhi verasûlihî veta`mel ṣâliḥan nü''tihâ ecrahâ merrateyni vea`tednâ lehâ rizḳan kerîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'yâ nisâe-nnebiyyi lestünne keeḥadim mine-nnisâi ini-tteḳaytünne felâ taḫḍa`ne bilḳavli feyaṭme`a-lleẕî fî ḳalbihî meraḍuv veḳulne ḳavlem ma`rûfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'veḳarne fî büyûtikünne velâ teberracne teberruce-lcâhiliyyeti-l''ûlâ veeḳimne-ṣṣalâte veâtîne-zzekâte veeṭi`ne-llâhe verasûleh. innemâ yürîdü-llâhü liyüẕhibe `ankümü-rricse ehle-lbeyti veyüṭahhiraküm taṭhîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'veẕkürne mâ yütlâ fî büyûtikünne min âyâti-llâhi velḥikmeh. inne-llâhe kâne leṭîfen ḫabîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'inne-lmüslimîne velmüslimâti velmü''minîne velmü''minâti velḳânitîne velḳânitâti veṣṣâdiḳîne veṣṣâdiḳâti veṣṣâbirîne veṣṣâbirâti velḫâşi`îne velḫâşi`âti velmüteṣaddiḳîne velmüteṣaddiḳâti veṣṣâimîne veṣṣâimâti velḥâfiżîne fürûcehüm velḥâfiżâti veẕẕâkirîne-llâhe keŝîrav veẕẕâkirâti e`adde-llâhü lehüm magfiratev veecran `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'vemâ kâne limü''miniv velâ mü''minetin iẕâ ḳaḍa-llâhü verasûlühû emran ey yekûne lehümü-lḫiyeratü min emrihim. vemey ya`ṣi-llâhe verasûlehû feḳad ḍalle ḍalâlem mübînâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'veiẕ teḳûlü lilleẕî en`ame-llâhü `aleyhi veen`amte `aleyhi emsik `aleyke zevceke vetteḳi-llâhe vetuḫfî fî nefsike me-llâhü mübdîhi vetaḫşe-nnâs. vellâhü eḥaḳḳu en taḫşâh. felemmâ ḳaḍâ zeydüm minhâ veṭaran zevvecnâkehâ likey lâ yekûne `ale-lmü''minîne ḥaracün fî ezvâci ed`iyâihim iẕâ ḳaḍav minhünne veṭarâ. vekâne emru-llâhi mef`ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'mâ kâne `ale-nnebiyyi min ḥaracin fîmâ feraḍa-llâhü leh. sünnete-llâhi fi-lleẕîne ḫalev min ḳabl. vekâne emru-llâhi ḳaderam maḳdûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'elleẕîne yübelligûne risâlâti-llâhi veyaḫşevnehû velâ yaḫşevne eḥaden ille-llâh. vekefâ billâhi ḥasîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'mâ kâne müḥammedün ebâ eḥadim mir ricâliküm velâkir rasûle-llâhi veḫâteme-nnebiyyîn. vekâne-llâhü bikülli şey''in `alîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'yâ eyyühe-lleẕîne âmenü-ẕkürü-llâhe ẕikran keŝîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'vesebbiḥûhü bükratev veeṣîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'hüve-lleẕî yüṣallî `aleyküm vemelâiketühû liyuḫriceküm mine-żżulümâti ile-nnûr. vekâne bilmü''minîne raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'teḥiyyetühüm yevme yelḳavnehû selâm. vee`adde lehüm ecran kerîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'yâ eyyühe-nnebiyyü innâ erselnâke şâhidev vemübeşşirav veneẕîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'vedâ`iyen ile-llâhi biiẕnihî vesirâcem münîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'vebeşşiri-lmü''minîne bienne lehüm mine-llâhi faḍlen kebîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'velâ tüṭi`i-lkâfirîne velmünâfiḳîne veda` eẕâhüm vetevekkel `ale-llâh. vekefâ billâhi vekîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'yâ eyyühe-lleẕîne âmenû iẕâ nekaḥtümü-lmü''minâti ŝümme ṭallaḳtümûhünne min ḳabli en temessûhünne femâ leküm `aleyhinne min `iddetin ta`teddûnehâ. femetti`ûhünne veserriḥûhünne serâḥan cemîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'yâ eyyühe-nnebiyyü innâ aḥlelnâ leke ezvâceke-llâtî âteyte ücûrahünne vemâ meleket yemînüke mimmâ efâe-llâhü `aleyke vebenâti `ammike vebenâti `ammetike vebenâti ḫâlike vebenâti ḫâletike-llâtî hâcerne me`ak. vemraetem mü''mineten iv vehebet nefsehâ linnebiyyi in erâde-nnebiyyü ey yestenkiḥahâ. ḫâliṣatel leke min dûni-lmü''minîn. ḳad `alimnâ mâ feraḍnâ `aleyhim fî ezvâcihim vemâ meleket eymânühüm likeylâ yekûne `aleyke ḥarac. vekâne-llâhü gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'türcî men teşâü minhünne vetü''vî ileyke men teşâ''. vemeni-btegayte mimmen `azelte felâ cünâḥa `aleyk. ẕâlike ednâ en teḳarra a`yünühünne velâ yaḥzenne veyerḍayne bimâ âteytehünne küllühünn. vellâhü ya`lemü mâ fî ḳulûbiküm. vekâne-llâhü `alîmen ḥalîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'lâ yeḥillü leke-nnisâü mim ba`dü velâ en tebeddele bihinne min ezvâciv velev a`cebeke ḥusnühünne illâ mâ meleket yemînük. vekâne-llâhü `alâ külli şey''ir raḳîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'yâ eyyühe-lleẕîne âmenû lâ tedḫulû büyûte-nnebiyyi illâ ey yü''ẕene leküm ilâ ṭa`âmin gayra nâżirîne inâhü velâkin iẕâ dü`îtüm fedḫulû feiẕâ ṭa`imtüm fenteşirû velâ müste''nisîne liḥadîŝ. inne ẕâliküm kâne yü''ẕi-nnebiyye feyestaḥyî minküm. vellâhü lâ yestaḥyî mine-lḥaḳḳ. veiẕâ seeltümûhünne metâ`an fes''elûhünne miv verâi ḥicâb. ẕâliküm aṭheru liḳulûbiküm veḳulûbihinn. vemâ kâne leküm en tü''ẕû rasûle-llâhi velâ en tenkiḥû ezvâcehû mim ba`dihî ebedâ. inne ẕâliküm kâne `inde-llâhi `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'in tübdû şey''en ev tuḫfûhü feinne-llâhe kâne bikülli şey''in `alîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'lâ cünâḥa `aleyhinne fî âbâihinne velâ ebnâihinne velâ iḫvânihinne velâ ebnâi iḫvânihinne velâ ebnâi eḫavâtihinne velâ nisâihinne velâ mâ meleket eymânühünn. vetteḳîne-llâh. inne-llâhe kâne `alâ külli şey''in şehîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'inne-llâhe vemelâiketehû yüṣallûne `ale-nnebiyy. yâ eyyühe-lleẕîne âmenû ṣallû `aleyhi vesellimû teslîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'inne-lleẕîne yü''ẕûne-llâhe verasûlehû le`anehümü-llâhü fi-ddünyâ vel''âḫirati vee`adde lehüm `aẕâbem mühînâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'velleẕîne yü''ẕûne-lmü''minîne velmü''minâti bigayri me-ktesebû feḳadi-ḥtemelû bühtânev veiŝmem mübînâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'yâ eyyühe-nnebiyyü ḳul liezvâcike vebenâtike venisâi-lmü''minîne yüdnîne `aleyhinne min celâbîbihinn. ẕâlike ednâ ey yü`rafne felâ yü''ẕeyn. vekâne-llâhü gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'leil lem yentehi-lmünâfiḳûne velleẕîne fî ḳulûbihim meraḍuv velmürcifûne fi-lmedîneti lenugriyenneke bihim ŝümme lâ yücâvirûneke fîhâ illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'mel`ûnîn. eyne mâ ŝüḳifû üḫiẕû veḳuttilû taḳtîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'sünnete-llâhi fi-lleẕîne ḫalev min ḳabl. velen tecide lisünneti-llâhi tebdîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'yes''elüke-nnâsü `ani-ssâ`ah. ḳul innemâ `ilmühâ `inde-llâh. vemâ yüdrîke le`alle-ssâ`ate tekûnü ḳarîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'inne-llâhe le`ane-lkâfirîne vee`adde lehüm se`îrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'ḫâlidîne fîhâ ebedâ. lâ yecidûne veliyyev velâ neṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'yevme tüḳallebü vucûhühüm fi-nnâri yeḳûlûne yâ leytenâ eṭa`ne-llâhe veeṭa`ne-rrasûl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'veḳâlû rabbenâ innâ eṭa`nâ sâdetenâ veküberâenâ feeḍallûne-ssebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'rabbenâ âtihim ḍi`feyni mine-l`aẕâbi vel`anhüm la`nen kebîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'yâ eyyühe-lleẕîne âmenû lâ tekûnû kelleẕîne âẕev mûsâ feberra''ehü-llâhü mimmâ ḳâlû. vekâne `inde-llâhi vecîhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'yâ eyyühe-lleẕîne âmenü-tteḳu-llâhe veḳûlû ḳavlen sedîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'yuṣliḥ leküm a`mâleküm veyagfir leküm ẕünûbeküm. vemey yüṭi`i-llâhe verasûlehû feḳad fâze fevzen `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'innâ `araḍne-l''emânete `ale-ssemâvâti vel''arḍi velcibâli feebeynâ ey yaḥmilnehâ veeşfaḳne minhâ veḥamelehe-l''insân. innehû kâne żalûmen cehûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'liyü`aẕẕibe-llâhü-lmünâfiḳîne velmünâfiḳâti velmüşrikîne velmüşrikâti veyetûbe-llâhü `ale-lmü''minîne velmü''minât. vekâne-llâhü gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'elḥamdü lillâhi-lleẕî lehû mâ fi-ssemâvâti vemâ fi-l''arḍi velehü-lḥamdü fi-l''âḫirah. vehüve-lḥakîmü-lḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'ya`lemü mâ yelicü fi-l''arḍi vemâ yaḫrucü minhâ vemâ yenzilü mine-ssemâi vemâ ya`rucü fîhâ. vehüve-rraḥîmü-lgafûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'veḳâle-lleẕîne keferû lâ te''tîne-ssâ`ah. ḳul belâ verabbî lete''tiyenneküm `âlimi-lgaybi. lâ ya`zübü `anhü miŝḳâlü ẕerratin fi-ssemâvâti velâ fi-l''arḍi velâ aṣgaru min ẕâlike velâ ekberu illâ fî kitâbim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'liyecziye-lleẕîne âmenû ve`amilu-ṣṣâliḥâti. ülâike lehüm magfiratüv verizḳun kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'velleẕîne se`av fî âyâtinâ mü`âcizîne ülâike lehüm `aẕâbüm mir riczin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'veyere-lleẕîne ûtü-l`ilme-lleẕî ünzile ileyke mir rabbike hüve-lḥaḳḳa veyehdî ilâ ṣirâṭi-l`azîzi-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'veḳâle-lleẕîne keferû hel nedüllüküm `alâ racüliy yünebbiüküm iẕâ müzziḳtüm külle mümezzeḳin inneküm lefî ḫalḳin cedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'efterâ `ale-llâhi keẕiben em bihî cinneh. beli-lleẕîne lâ yü''minûne bil''âḫirati fi-l`aẕâbi veḍḍalâli-lbe`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'efelem yerav ilâ mâ beyne eydîhim vemâ ḫalfehüm mine-ssemâi vel''arḍ. in neşe'' naḫsif bihimü-l''arḍa ev nüsḳiṭ `aleyhim kisefem mine-ssemâ''. inne fî ẕâlike leâyetel likülli `abdim münîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'veleḳad âteynâ dâvûde minnâ faḍlâ. yâ cibâlü evvibî me`ahû veṭṭayr. veelennâ lehü-lḥadîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, 'eni-`mel sâbigâtiv veḳaddir fi-sserdi va`melû ṣâliḥâ. innî bimâ ta`melûne beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'velisüleymâne-rrîḥa gudüvvuhâ şehruv veravâḥuhâ şehr. veeselnâ lehû `ayne-lḳiṭr. vemine-lcinni mey ya`melü beyne yedeyhi biiẕni rabbihî. vemey yezig minhüm `an emrinâ nüẕiḳhü min `aẕâbi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'ya`melûne lehû mâ yeşâü mim meḥârîbe vetemâŝîle vecifânin kelcevâbi veḳudûrir râsiyât. i`melû âle dâvûde şükrâ. veḳalîlüm min `ibâdiye-şşekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'felemmâ ḳaḍaynâ `aleyhi-lmevte mâ dellehüm `alâ mevtih illâ dâbbetü-l''arḍi te''külü minseeteh. felemmâ ḫarra tebeyyeneti-lcinnü el lev kânû ya`lemûne-lgaybe mâ lebiŝû fi-l`aẕâbi-lmühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'leḳad kâne lisebein fî meskenihim âyeh. cennetâni `ay yemîniv veşimâl. külû mir rizḳi rabbiküm veşkürû leh. beldetün ṭayyibetüv verabbün gafûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'fea`raḍû feerselnâ `aleyhim seyle-l`arimi vebeddelnâhüm bicenneteyhim cenneteyni ẕevâtey ükülin ḫamṭiv veeŝliv veşey''im min sidrin ḳalîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'ẕâlike cezeynâhüm bimâ keferû. vehel nücezî ille-lkefûra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'vece`alnâ beynehüm vebeyne-lḳura-lletî bâraknâ fîhâ ḳuran żâhiratev veḳaddernâ fîhe-sseyr. sîrû fîhâ leyâliye veeyyâmen âminîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'feḳâlû rabbenâ bâ`id beyne esfârinâ veżalemû enfüsehüm fece`alnâhüm eḥâdîŝe vemezzaḳnâhüm külle mümezzeḳ. inne fî ẕâlike leâyâtil likülli ṣabbârin şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'veleḳad ṣaddeḳa `aleyhim iblîsü żannehû fettebe`ûhü illâ ferîḳam mine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'vemâ kâne lehû `aleyhim min sülṭânin illâ lina`leme mey yü''minü bil''âḫirati mimmen hüve minhâ fî şekkin. verabbüke `alâ külli şey''in ḥafîż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'ḳuli-d`ü-lleẕîne za`amtüm min dûni-llâh. lâ yemlikûne miŝḳâle ẕerratin fi-ssemâvâti velâ fi-l''arḍi vemâ lehüm fîhimâ min şirkiv vemâ lehû minhüm min żahîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'velâ tenfe`u-şşefâ`atü `indehû illâ limen eẕine leh. ḥattâ iẕâ füzzi`a `an ḳulûbihim ḳâlû mâẕâ ḳâle rabbüküm. ḳâlü-lḥaḳḳ. vehüve-l`aliyyü-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'ḳul mey yerzüḳuküm mine-ssemâvâti vel''arḍ. ḳuli-llâhü veinnâ ev iyyâküm le`alâ hüden ev fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'ḳul lâ tüs''elûne `ammâ ecramnâ velâ nüs''elü `ammâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'ḳul yecme`u beynenâ rabbünâ ŝümme yefteḥu beynenâ bilḥaḳḳ. vehüve-lfettâḥu-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'ḳul erûniye-lleẕîne elḥaḳtüm bihî şürakâe kellâ. bel hüve-llâhü-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'vemâ erselnâke illâ kâffetel linnâsi beşîrav veneẕîrav velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'veyeḳûlûne metâ hâẕe-lva`dü in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'ḳul leküm mî`âdü yevmil lâ teste''ḫirûne `anhü sâ`atev velâ testaḳdimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'veḳâle-lleẕîne keferû len nü''mine bihâẕe-lḳur''âni velâ billeẕî beyne yedeyh. velev terâ iẕi-żżâlimûne mevḳûfûne `inde rabbihim. yerci`u ba`ḍuhüm ilâ ba`ḍin-lḳavle. yeḳûlü-lleẕîne-stuḍ`ifû lilleẕîne-stekberû levlâ entüm lekünnâ mü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'ḳâle-lleẕîne-stekberû lilleẕîne-stuḍ`ifû enaḥnü ṣadednâküm `ani-lhüdâ ba`de iẕ câeküm bel küntüm mücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'veḳâle-lleẕîne-stuḍ`ifû lilleẕîne-stekberû bel mekru-lleyli vennehâri iẕ te''mürûnenâ en nekfüra billâhi venec`ale lehû endâdâ. veeserrü-nnedâmete lemmâ raevu-l`aẕâb. vece`alne-l''aglâle fî a`nâḳi-lleẕîne keferû. hel yüczevne illâ mâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'vemâ erselnâ fî ḳaryetim min neẕîrin illâ ḳâle mütrafûhâ innâ bimâ ürsiltüm bihî kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'veḳâlû naḥnü ekŝeru emvâlev veevlâdev vemâ naḥnü bimü`aẕẕebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'ḳul inne rabbî yebsüṭu-rrizḳa limey yeşâü veyaḳdiru velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'vemâ emvâlüküm velâ evlâdüküm billetî tüḳarribüküm `indenâ zülfâ illâ men âmene ve`amile ṣâliḥâ. feülâike lehüm cezâu-ḍḍi`fi bimâ `amilû vehüm fi-lgurufâti âminûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'velleẕîne yes`avne fî âyâtinâ mü`âcizîne ülâike fi-l`aẕâbi muḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'ḳul inne rabbî yebsüṭu-rrizḳa limey yeşâü min `ibâdihî veyaḳdiru leh. vemâ enfaḳtüm min şey''in fehüve yuḫlifüh. vehüve ḫayru-rrâziḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'veyevme yaḥşüruhüm cemî`an ŝümme yeḳûlü lilmelâiketi ehâülâi iyyâküm kânû ya`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'ḳâlû sübḥâneke ente veliyyünâ min dûnihim. bel kânû ya`büdûne-lcinn. ekŝeruhüm bihim mü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'felyevme lâ yemlikü ba`ḍuküm liba`ḍin nef`av velâ ḍarrâ. veneḳûlü lilleẕîne żalemû ẕûḳû `aẕâbe-nnâri-lletî küntüm bihâ tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'veiẕâ tütlâ `aleyhim âyâtünâ beyyinâtin ḳâlû mâ hâẕâ illâ racülüy yürîdü ey yeṣuddeküm `ammâ kâne ya`büdü âbâüküm. veḳâlû mâ hâẕâ illâ ifküm müfterâ. veḳâle-lleẕîne keferû lilḥaḳḳi lemmâ câehüm in hâẕâ illâ siḥrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'vemâ âteynâhüm min kütübiy yedrusûnehâ vemâ erselnâ ileyhim ḳableke min neẕîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'vekeẕẕebe-lleẕîne min ḳablihim vemâ belegû mi`şâra mâ âteynâhüm fekeẕẕebû rusülî. fekeyfe kâne nekîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'ḳul innemâ e`iżuküm bivâḥideh. en teḳûmû lillâhi meŝnâ vefürâdâ ŝümme tetefekkerû. mâ biṣâḥibiküm min cinneh. in hüve illâ neẕîrul leküm beyne yedey `aẕâbin şedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'ḳul mâ seeltüküm min ecrin fehüve leküm. in ecriye illâ `ale-llâh. vehüve `alâ külli şey''in şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'ḳul inne rabbî yaḳẕifü bilḥaḳḳ. `allâmü-lguyûb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'ḳul câe-lḥaḳḳu vemâ yübdiü-lbâṭilü vemâ yü`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'ḳul in ḍaleltü feinnemâ eḍillü `alâ nefsî. veini-htedeytü febimâ yûḥî ileyye rabbî. innehû semî`un ḳarîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'velev terâ iẕ fezi`û felâ fevte veüḫiẕû mim mekânin ḳarîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'veḳâlû âmennâ bih. veennâ lehümü-ttenâvuşü mim mekânim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'veḳad keferû bihî min ḳabl. veyaḳẕifûne bilgaybi mim mekânim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'veḥîle beynehüm vebeyne mâ yeştehûne kemâ fu`ile bieşyâ`ihim min ḳabl. innehüm kânû fî şekkim mürîbün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'elḥamdü lillâhi fâṭiri-ssemâvâti vel''arḍi câ`ili-lmelâiketi rusülen ülî ecniḥatim meŝnâ veŝülâŝe verubâ`. yezîdü fi-lḫalḳi mâ yeşâ''. inne-llâhe `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'mâ yefteḥi-llâhü linnâsi mir raḥmetin felâ mümsike lehâ. vemâ yümsik felâ mürsile lehû mim ba`dih. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'yâ eyyühe-nnâsü-ẕkürû ni`mete-llâhi `aleyküm. hel min ḫâliḳin gayru-llâhi yerzüḳuküm mine-ssemâi vel''arḍ. lâ ilâhe illâ hû. feennâ tü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'veiy yükeẕẕibûke feḳad küẕẕibet rusülüm min ḳablik. veile-llâhi türce`u-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'yâ eyyühe-nnâsü inne va`de-llâhi ḥaḳḳun felâ tegurrannekümü-lḥayâtü-ddünyâ. velâ yegurranneküm billâhi-lgarûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'inne-şşeyṭâne leküm `adüvvün fetteḫiẕûhü `adüvvâ. innemâ yed`û ḥizbehû liyekûnû min aṣḥâbi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'elleẕîne keferû lehüm `aẕâbün şedîd. velleẕîne âmenû ve`amilu-ṣṣâliḥâti lehüm magfiratüv veecrun kebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'efemen züyyine lehû sûü `amelihî feraâhü ḥasenâ. feinne-llâhe yüḍillü mey yeşâü veyehdî mey yeşâ''. felâ teẕheb nefsüke `aleyhim ḥaserât. inne-llâhe `alîmüm bimâ yaṣne`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'vellâhü-lleẕî ersele-rriyâḥa fetüŝîru seḥâben fesuḳnâhü ilâ beledim meyyitin feaḥyeynâ bihi-l''arḍa ba`de mevtihâ. keẕâlike-nnüşûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'men kâne yürîdü-l`izzete felillâhi-l`izzetü cemî`â. ileyhi yaṣ`adü-lkelimu-ṭṭayyibü vel`amelu-ṣṣâliḥu yerfe`uh. velleẕîne yemkürûne-sseyyiâti lehüm `aẕâbün şedîd. vemekru ülâike hüve yebûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'vellâhü ḫaleḳaküm min türâbin ŝümme min nuṭfetin ŝümme ce`aleküm ezvâcâ. vemâ taḥmilü min ünŝâ velâ teḍa`u illâ bi`ilmih. vemâ yü`ammeru mim mü`ammeriv velâ yünḳaṣu min `umürihî illâ fî kitâb. inne ẕâlike `ale-llâhi yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'vemâ yestevi-lbaḥrân. hâẕâ `aẕbün fürâtün sâigun şerâbühû vehâẕâ milḥun ücâc. vemin küllin te''külûne laḥmen ṭariyyev vetestaḫricûne ḥilyeten telbesûnehâ. vetera-lfülke fîhi mevâḫira litebtegû min faḍlihî vele`alleküm teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'yûlicü-lleyle fi-nnehâri veyûlicü-nnehâra fi-lleyli veseḫḫara-şşemse velḳamer. küllüy yecrî liecelim müsemmâ. ẕâlikümü-llâhü rabbüküm lehü-lmülk. velleẕîne ted`ûne min dûnihî mâ yemlikûne min ḳiṭmîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'in ted`ûhüm lâ yesme`û dü`âeküm. velev semi`û me-stecâbû leküm. veyevme-lḳiyâmeti yekfürûne bişirkiküm. velâ yünebbiüke miŝlü ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'yâ eyyühe-nnâsü entümü-lfüḳarâü ile-llâh. vellâhü hüve-lganiyyü-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'iy yeşe'' yüẕhibküm veye''ti biḫalḳin cedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'vemâ ẕâlike `ale-llâhi bi`azîz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'velâ teziru vâziratüv vizra uḫrâ. vein ted`u müŝḳaletün ilâ ḥimlihâ lâ yuḥmel minhü şey''üv velev kâne ẕâ ḳurbâ. innemâ tünẕiru-lleẕîne yaḫşevne rabbehüm bilgaybi veeḳâmu-ṣṣalâh. vemen tezekkâ feinnemâ yetezekkâ linefsih. veile-llâhi-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'vemâ yestevi-l''a`mâ velbeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'vele-żżulümâtü vele-nnûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'vele-żżillü vele-lḥarûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'vemâ yestevi-l''aḥyâü vele-l''emvât. inne-llâhe yüsmi`u mey yeşâ''. vemâ ente bimüsmi`im men fi-lḳubûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'in ente illâ neẕîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'innâ erselnâke bilḥaḳḳi beşîrav veneẕîrâ. veim min ümmetin illâ ḫalâ fîhâ neẕîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'veiy yükeẕẕibûke feḳad keẕẕebe-lleẕîne min ḳablihim. câethüm rusülühüm bilbeyyinâti vebizzübüri vebilkitâbi-lmünîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'ŝümme eḫaẕtü-lleẕîne keferû fekeyfe kâne nekîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'elem tera enne-llâhe enzele mine-ssemâi mââ. feaḫracnâ bihî ŝemerâtim muḫtelifen elvânühâ. vemine-lcibâli cüdedüm bîḍuv veḥumrum muḫtelifün elvânühâ vegarâbîbü sûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'vemine-nnâsi veddevâbbi vel''en`âmi muḫtelifün elvânühû keẕâlik. innemâ yaḫşe-llâhe min `ibâdihi-l`ulemâ''. inne-llâhe `azîzün gafûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'inne-lleẕîne yetlûne kitâbe-llâhi veeḳâmu-ṣṣalâte veenfeḳû mimmâ razaḳnâhüm sirrav ve`alâniyetey yercûne ticâratel len tebûra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'liyüveffiyehüm ücûrahüm veyezîdehüm min faḍlih. innehû gafûrun şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'velleẕî evḥaynâ ileyke mine-lkitâbi hüve-lḥaḳḳu müṣaddiḳal limâ beyne yedeyh. inne-llâhe bi`ibâdihî leḫabîrum beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'ŝümme evraŝne-lkitâbe-lleẕîne-ṣṭafeynâ min `ibâdinâ. feminhüm żâlimül linefsih. veminhüm muḳteṣid. veminhüm sâbiḳum bilḫayrâti biiẕni-llâh. ẕâlike hüve-lfaḍlü-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'cennâtü `adniy yedḫulûnehâ yüḥallevne fîhâ min esâvira min ẕehebiv velü''lüâ. velibâsühüm fîhâ ḥarîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'veḳâlü-lḥamdü lillâhi-lleẕî eẕhebe `anne-lḥazen. inne rabbenâ legafûrun şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'elleẕî eḥallenâ dâra-lmüḳâmeti min faḍlih. lâ yemessünâ fîhâ neṣabüv velâ yemessünâ fîhâ lügûb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'velleẕîne keferû lehüm nâru cehennem. lâ yuḳḍâ `aleyhim feyemûtû velâ yüḫaffefü `anhüm min `aẕâbihâ. keẕâlike neczî külle kefûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'vehüm yaṣṭariḫûne fîhâ. rabbenâ aḫricnâ na`mel ṣâliḥan gayra-lleẕî künnâ na`mel. evelem nü`ammirküm mâ yeteẕekkeru fîhi men teẕekkera vecâekümü-nneẕîr. feẕûḳû femâ liżżâlimîne min neṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'inne-llâhe `âlimü gaybi-ssemâvâti vel''arḍ. innehû `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'hüve-lleẕî ce`aleküm ḫalâife fi-l''arḍ. femen kefera fe`aleyhi küfruh. velâ yezîdü-lkâfirîne küfruhüm `inde rabbihim illâ maḳtâ. velâ yezîdü-lkâfirîne küfruhüm illâ ḫasârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'ḳul era''eytüm şürakâekümü-lleẕîne ted`ûne min dûni-llâh. erûnî mâẕâ ḫaleḳû mine-l''arḍi em lehüm şirkün fi-ssemâvât. em âteynâhüm kitâben fehüm `alâ beyyinetim minh. bel iy ye`idu-żżâlimûne ba`ḍuhüm ba`ḍan illâ gurûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'inne-llâhe yümsikü-ssemâvâti vel''arḍa en tezûlâ. velein zâletâ in emsekehümâ min eḥadim mim ba`dih. innehû kâne ḥalîmen gafûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'veaḳsemû billâhi cehde eymânihim lein câehüm neẕîrul leyekûnünne ehdâ min iḥde-l''ümem. felemmâ câehüm neẕîrum mâ zâdehüm illâ nüfûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'istikbâran fi-l''arḍi vemekra-sseyyi''. velâ yeḥîḳu-lmekru-sseyyiü illâ biehlih. fehel yenżurûne illâ sünnete-l''evvelîn. felen tecide lisünneti-llâhi tebdîlâ. velen tecide lisünneti-llâhi taḥvîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'evelem yesîrû fi-l''arḍi feyenżurû keyfe kâne `âḳibetü-lleẕîne min ḳablihim vekânû eşedde minhüm ḳuvveh. vemâ kâne-llâhü liyü`cizehû min şey''in fi-ssemâvâti velâ fi-l''arḍ. innehû kâne `alîmen ḳadîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'velev yüâḫiẕü-llâhü-nnâse bimâ kesebû mâ terake `alâ żahrihâ min dâbbetiv velâkiy yü''eḫḫiruhüm ilâ ecelim müsemmâ. feiẕâ câe ecelühüm feinne-llâhe kâne bi`ibâdihî beṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'yâ-sîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, 'velḳur''âni-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'inneke lemine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, '`alâ ṣirâṭim müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'tenzîle-l`azîzi-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'litünẕira ḳavmem mâ ünẕira âbâühüm fehüm gâfilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'leḳad ḥaḳḳa-lḳavlü `alâ ekŝerihim fehüm lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'innâ ce`alnâ fî a`nâḳihim aglâlen fehiye ile-l''eẕḳâni fehüm muḳmeḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'vece`alnâ mim beyni eydîhim seddev vemin ḫalfihim sedden feagşeynâhüm fehüm lâ yübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'vesevâün `aleyhim eenẕertehüm em lem tünẕirhüm lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'innemâ tünẕiru meni-ttebe`a-ẕẕikra veḫaşiye-rraḥmâne bilgayb. febeşşirhü bimagfirativ veecrin kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'innâ naḥnü nuḥyi-lmevtâ venektübü mâ ḳaddemû veâŝârahüm. vekülle şey''in aḥṣaynâhü fî imâmim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'vaḍrib lehüm meŝelen aṣḥâbe-lḳaryeh. iẕ câehe-lmürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'iẕ erselnâ ileyhimü-ŝneyni fekeẕẕebûhümâ fe`azzeznâ biŝâliŝin feḳâlû innâ ileyküm mürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'ḳâlû mâ entüm illâ beşerum miŝlünâ vemâ enzele-rraḥmânü min şey''in in entüm illâ tekẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, 'ḳâlû rabbünâ ya`lemü innâ ileyküm lemürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, 'vemâ `aleynâ ille-lbelâgu-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'ḳâlû innâ teṭayyernâ biküm. leil lem tentehû lenercümenneküm veleyemessenneküm minnâ `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, 'ḳâlû ṭâiruküm me`aküm. ein ẕükkirtüm. bel entüm ḳavmüm müsrifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'vecâe min aḳṣe-lmedîneti racülüy yes`â ḳâle yâ ḳavmi-ttebi`ü-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'ittebi`û mel lâ yes''elüküm ecrav vehüm mühtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'vemâ liye lâ a`büdü-lleẕî feṭaranî veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'eetteḫiẕü min dûnihî âliheten iy yüridni-rraḥmânü biḍurril lâ tugni `annî şefâ`atühüm şey''ev velâ yünḳiẕûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'innî iẕel lefî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'innî âmentü birabbiküm fesme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'ḳîle-dḫuli-lcenneh. ḳâle yâ leyte ḳavmî ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'bimâ gafera lî rabbî vece`alenî mine-lmükramîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'vemâ enzelnâ `alâ ḳavmihî mim ba`dihî min cündim mine-ssemâi vemâ künnâ münzilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'in kânet illâ ṣayḥatev vâḥideten feiẕâ hüm ḫâmidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'yâ ḥasraten `ale-l`ibâd. mâ ye''tîhim mir rasûlin illâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'elem yerav kem ehleknâ ḳablehüm mine-lḳurûni ennehüm ileyhim lâ yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'vein küllül lemmâ cemî`ul ledeynâ muḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'veâyetül lehümü-l''arḍu-lmeyteh. aḥyeynâhâ veaḫracnâ minhâ ḥabben feminhü ye''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'vece`alnâ fîhâ cennâtim min neḫîliv vea`nâbiv vefeccernâ fîhâ mine-l`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'liye''külû min ŝemerihî vemâ `amilethü eydîhim. efelâ yeşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'sübḥâne-lleẕî ḫaleḳa-l''ezvâce küllehâ mimmâ tümbitü-l''arḍu vemin enfüsihim vemimmâ lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'veâyetül lehümü-lleyl. nesleḫu minhü-nnehâra feiẕâ hüm mużlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'veşşemsü tecrî limüsteḳarril lehâ. ẕâlike taḳdîru-l`azîzi-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'velḳamera ḳaddernâhü menâzile ḥattâ `âde kel`urcûni-lḳadîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'le-şşemsü yembegî lehâ en tüdrike-lḳamera vele-lleylü sâbiḳu-nnehâr. veküllün fî felekiy yesbeḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'veâyetül lehüm ennâ ḥamelnâ ẕürriyyetehüm fi-lfülki-lmeşḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'veḫalaḳnâ lehüm mim miŝlihî mâ yerkebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'vein neşe'' nugriḳhüm felâ ṣarîḫa lehüm velâ hüm yünḳaẕûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'illâ raḥmetem minnâ vemetâ`an ilâ ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'veiẕâ ḳîle lehümü-tteḳû mâ beyne eydîküm vemâ ḫalfeküm le`alleküm türḥamûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'vemâ te''tîhim min âyetim min âyâti rabbihim illâ kânû `anhâ mü`riḍîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'veiẕâ ḳîle lehüm enfiḳû mimmâ razeḳakümü-llâhü ḳâle-lleẕîne keferû lilleẕîne âmenû enuṭ`imü mel lev yeşâü-llâhü aṭ`ameh. in entüm illâ fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'veyeḳûlûne metâ hâẕe-lva`dü in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'mâ yenżurûne illâ ṣayḥatev vâḥideten te''ḫuẕühüm vehüm yeḫiṣṣimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'felâ yesteṭî`ûne tevṣiyetev velâ ilâ ehlihim yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'venüfiḫa fi-ṣṣûri feiẕâ hüm mine-l''ecdâŝi ilâ rabbihim yensilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'ḳâlû yâ veylenâ mem be`aŝenâ mim merḳadinâ. hâẕâ mâ ve`ade-rraḥmânü veṣadeḳa-lmürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'in kânet illâ ṣayḥatev vâḥideten feiẕâ hüm cemî`ul ledeynâ muḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'felyevme lâ tużlemü nefsün şey''ev velâ tüczevne illâ mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'inne aṣḥâbe-lcennehi-lyevme fî şügulin fâkihûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'hüm veezvâcühüm fî żilâlin `ale-l''erâiki müttekiûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'lehüm fîhâ fâkihetüv velehüm mâ yedde`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, 'selâmün ḳavlem mir rabbir raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, 'vemtâzü-lyevme eyyühe-lmücrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'elem a`hed ileyküm yâ benî âdeme el lâ ta`büdü-şşeyṭân. innehû leküm `adüvvüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'veeni-`büdûnî. hâẕâ ṣirâṭum müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'veleḳad eḍalle minküm cibillen keŝîrâ. efelem tekûnû ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'hâẕihî cehennemü-lletî küntüm tû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'iṣlevhe-lyevme bimâ küntüm tekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'elyevme naḫtimü `alâ efvâhihim vetükellimünâ eydîhim veteşhedü ercülühüm bimâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'velev neşâü leṭamesnâ `alâ a`yünihim festebeḳu-ṣṣirâṭa feennâ yübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'velev neşâü lemesaḫnâhüm `alâ mekânetihim feme-steṭâ`û müḍiyyev velâ yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'vemen nü`ammirhü nünekkishü fi-lḫalḳ. efelâ ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'vemâ `allemnâhü-şşi`ra vemâ yembegî leh. in hüve illâ ẕikruv veḳur''ânüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'liyünẕira men kâne ḥayyev veyeḥiḳḳa-lḳavlü `ale-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'evelem yerav ennâ ḫalaḳnâ lehüm mimmâ `amilet eydînâ en`âmen fehüm lehâ mâlikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'veẕellelnâhâ lehüm feminhâ rakûbühüm veminhâ ye''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'velehüm fîhâ menâfi`u vemeşârib. efelâ yeşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'vetteḫaẕû min dûni-llâhi âlihetel le`allehüm yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'lâ yesteṭî`ûne naṣrahüm vehüm lehüm cündüm muḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'felâ yaḥzünke ḳavlühüm. innâ na`lemü mâ yüsirrûne vemâ yü`linûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'evelem yera-l''insânü ennâ ḫalaḳnâhü min nuṭfetin feiẕâ hüve ḫaṣîmüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'veḍarabe lenâ meŝelev venesiye ḫalḳah. ḳâle mey yuḥyi-l`iżâme vehiye ramîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'ḳul yuḥyîhe-lleẕî enşeehâ evvele merrah. vehüve bikülli ḫalḳin `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, 'elleẕî ce`ale leküm mine-şşeceri-l''aḫḍari nâran feiẕâ entüm minhü tûḳidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'eveleyse-lleẕî ḫaleḳa-ssemâvâti vel''arḍa biḳâdirin `alâ ey yaḫlüḳa miŝlehüm. belâ vehüve-lḫallâḳu-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'innemâ emruhû iẕâ erâde şey''en ey yeḳûle lehû kün feyekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'fesübḥâne-lleẕî biyedihî melekûtü külli şey''iv veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'veṣṣâffâti ṣaffâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'fezzâcirâti zecrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'fettâliyâti ẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'inne ilâheküm levâḥid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'rabbü-ssemâvâti vel''arḍi vemâ beynehümâ verabbü-lmeşâriḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'innâ zeyyenne-ssemâe-ddünyâ bizînetini-lkevâkib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'veḥifżam min külli şeyṭânim mârid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'lâ yessemme`ûne ile-lmelei-l''a`lâ veyuḳẕefûne min külli cânib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'düḥûrav velehüm `aẕâbüv vâṣib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'illâ men ḫaṭife-lḫaṭfete feetbe`ahû şihâbün ŝâḳib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'festeftihim ehüm eşeddü ḫalḳan em men ḫalaḳnâ. innâ ḫalaḳnâhüm min ṭînil lâzib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'bel `acibte veyesḫarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'veiẕâ ẕükkirû lâ yeẕkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'veiẕâ raev âyetey yestesḫirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'veḳâlû in hâẕâ illâ siḥrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'eiẕâ mitnâ vekünnâ türâbev ve`iżâmen einnâ lemeb`ûŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'eveâbâüne-l''evvelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'ḳul ne`am veentüm dâḫirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'feinnemâ hiye zecratüv vâḥidetün feiẕâ hüm yenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'veḳâlû yâ veylenâ hâẕâ yevmü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, 'hâẕâ yevmü-lfaṣli-lleẕî küntüm bihî tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, 'uḥşürü-lleẕîne żalemû veezvâcehüm vemâ kânû ya`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'min dûni-llâhi fehdûhüm ilâ ṣirâṭi-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'veḳifûhüm innehüm mes''ûlûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, 'mâ leküm lâ tenâṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'bel hümü-lyevme müsteslimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'veaḳbele ba`ḍuhüm `alâ ba`ḍiy yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'ḳâlû inneküm küntüm te''tûnenâ `ani-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'ḳâlû bel lem tekûnû mü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'vemâ kâne lenâ `aleyküm min sülṭân. bel küntüm ḳavmen ṭâgîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'feḥaḳḳa `aleynâ ḳavlü rabbinâ. innâ leẕâiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'feagveynâküm innâ künnâ gâvîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'feinnehüm yevmeiẕin fi-l`aẕâbi müşterikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'innâ keẕâlike nef`alü bilmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'innehüm kânû iẕâ ḳîle lehüm lâ ilâhe ille-llâhü yestekbirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'veyeḳûlûne einnâ letârikû âlihetinâ lişâ`irim mecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'bel câe bilḥaḳḳi veṣaddeḳa-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'inneküm leẕâiḳu-l`aẕâbi-l''elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'vemâ tüczevne illâ mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'illâ `ibâde-llâhi-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'ülâike lehüm rizḳum ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'fevâkih. vehüm mükramûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'fî cennâti-nne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, '`alâ sürurim müteḳâbilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'yüṭâfü `aleyhim bike''sim mim me`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'beyḍâe leẕẕetil lişşâribîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'lâ fîhâ gavlüv velâ hüm `anhâ yünzefûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 've`indehüm ḳâṣirâtu-ṭṭarfi `în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'keennehünne beyḍum meknûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'feaḳbele ba`ḍuhüm `alâ ba`ḍiy yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'ḳâle ḳâilüm minhüm innî kâne lî ḳarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'yeḳûlü einneke lemine-lmüṣaddiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'eiẕâ mitnâ vekünnâ türâbev ve`iżâmen einnâ lemedînûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'ḳâle hel entüm müṭṭali`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'feṭṭale`a feraâhü fî sevâi-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'ḳâle tellâhi in kitte letürdîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'velevlâ ni`metü rabbî leküntü mine-lmuḥḍarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, 'efemâ naḥnü bimeyyitîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'illâ mevtetene-l''ûlâ vemâ naḥnü bimü`aẕẕebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'inne hâẕâ lehüve-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'limiŝli hâẕâ felya`meli-l`âmilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'eẕâlike ḫayrun nüzülen em şeceratü-zzeḳḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'innâ ce`alnâhâ fitnetel liżżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'innehâ şeceratün taḫrucü fî aṣli-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'ṭal`uhâ keennehû ruûsü-şşeyâṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'feinnehüm leâkilûne minhâ femâliûne minhe-lbüṭûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'ŝümme inne lehüm `aleyhâ leşevbem min ḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'ŝümme inne merci`ahüm leile-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'innehüm elfev âbâehüm ḍâllîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'fehüm `alâ âŝârihim yühra`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'veleḳad ḍalle ḳablehüm ekŝeru-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'veleḳad erselnâ fîhim münẕirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'fenżur keyfe kâne `âḳibetü-lmünẕerîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'illâ `ibâde-llâhi-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'veleḳad nâdânâ nûḥun feleni`me-lmücîbûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'venecceynâhü veehlehû mine-lkerbi-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'vece`alnâ ẕürriyyetehû hümü-lbâḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'veteraknâ `aleyhi fi-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, 'selâmün `alâ nûḥin fi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'innâ keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'innehû min `ibâdine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'ŝümme agraḳne-l''âḫarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'veinne min şî`atihî leibrâhîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'iẕ câe rabbehû biḳalbin selîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'iẕ ḳâle liebîhi veḳavmihî mâẕâ ta`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'eifken âliheten dûne-llâhi türîdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'femâ żannüküm birabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'feneżara nażraten fi-nnücûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'feḳâle innî seḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'fetevellev `anhü müdbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'ferâga ilâ âlihetihim feḳâle elâ te''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'mâ leküm lâ tenṭiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'ferâga `aleyhim ḍarbem bilyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'feaḳbelû ileyhi yeziffûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, 'ḳâle eta`büdûne mâ tenḥitûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'vellâhü ḫaleḳaküm vemâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, 'ḳâlü-bnû lehû bünyânen feelḳûhü fi-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'feerâdû bihî keyden fece`alnâhümü-l''esfelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'veḳâle innî ẕâhibün ilâ rabbî seyehdîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'rabbi heb lî mine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'febeşşernâhü bigulâmin ḥalîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'felemmâ belega me`ahü-ssa`ye ḳâle yâ büneyye innî erâ fi-lmenâmi ennî eẕbeḥuke fenżur mâẕâ terâ. ḳâle yâ ebeti-f`al mâ tü''mer. setecidünî in şâe-llâhü mine-ṣṣâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'felemmâ eslemâ vetellehû lilcebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'venâdeynâhü ey yâ ibrâhîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'ḳad ṣaddaḳte-rru''yâ. innâ keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'inne hâẕâ lehüve-lbelâü-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'vefedeynâhü biẕibḥin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'veteraknâ `aleyhi fi-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, 'selâmün `alâ ibrâhîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'innehû min `ibâdine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'vebeşşernâhü biisḥâḳa nebiyyem mine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'vebâraknâ `aleyhi ve`alâ isḥâḳ. vemin ẕürriyyetihimâ muḥsinüv veżâlimül linefsihî mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'veleḳad menennâ `alâ mûsâ vehârûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'venecceynâhümâ veḳavmehümâ mine-lkerbi-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'veneṣarnâhüm fekânû hümü-lgâlibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'veâteynâhüme-lkitâbe-lmüstebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'vehedeynâhüme-ṣṣirâṭa-lmüsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'veteraknâ `aleyhimâ fi-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, 'selâmün `alâ mûsâ vehârûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'innâ keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'innehümâ min `ibâdine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'veinne ilyâse lemine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'iẕ ḳâle liḳavmihî elâ tetteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'eted`ûne ba`lev veteẕerûne aḥsene-lḫâliḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'allâhe rabbeküm verabbe âbâikümü-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'fekeẕẕebûhü feinnehüm lemuḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'illâ `ibâde-llâhi-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'veteraknâ `aleyhi fi-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, 'selâmün `alâ ilyâsîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'innâ keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'innehû min `ibâdine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'veinne lûṭal lemine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'iẕ necceynâhü veehlehû ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'illâ `acûzen fi-lgâbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'ŝümme demmerne-l''âḫarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'veinneküm letemürrûne `aleyhim muṣbiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'vebilleyl. efelâ ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'veinne yûnüse lemine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'iẕ ebeḳa ile-lfülki-lmeşḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'fesâheme fekâne mine-lmüdḥaḍîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'felteḳamehü-lḥûtü vehüve mülîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'felevlâ ennehû kâne mine-lmüsebbiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'lelebiŝe fî baṭnih ilâ yevmi yüb`aŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'fenebeẕnâhü bil`arâi vehüve seḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'veembetnâ `aleyhi şeceratem miy yaḳṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'veerselnâhü ilâ mieti elfin ev yezîdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'feâmenû femetta`nâhüm ilâ ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'festeftihim elirabbike-lbenâtü velehümü-lbenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'em ḫalaḳne-lmelâikete inâŝev vehüm şâhidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'elâ innehüm min ifkihim leyeḳûlûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, 'velede-llâhü veinnehüm lekâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'aṣṭafe-lbenâti `ale-lbenîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'mâ leküm. keyfe taḥkümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'efelâ teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'em leküm sülṭânüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'fe''tû bikitâbiküm in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'vece`alû beynehû vebeyne-lcinneti nesebâ. veleḳad `alimeti-lcinnetü innehüm lemuḥḍarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'sübḥâne-llâhi `ammâ yeṣifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'illâ `ibâde-llâhi-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'feinneküm vemâ ta`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'mâ entüm `aleyhi bifâtinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'illâ men hüve ṣâli-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'vemâ minnâ illâ lehû meḳâmüm ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'veinnâ lenaḥnu-ṣṣâffûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'veinnâ lenaḥnü-lmüsebbiḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'vein kânû leyeḳûlûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, 'lev enne `indenâ ẕikram mine-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'lekünnâ `ibâde-llâhi-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'fekeferû bih. fesevfe ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'veleḳad sebeḳat kelimetünâ li`ibâdine-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'innehüm lehümü-lmenṣûrûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'veinne cündenâ lehümü-lgâlibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'fetevelle `anhüm ḥattâ ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'veebṣirhüm fesevfe yübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'efebi`aẕâbinâ yesta`cilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'feiẕâ nezele bisâḥatihim fesâe ṣabâḥu-lmünẕerîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'vetevelle `anhüm ḥattâ ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'veebṣir fesevfe yübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'sübḥâne rabbike rabbi-l`izzeti `ammâ yeṣifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'veselâmün `ale-lmürselîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'velḥamdü lillâhi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'ṣâd. velḳur''âni ẕi-ẕẕikr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'beli-lleẕîne keferû fî `izzetiv veşiḳâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'kem ehleknâ min ḳablihim min ḳarnin fenâdev velâte ḥîne menâṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 've`acibû en câehüm münẕirum minhüm. veḳâle-lkâfirûne hâẕâ sâḥirun keẕẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'ece`ale-l''âlihete ilâhev vâḥidâ. inne hâẕâ leşey''ün `ucâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'venṭaleḳa-lmeleü minhüm eni-mşû vaṣbirû `alâ âlihetiküm. inne hâẕâ leşey''üy yürâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'mâ semi`nâ bihâẕâ fi-lmilleti-l''âḫirah. in hâẕâ ille-ḫtilâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'eünzile `aleyhi-ẕẕikru mim beyninâ. bel hüm fî şekkim min ẕikrî. bel lemmâ yeẕûḳû `aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'em `indehüm ḫazâinü raḥmeti rabbike-l`azîzi-lvehhâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'em lehüm mülkü-ssemâvâti vel''arḍi vemâ beynehümâ. felyerteḳû fi-l''esbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'cündüm mâ hünâlike mehzûmüm mine-l''aḥzâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'keẕẕebet ḳablehüm ḳavmü nûḥiv ve`âdüv vefir`avnü ẕü-l''evtâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'veŝemûdü veḳavmü lûṭiv veaṣḥâbü-l''eykeh. ülâike-l''aḥzâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'in küllün illâ keẕẕebe-rrusüle feḥaḳḳa `iḳâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'vemâ yenżuru hâülâi illâ ṣayḥatev vâḥidetem mâ lehâ min fevâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'veḳâlû rabbenâ `accil lenâ ḳiṭṭanâ ḳable yevmi-lḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'iṣbir `alâ mâ yeḳûlûne veẕkür `abdenâ dâvûde ẕe-l''eyd. innehû evvâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'innâ seḫḫarne-lcibâle me`ahû yüsebbiḥne bil`aşiyyi vel''işrâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'veṭṭayra maḥşûrah. küllül lehû evvâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'veşedednâ mülkehû veâteynâhü-lḥikmete vefaṣle-lḫiṭâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'vehel etâke nebeü-lḫaṣm. iẕ tesevveru-lmiḥrâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'iẕ deḫalû `alâ dâvûde fefezi`a minhüm ḳâlû lâ teḫaf. ḫaṣmâni begâ ba`ḍunâ `alâ ba`ḍin faḥküm beynenâ bilḥaḳḳi velâ tüşṭiṭ vehdinâ ilâ sevâi-ṣṣirâṭ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'inne hâẕâ eḫî lehû tis`uv vetis`ûne na`cetev veliye na`cetüv vâḥidetün feḳâle ekfilnîhâ ve`azzenî fi-lḫiṭâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, 'ḳâle leḳad żalemeke bisüâli na`cetike ilâ ni`âcih. veinne keŝîram mine-lḫuleṭâi leyebgî ba`ḍuhüm `alâ ba`ḍin ille-lleẕîne âmenû ve`amilu-ṣṣâliḥâti veḳalîlüm mâ hüm. veżanne dâvûdü ennemâ fetennâhü festagfera rabbehû veḫarra râki`av veenâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'fegafernâ lehû ẕâlik. veinne lehû `indenâ lezülfâ veḥusne meâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'yâ dâvûdü innâ ce`alnâke ḫalîfeten fi-l''arḍi faḥküm beyne-nnâsi bilḥaḳḳi velâ tettebi`i-lhevâ feyüḍilleke `an sebîli-llâh. inne-lleẕîne yeḍillûne `an sebîli-llâhi lehüm `aẕâbün şedîdüm bimâ nesû yevme-lḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'vemâ ḫalaḳne-ssemâe vel''arḍa vemâ beynehümâ bâṭilâ. ẕâlike żannü-lleẕîne keferû. feveylül lilleẕîne keferû mine-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'em nec`alü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti kelmüfsidîne fi-l''arḍ. em nec`alü-lmütteḳîne kelfüccâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, 'kitâbün enzelnâhü ileyke mübârakül liyeddebberû âyâtihî veliyeteẕekkera ülü-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'vevehebnâ lidâvûde süleymân. ni`me-l`abd. innehû evvâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'iẕ `uriḍa `aleyhi bil`aşiyyi-ṣṣâfinâtü-lciyâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'feḳâle innî aḥbebtü ḥubbe-lḫayri `an ẕikri rabbî. ḥattâ tevârat bilḥicâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, 'ruddûhâ `aleyy. feṭafiḳa mesḥam bissûḳi vel''a`nâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'veleḳad fetennâ süleymâne veelḳaynâ `alâ kürsiyyihî ceseden ŝümme enâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'ḳâle rabbi-gfir lî veheb lî mülkel lâ yembegî lieḥadim mim ba`dî. inneke ente-lvehhâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'feseḫḫarnâ lehü-rrîḥa tecrî biemrih ruḫâen ḥayŝü eṣâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'veşşeyâṭîne külle bennâiv vegavvâṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'veâḫarîne müḳarranîne fi-l''aṣfâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, 'hâẕâ `aṭâünâ femnün ev emsik bigayri ḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'veinne lehû `indenâ lezülfâ veḥusne meâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'veẕkür `abdenâ eyyûb. iẕ nâdâ rabbehû ennî messeniye-şşeyṭânü binuṣbiv ve`aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, 'ürkuḍ biriclik. hâẕâ mugteselüm bâridüv veşerâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'vevehebnâ lehû ehlehû vemiŝlehüm me`ahüm raḥmetem minnâ veẕikrâ liüli-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, 'veḫuẕ biyedike ḍigŝen faḍrib bihî velâ taḥneŝ. innâ vecednâhü ṣâbirâ. ni`me-l`abd. innehû evvâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'veẕkür `ibâdenâ ibrâhîme veisḥâḳa veya`ḳûbe üli-l''eydî vel''ebṣâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'innâ aḫlaṣnâhüm biḫâliṣatin ẕikra-ddâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'veinnehüm `indenâ lemine-lmuṣṭafeyne-l''aḫyâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'veẕkür ismâ`île velyese`a veẕe-lkifl. veküllüm mine-l''aḫyâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'hâẕâ ẕikr. veinne lilmütteḳîne leḥusne meâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'cennâti `adnim müfetteḥatel lehümü-l''ebvâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'müttekiîne fîhâ yed`ûne fîhâ bifâkihetin keŝîrativ veşerâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 've`indehüm ḳâṣirâtu-ṭṭarfi etrâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'hâẕâ mâ tû`adûne liyevmi-lḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'inne hâẕâ lerizḳunâ mâ lehû min nefâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'hâẕâ. veinne liṭṭâgîne leşerra meâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'cehennem. yaṣlevnehâ. febi''se-lmihâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'hâẕâ felyeẕûḳûhü ḥamîmüv vegassâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'veâḫaru min şeklihî ezvâc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'hâẕâ fevcüm muḳteḥimüm me`aküm. lâ merḥabem bihim. innehüm ṣâlü-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, 'ḳâlû bel entüm. lâ merḥabem biküm. entüm ḳaddemtümûhü lenâ. febi''se-lḳarâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'ḳâlû rabbenâ men ḳaddeme lenâ hâẕâ fezidhü `aẕâben ḍi`fen fi-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'veḳâlû mâ lenâ lâ nerâ ricâlen künnâ ne`uddühüm mine-l''eşrâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'etteḫaẕnâhüm siḫriyyen em zâgat `anhümü-l''ebṣâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'inne ẕâlike leḥaḳḳun teḫâṣumü ehli-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'ḳul innemâ ene münẕir. vemâ min ilâhin ille-llâhü-lvâḥidü-lḳahhâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'rabbü-ssemâvâti vel''arḍi vemâ beynehüme-l`azîzü-lgaffâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'ḳul hüve nebeün `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'entüm `anhü mü`riḍûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'mâ kâne liye min `ilmim bilmelei-l''a`lâ iẕ yaḫteṣimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'iy yûḥâ ileyye illâ ennemâ ene neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'iẕ ḳâle rabbüke lilmelâiketi innî ḫâliḳum beşeram min ṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'feiẕâ sevveytühû venefaḫtü fîhi mir rûḥî feḳa`û lehû sâcidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'fesecede-lmelâiketü küllühüm ecme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'illâ iblîs. istekbera vekâne mine-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, 'ḳâle yâ iblîsü mâ mene`ake en tescüde limâ ḫalaḳtü biyedeyy. estekberte em künte mine-l`âlîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, 'ḳâle ene ḫayrum minh. ḫalaḳtenî min nâriv veḫalaḳtehû min ṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, 'ḳâle faḫruc minhâ feinneke racîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'veinne `aleyke la`netî ilâ yevmi-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, 'ḳâle rabbi feenżirnî ilâ yevmi yüb`aŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, 'ḳâle feinneke mine-lmünżarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'ilâ yevmi-lvaḳti-lma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, 'ḳâle febi`izzetike leugviyennehüm ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'illâ `ibâdeke minhümü-lmuḫleṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, 'ḳâle felḥaḳḳ. velḥaḳḳa eḳûl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'leemleenne cehenneme minke vemimmen tebi`ake minhüm ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'ḳul mâ es''elüküm `aleyhi min ecriv vemâ ene mine-lmütekellifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'in hüve illâ ẕikrul lil`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'veleta`lemünne nebeehû ba`de ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'tenzîlü-lkitâbi mine-llâhi-l`azîzi-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'innâ enzelnâ ileyke-lkitâbe bilḥaḳḳi fa`büdi-llâhe muḫliṣal lehü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'elâ lillâhi-ddînü-lḫâliṣ. velleẕîne-tteḫaẕû min dûnihî evliyâ''. mâ na`büdühüm illâ liyüḳarribûnâ ile-llâhi zülfâ. inne-llâhe yaḥkümü beynehüm fî mâ hüm fîhi yaḫtelifûn. inne-llâhe lâ yehdî men hüve kâẕibün keffâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'lev erâde-llâhü ey yetteḫiẕe veledel laṣṭafâ mimmâ yaḫlüḳu mâ yeşâü sübḥâneh. hüve-llâhü-lvâḥidü-lḳahhâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'ḫaleḳa-ssemâvâti vel''arḍa bilḥaḳḳ. yükevviru-lleyle `ale-nnehâri veyükevviru-nnehâra `ale-lleyli veseḫḫara-şşemse velḳamer. küllüy yecrî liecelim müsemmâ. elâ hüve-l`azîzü-lgaffâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'ḫaleḳaküm min nefsiv vâḥidetin ŝümme ce`ale minhâ zevcehâ veenzele leküm mine-l''en`âmi ŝemâniyete ezvâc. yaḫlüḳuküm fî büṭûni ümmehâtiküm ḫalḳam mim ba`di ḫalḳin fî żulümâtin ŝelâŝ. ẕâlikümü-llâhü rabbüküm lehü-lmülk. lâ ilâhe illâ hû. feennâ tuṣrafûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'in tekfürû feinne-llâhe ganiyyün `anküm velâ yerḍâ li`ibâdihi-lküfr. vein teşkürû yerḍahü leküm. velâ teziru vâziratüv vizra uḫrâ. ŝümme ilâ rabbiküm merci`uküm feyünebbiüküm bimâ küntüm ta`melûn. innehû `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'veiẕâ messe-l''insâne ḍurrun de`â rabbehû münîben ileyhi ŝümme iẕâ ḫavvelehû ni`metem minhü nesiye mâ kâne yed`û ileyhi min ḳablü vece`ale lillâhi endâdel liyüḍille `an sebîlih. ḳul temetta` biküfrike ḳalîlen. inneke min aṣḥâbi-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'emmen hüve ḳânitün ânâe-lleyli sâcidev veḳâimey yaḥẕeru-l''âḫirate veyercû raḥmete rabbih. ḳul hel yestevi-lleẕîne ya`lemûne velleẕîne lâ ya`lemûn. innemâ yeteẕekkeru ülü-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'ḳul yâ `ibâdi-lleẕîne âmenü-tteḳû rabbeküm. lilleẕîne aḥsenû fî hâẕihi-ddünyâ ḥaseneh. vearḍu-llâhi vâsi`ah. innemâ yüveffe-ṣṣâbirûne ecrahüm bigayri ḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'ḳul innî ümirtü en a`büde-llâhe muḫliṣal lehü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'veümirtü lien ekûne evvele-lmüslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'ḳul innî eḫâfü in `aṣaytü rabbî `aẕâbe yevmin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'ḳuli-llâhe a`büdü muḫliṣal lehû dînî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'fa`büdû mâ şi''tüm min dûnih. ḳul inne-lḫâsirîne-lleẕîne ḫasirû enfüsehüm veehlîhim yevme-lḳiyâmeh. elâ ẕâlike hüve-lḫusrânü-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'lehüm min fevḳihim żulelüm mine-nnâri vemin taḥtihim żulelün. ẕâlike yüḫavvifü-llâhü bihî `ibâdeh. yâ `ibâdi fetteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'velleẕîne-ctenebu-ṭṭâgûte ey ya`büdûhâ veenâbû ile-llâhi lehümü-lbüşrâ. febeşşir `ibâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'elleẕîne yestemi`ûne-lḳavle feyettebi`ûne aḥseneh. ülâike-lleẕîne hedâhümü-llâhü veülâike hüm ülü-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'efemen ḥaḳḳa `aleyhi kelimetü-l`aẕâb. efeente tünḳiẕü men fi-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'lâkini-lleẕîne-tteḳav rabbehüm lehüm gurafüm min fevḳihâ gurafüm mebniyyetün tecrî min taḥtihe-l''enhâr. va`de-llâh. lâ yuḫlifü-llâhü-lmî`âd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'elem tera enne-llâhe enzele mine-ssemâi mâen feselekehû yenâbî`a fi-l''arḍi ŝümme yuḫricü bihî zer`am muḫtelifen elvânühû ŝümme yehîcü feterâhü muṣferran ŝümme yec`alühû ḥuṭâmâ. inne fî ẕâlike leẕikrâ liüli-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'efemen şeraḥa-llâhü ṣadrahû lil''islâmi fehüve `alâ nûrum mir rabbih. feveylül lilḳâsiyeti ḳulûbühüm min ẕikri-llâh. ülâike fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'allâhü nezzele aḥsene-lḥadîŝi kitâbem müteşâbihem meŝânî. taḳşe`irru minhü cülûdü-lleẕîne yaḫşevne rabbehüm. ŝümme telînü cülûdühüm veḳulûbühüm ilâ ẕikri-llâh. ẕâlike hüde-llâhi yehdî bihî mey yeşâ''. vemey yuḍlili-llâhü femâ lehû min hâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'efemey yetteḳî bivechihî sûe-l`aẕâbi yevme-lḳiyâmeh. veḳîle liżżâlimîne ẕûḳû mâ küntüm teksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'keẕẕebe-lleẕîne min ḳablihim feetâhümü-l`aẕâbü min ḥayŝü lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'feeẕâḳahümü-llâhü-lḫizye fi-lḥayâti-ddünyâ. vele`aẕâbü-l''âḫirati ekber. lev kânû ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'veleḳad ḍarabnâ linnâsi fî hâẕe-lḳur''âni min külli meŝelil le`allehüm yeteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'ḳur''ânen `arabiyyen gayra ẕî `ivecil le`allehüm yetteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'ḍarabe-llâhü meŝeler racülen fîhi şürakâü müteşâkisûne veracülen selemel liracül. hel yesteviyâni meŝelâ. elḥamdü lillâh. bel ekŝeruhüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'inneke meyyitüv veinnehüm meyyitûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'ŝümme inneküm yevme-lḳiyâmeti `inde rabbiküm taḫteṣimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'femen ażlemü mimmen keẕebe `ale-llâhi vekeẕẕebe biṣṣidḳi iẕ câeh. eleyse fî cehenneme meŝvel lilkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'velleẕî câe biṣṣidḳi veṣaddeḳa bihî ülâike hümü-lmütteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'lehüm mâ yeşâûne `inde rabbihim. ẕâlike cezâü-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'liyükeffira-llâhü `anhüm esvee-lleẕî `amilû veyecziyehüm ecrahüm biaḥseni-lleẕî kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'eleyse-llâhü bikâfin `abdeh. veyüḫavvifûneke billeẕîne min dûnih. vemey yuḍlili-llâhü femâ lehû min hâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'vemey yehdi-llâhü femâ lehû mim müḍill. eleyse-llâhü bi`azîzin ẕi-ntiḳâm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'velein seeltehüm men ḫaleḳa-ssemâvâti vel''arḍa leyeḳûlünne-llâh. ḳul eferaeytüm mâ ted`ûne min dûni-llâhi in erâdeniye-llâhü biḍurrin hel hünne kâşifâtü ḍurrihî ev erâdenî biraḥmetin hel hünne mümsikâtü raḥmetih. ḳul ḥasbiye-llâh. `aleyhi yetevekkelü-lmütevekkilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'ḳul yâ ḳavmi-`melû `alâ mekânetiküm innî `âmil. fesevfe ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'mey ye''tîhi `aẕâbüy yuḫzîhi veyeḥillü `aleyhi `aẕâbüm müḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'innâ enzelnâ `aleyke-lkitâbe linnâsi bilḥaḳḳ. femeni-htedâ felinefsih. vemen ḍalle feinnemâ yeḍillü `aleyhâ. vemâ ente `aleyhim bivekîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'allâhü yeteveffe-l''enfüse ḥîne mevtihâ velletî lem temüt fî menâmihâ. feyümsikü-lletî ḳaḍâ `aleyhe-lmevte veyürsilü-l''uḫrâ ilâ ecelim müsemmâ. inne fî ẕâlike leâyâtil liḳavmiy yetefekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'emi-tteḫaẕû min dûni-llâhi şüfe`â''. ḳul evelev kânû lâ yemlikûne şey''ev velâ ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'ḳul lillâhi-şşefâ`atü cemî`â. lehû mülkü-ssemâvâti vel''arḍ. ŝümme ileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'veiẕâ ẕükira-llâhü vaḥdehü-şmeezzet ḳulûbü-lleẕîne lâ yü''minûne bil''âḫirati. veiẕâ ẕükira-lleẕîne min dûnihî iẕâ hüm yestebşirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'ḳuli-llâhümme fâṭira-ssemâvâti vel''arḍi `âlime-lgaybi veşşehâdeti ente taḥkümü beyne `ibâdike fîmâ kânû fîhi yaḫtelifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'velev enne lilleẕîne żalemû mâ fi-l''arḍi cemî`av vemiŝlehû me`ahû leftedev bihî min sûi-l`aẕâbi yevme-lḳiyâmeh. vebedâ lehüm mine-llâhi mâ lem yekûnû yaḥtesibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'vebedâ lehüm seyyietü mâ kesebû veḥâḳa bihim mâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'feiẕâ messe-l''insâne ḍurrun de`ânâ. ŝümme iẕâ ḫavvelnâhü ni`metem minnâ ḳâle innemâ ûtîtühû `alâ `ilm. bel hiye fitnetüv velâkinne ekŝerahüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'ḳad ḳâlehe-lleẕîne min ḳablihim femâ agnâ `anhüm mâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'feeṣâbehüm seyyietü mâ kesebû. velleẕîne żalemû min hâülâi seyüṣîbühüm seyyietü mâ kesebû vemâ hüm bimü`cizîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'evelem ya`lemû enne-llâhe yebsüṭu-rrizḳa limey yeşâü veyaḳdir. inne fî ẕâlike leâyâtil liḳavmiy yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'ḳul yâ `ibâdîye-lleẕîne esrafû `alâ enfüsihim lâ taḳneṭû mir raḥmeti-llâh. inne-llâhe yagfiru-ẕẕünûbe cemî`â. innehû hüve-lgafûru-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'veenîbû ilâ rabbiküm veeslimû lehû min ḳabli ey ye''tiyekümü-l`aẕâbü ŝümme lâ tünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'vettebi`û aḥsene mâ ünzile ileyküm mir rabbiküm min ḳabli ey ye''tiyekümü-l`aẕâbü bagtetev veentüm lâ teş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'en teḳûle nefsüy yâ ḥasratâ `alâ mâ ferraṭtü fî cembi-llâhi vein küntü lemine-ssâḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'ev teḳûle lev enne-llâhe hedânî leküntü mine-lmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'ev teḳûle ḥîne tera-l`aẕâbe lev enne lî kerraten feekûne mine-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, 'belâ ḳad câetke âyâtî fekeẕẕebte bihâ vestekberte vekünte mine-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'veyevme-lḳiyâmeti tera-lleẕîne keẕebû `ale-llâhi vucûhühüm müsveddeh. eleyse fî cehenneme meŝvel lilmütekebbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'veyünecci-llâhü-lleẕîne-tteḳav bimefâzetihim. lâ yemessühümü-ssûü velâ hüm yaḥzenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'allâhü ḫâliḳu külli şey''. vehüve `alâ külli şey''iv vekîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'lehû meḳâlîdü-ssemâvâti vel''arḍ. velleẕîne keferû biâyâti-llâhi ülâike hümü-lḫâsirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'ḳul efegayra-llâhi te''mürûnnî a`büdü eyyühe-lcâhilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'veleḳad ûḥiye ileyke veile-lleẕîne min ḳablik. lein eşrakte leyaḥbeṭanne `amelüke veletekûnenne mine-lḫâsirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'beli-llâhe fa`büd veküm mine-şşâkirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'vemâ ḳaderü-llâhe ḥaḳḳa ḳadrih. vel''arḍu cemî`an ḳabḍatühû yevme-lḳiyâmeti vessemâvâtü maṭviyyâtüm biyemînih. sübḥânehû vete`âlâ `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'venüfiḫa fi-ṣṣûri feṣa`iḳa men fi-ssemâvâti vemen fi-l''arḍi illâ men şâe-llâh. ŝümme nüfiḫa fîhi uḫrâ feiẕâ hüm ḳiyâmüy yenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'veeşraḳati-l''arḍu binûri rabbihâ vevuḍi`a-lkitâbü vecîe binnebiyyîne veşşühedâi veḳuḍiye beynehüm bilḥaḳḳi vehüm lâ yużlemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'vevuffiyet küllü nefsim mâ `amilet vehüve a`lemü bimâ yef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'vesîḳa-lleẕîne keferû ilâ cehenneme zümerâ. ḥattâ iẕâ câûhâ fütiḥat ebvâbühâ veḳâle lehüm ḫazenetühâ elem ye''tiküm rusülüm minküm yetlûne `aleyküm âyâti rabbiküm veyünẕirûneküm liḳâe yevmiküm hâẕâ. ḳâlû belâ velâkin ḥaḳḳat kelimetü-l`aẕâbi `ale-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'ḳîle-dḫulû ebvâbe cehenneme ḫâlidîne fîhâ. febi''se meŝve-lmütekebbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'vesîḳa-lleẕîne-tteḳav rabbehüm ile-lcenneti zümerâ. ḥattâ iẕâ câûhâ vefütiḥat ebvâbühâ veḳâle lehüm ḫazenetühâ selâmün `aleyküm ṭibtüm fedḫulûhâ ḫâlidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'veḳâlü-lḥamdü lillâhi-lleẕî ṣadeḳanâ va`dehû veevraŝene-l''arḍa netebevveü mine-lcenneti ḥayŝü neşâ''. feni`me ecru-l`âmilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'vetera-lmelâikete ḥâffîne min ḥavli-l`arşi yüsebbiḥûne biḥamdi rabbihim. veḳuḍiye beynehüm bilḥaḳḳi veḳîle-lḥamdü lillâhi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'tenzîlü-lkitâbi mine-llâhi-l`azîzi-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'gâfiri-ẕẕembi veḳâbili-ttevbi şedîdi-l`iḳâbi ẕi-ṭṭavl. lâ ilâhe illâ hû. ileyhi-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'mâ yücâdilü fî âyâti-llâhi ille-lleẕîne keferû felâ yagrurke teḳallübühüm fi-lbilâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'keẕẕebet ḳablehüm ḳavmü nûḥiv vel''aḥzâbü mim ba`dihim. vehemmet küllü ümmetim birasûlihim liye''ḫuẕûhü vecâdelû bilbâṭili liyüdḥiḍû bihi-lḥaḳḳa feeḫaẕtühüm. fekeyfe kâne `iḳâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'vekeẕâlike ḥaḳḳat kelimetü rabbike `ale-lleẕîne keferû ennehüm aṣḥâbü-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'elleẕîne yaḥmilûne-l`arşe vemen ḥavlehû yüsebbiḥûne biḥamdi rabbihim veyü''minûne bihî veyestagfirûne lilleẕîne âmenû. rabbenâ vesi`te külle şey''ir raḥmetev ve`ilmen fagfir lilleẕîne tâbû vettebe`û sebîleke veḳihim `aẕâbe-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'rabbenâ veedḫilhüm cennâti `adnini-lletî ve`attehüm vemen ṣaleḥa min âbâihim veezvâcihim veẕürriyyâtihim. inneke ente-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'veḳihimü-sseyyiât. vemen teḳi-sseyyiâti yevmeiẕin feḳad raḥimteh. veẕâlike hüve-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'inne-lleẕîne keferû yünâdevne lemaḳtü-llâhi ekberu mim maḳtiküm enfüseküm iẕ tüd`avne ile-l''îmâni fetekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'ḳâlû rabbenâ emettene-ŝneteyni veaḥyeytene-ŝneteyni fa`terafnâ biẕünûbinâ fehel ilâ ḫurûcim min sebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, 'ẕâliküm biennehû iẕâ dü`iye-llâhü vaḥdehû kefertüm. veiy yüşrak bihî tü''minû. felḥukmü lillâhi-l`aliyyi-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'hüve-lleẕî yürîküm âyâtihî veyünezzilü leküm mine-ssemâi rizḳâ. vemâ yeteẕekkeru illâ mey yünîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'fed`ü-llâhe muḫliṣîne lehü-ddîne velev kerihe-lkâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'rafî`u-dderacâti ẕü-l`arş. yülḳi-rrûḥa min emrihî `alâ mey yeşâü min `ibâdihî liyünẕira yevme-ttelâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'yevme hüm bârizûn. lâ yaḫfâ `ale-llâhi minhüm şey''ün. limeni-lmülkü-lyevm. lillâhi-lvâḥidi-lḳahhâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'elyevme tüczâ küllü nefsim bimâ kesebet. lâ żulme-lyevm. inne-llâhe serî`u-lḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'veenẕirhüm yevme-l''âzifeti iẕi-lḳulûbü lede-lḥanâciri kâżimîn. mâ liżżâlimîne min ḥamîmiv velâ şefî`iy yüṭâ`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, 'ya`lemü ḫâinete-l''a`yüni vemâ tuḫfi-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'vellâhü yaḳḍî bilḥaḳḳ. velleẕîne yed`ûne min dûnihî lâ yaḳḍûne bişey''. inne-llâhe hüve-ssemî`u-lbeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'evelem yesîrû fi-l''arḍi feyenżurû keyfe kâne `âḳibetü-lleẕîne kânû min ḳablihim. kânû hüm eşedde minhüm ḳuvvetev veâŝâran fi-l''arḍi feeḫaẕehümü-llâhü biẕünûbihim vemâ kâne lehüm mine-llâhi miv vâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'ẕâlike biennehüm kânet te''tîhim rusülühüm bilbeyyinâti fekeferû feeḫaẕehümü-llâh. innehû ḳaviyyün şedîdü-l`iḳâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'veleḳad erselnâ mûsâ biâyâtinâ vesülṭânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'ilâ fir`avne vehâmâne veḳârûne feḳâlû sâḥirun keẕẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'felemmâ câehüm bilḥaḳḳi min `indinâ ḳâlu-ḳtülû ebnâe-lleẕîne âmenû me`ahû vestaḥyû nisâehüm. vemâ keydü-lkâfirîne illâ fî ḍalâl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'veḳâle fir`avnü ẕerûnî aḳtül mûsâ velyed`u rabbeh. innî eḫâfü ey yübeddile dîneküm ev ey yużhira fi-l''arḍi-lfesâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'veḳâle mûsâ innî `uẕtü birabbî verabbiküm min külli mütekebbiril lâ yü''minü biyevmi-lḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'veḳâle racülüm mü''min. min âli fir`avne yektümü îmânehû etaḳtülûne racülen ey yeḳûle rabbiye-llâhü veḳad câeküm bilbeyyinâti mir rabbiküm. veiy yekü kâẕiben fe`aleyhi keẕibüh. veiy yekü ṣâdiḳay yüṣibküm ba`ḍu-lleẕî ye`idüküm. inne-llâhe lâ yehdî men hüve müsrifün keẕẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'yâ ḳavmi lekümü-lmülkü-lyevme żâhirîne fi-l''arḍ. femey yenṣurunâ mim be''si-llâhi in câenâ. ḳâle fir`avnü mâ ürîküm illâ mâ erâ vemâ ehdîküm illâ sebîle-rraşâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'veḳâle-lleẕî âmene yâ ḳavmi innî eḫâfü `aleyküm miŝle yevmi-l''aḥzâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'miŝle de''bi ḳavmi nûḥiv ve`âdiv veŝemûde velleẕîne mim ba`dihim. veme-llâhü yürîdü żulmel lil`ibâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'veyâ ḳavmi innî eḫâfü `aleyküm yevme-ttenâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'yevme tüvellûne müdbirîn. mâ leküm mine-llâhi min `âṣim. vemey yuḍlili-llâhü femâ lehû min hâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'veleḳad câeküm yûsüfü min ḳablü bilbeyyinâti femâ ziltüm fî şekkim mimmâ câeküm bih. ḥattâ iẕâ heleke ḳultüm ley yeb`aŝe-llâhü mim ba`dihî rasûlâ. keẕâlike yüḍillü-llâhü men hüve müsrifüm mürtâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'elleẕîne yücâdilûne fî âyâti-llâhi bigayri sülṭânin etâhüm. kebüra maḳten `inde-llâhi ve`inde-lleẕîne âmenû. keẕâlike yaṭbe`u-llâhü `alâ külli ḳalbi mütekebbirin cebbâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'veḳâle fir`avnü yâ hâmânü-bni lî ṣarḥal le`allî eblügu-l''esbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'esbâbe-ssemâvâti feeṭṭali`a ilâ ilâhi mûsâ veinnî leeżunnühû kâẕibâ. vekeẕâlike züyyine lifir`avne sûü `amelihî veṣudde `ani-ssebîl. vemâ keydü fir`avne illâ fî tebâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'veḳâle-lleẕî âmene yâ ḳavmi-ttebi`ûni ehdiküm sebîle-rraşâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'yâ ḳavmi innemâ hâẕihi-lḥayâtü-ddünyâ metâ`. veinne-l''âḫirate hiye dâru-lḳarâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'men `amile seyyieten felâ yüczâ illâ miŝlehâ. vemen `amile ṣâliḥam min ẕekerin ev ünŝâ vehüve mü''minün feülâike yedḫulûne-lcennete yürzeḳûne fîhâ bigayri ḥisâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'veyâ ḳavmi mâ lî ed`ûküm ile-nnecâti veted`ûnenî ile-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'ted`ûnenî liekfüra billâhi veüşrike bihî mâ leyse lî bihî `ilm. veenâ ed`ûküm ile-l`azîzi-lgaffâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'lâ cerame ennemâ ted`ûnenî ileyhi leyse lehû da`vetün fi-ddünyâ velâ fi-l''âḫirati veenne meraddenâ ile-llâhi veenne-lmüsrifîne hüm aṣḥâbü-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'feseteẕkürûne mâ eḳûlü leküm. veüfevviḍu emrî ile-llâh. inne-llâhe beṣîrum bil`ibâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'feveḳâhü-llâhü seyyiâti mâ mekerû veḥâḳa biâli fir`avne sûü-l`aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'ennâru yü`raḍûne `aleyhâ gudüvvev ve`aşiyyâ. veyevme teḳûmü-ssâ`ah. edḫilû âle fir`avne eşedde-l`aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'veiẕ yeteḥâccûne fi-nnâri feyeḳûlu-ḍḍu`afâü lilleẕîne-stekberû innâ künnâ leküm tebe`an fehel entüm mugnûne `annâ neṣîbem mine-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'ḳâle-lleẕîne-stekberû innâ küllün fîhâ inne-llâhe ḳad ḥakeme beyne-l`ibâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'veḳâle-lleẕîne fi-nnâri liḫazeneti cehenneme-d`û rabbeküm yüḫaffif `annâ yevmem mine-l`aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, 'ḳâlû evelem tekü te''tîküm rusülüküm bilbeyyinât. ḳâlû belâ. ḳâlû fed`û. vemâ dü`âü-lkâfirîne illâ fî ḍalâl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'innâ lenenṣuru rusülenâ velleẕîne âmenû fi-lḥayâti-ddünyâ veyevme yeḳûmü-l''eşhâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'yevme lâ yenfe`u-żżâlimîne ma`ẕiratühüm velehümü-lla`netü velehüm sûü-ddâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'veleḳad âteynâ mûse-lhüdâ veevraŝnâ benî isrâîle-lkitâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'hüdev veẕikrâ liüli-l''elbâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'faṣbir inne va`de-llâhi ḥaḳḳuv vestagfir liẕembike vesebbiḥ biḥamdi rabbike bil`aşiyyi vel''ibkâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'inne-lleẕîne yücâdilûne fî âyâti-llâhi bigayri sülṭânin etâhüm in fî ṣudûrihim illâ kibrum mâ hüm bibâligîh. feste`iẕ billâh. innehû hüve-ssemî`u-lbeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'leḫalḳu-ssemâvâti vel''arḍi ekberu min ḫalḳi-nnâsi velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'vemâ yestevi-l''a`mâ velbeṣîru velleẕîne âmenû ve`amilu-ṣṣâliḥâti vele-lmüsî''. ḳalîlem mâ teteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'inne-ssâ`ate leâtiyetül lâ raybe fîhâ velâkinne ekŝera-nnâsi lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'veḳâle rabbükümü-d`ûnî estecib leküm. inne-lleẕîne yestekbirûne `an `ibâdetî seyedḫulûne cehenneme dâḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'allâhü-lleẕî ce`ale lekümü-lleyle liteskünû fîhi vennehâra mübṣirâ. inne-llâhe leẕû faḍlin `ale-nnâsi velâkinne ekŝera-nnâsi lâ yeşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'ẕâlikümü-llâhü rabbüküm ḫâliḳu külli şey''. lâ ilâhe illâ hû. feennâ tü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'keẕâlike yü''fekü-lleẕîne kânû biâyâti-llâhi yecḥadûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'allâhü-lleẕî ce`ale lekümü-l''arḍa ḳarârav vessemâe binâev veṣavveraküm feaḥsene ṣuveraküm verazeḳaküm mine-ṭṭayyibât. ẕâlikümü-llâhü rabbüküm. fetebârake-llâhü rabbü-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'hüve-lḥayyü lâ ilâhe illâ hüve fed`ûhü muḫliṣîne lehü-ddîn. elḥamdü lillâhi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'ḳul innî nühîtü en a`büde-lleẕîne ted`ûne min dûni-llâhi lemmâ câeniye-lbeyyinâtü mir rabbî veümirtü en üslime lirabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'hüve-lleẕî ḫaleḳaküm min türâbin ŝümme min nuṭfetin ŝümme min `aleḳatin ŝümme yuḫricüküm ṭiflen ŝümme liteblügû eşüddeküm ŝümme litekûnû şüyûḫâ. veminküm mey yüteveffâ min ḳablü veliteblügû ecelem müsemmev vele`alleküm ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'hüve-lleẕî yuḥyî veyümît. feiẕâ ḳaḍâ emran feinnemâ yeḳûlü lehû kün feyekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'elem tera ile-lleẕîne yücâdilûne fî âyâti-llâh. ennâ yuṣrafûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'elleẕîne keẕẕebû bilkitâbi vebimâ erselnâ bihî rusülenâ. fesevfe ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'iẕi-l''aglâlü fî a`nâḳihim vesselâsil. yüsḥabûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'fi-lḥamîmi ŝümme fi-nnâri yüscerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'ŝümme ḳîle lehüm eyne mâ küntüm tüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'min dûni-llâh. ḳâlû ḍallû `annâ bel lem nekün ned`û min ḳablü şey''â. keẕâlike yüḍillü-llâhü-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, 'ẕâliküm bimâ küntüm tefraḥûne fi-l''arḍi bigayri-lḥaḳḳi vebimâ küntüm temraḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'üdḫulû ebvâbe cehenneme ḫâlidîne fîhâ. febi''se meŝve-lmütekebbirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'faṣbir inne va`de-llâhi ḥaḳḳun. feimmâ nüriyenneke ba`ḍa-lleẕî ne`idühüm ev neteveffeyenneke feileynâ yürce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'veleḳad erselnâ rusülem min ḳablike minhüm men ḳaṣaṣnâ `aleyke veminhüm mel lem naḳṣuṣ `aleyk. vemâ kâne lirasûlin ey ye''tiye biâyetin illâ biiẕni-llâh. feiẕâ câe emru-llâhi ḳuḍiye bilḥaḳḳi veḫasira hünâlike-lmübṭilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'allâhü-lleẕî ce`ale lekümü-l''en`âme literkebû minhâ veminhâ te''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'veleküm fîhâ menâfi`u veliteblügû `aleyhâ ḥâceten fî ṣudûriküm ve`aleyhâ ve`ale-lfülki tuḥmelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'veyürîküm âyâtih. feeyye âyâti-llâhi tünkirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'efelem yesîrû fi-l''arḍi feyenżurû keyfe kâne `âḳibetü-lleẕîne min ḳablihim. kânû ekŝera minhüm veeşedde ḳuvvetev veâŝâran fi-l''arḍi femâ agnâ `anhüm mâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'felemmâ câethüm rusülühüm bilbeyyinâti feriḥû bimâ `indehüm mine-l`ilmi veḥâḳa bihim mâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'felemmâ raev be''senâ ḳâlû âmennâ billâhi vaḥdehû vekefernâ bimâ künnâ bihî müşrikîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'felem yekü yenfe`uhüm îmânühüm lemmâ raev be''senâ. sünnete-llâhi-lletî ḳad ḫalet fî `ibâdih. veḫasira hünâlike-lkâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, 'tenzîlüm mine-rraḥmâni-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'kitâbün füṣṣilet âyâtühû ḳur''ânen `arabiyyel liḳavmiy ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'beşîrav veneẕîrâ. fea`raḍa ekŝeruhüm fehüm lâ yesme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'veḳâlû ḳulûbünâ fî ekinnetim mimmâ ted`ûnâ ileyhi vefî âẕâninâ vaḳruv vemim beyninâ vebeynike ḥicâbün fa`mel innenâ `âmilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'ḳul innemâ ene beşerum miŝlüküm yûḥâ ileyye ennemâ ilâhüküm ilâhüv vâḥidün festeḳîmû ileyhi vestagfirûh. veveylül lilmüşrikîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'elleẕîne lâ yü''tûne-zzekâte vehüm bil''âḫirati hüm kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'inne-lleẕîne âmenû ve`amilu-ṣṣâliḥâti lehüm ecrun gayru memnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'ḳul einneküm letekfürûne billeẕî ḫaleḳa-l''arḍa fî yevmeyni vetec`alûne lehû endâdâ. ẕâlike rabbü-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'vece`ale fîhâ ravâsiye min fevḳihâ vebârake fîhâ veḳaddera fîhâ aḳvâtehâ fî erbe`ati eyyâm. sevâel lissâilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'ŝümme-stevâ ile-ssemâi vehiye düḫânün feḳâle lehâ velil''arḍi-''tiyâ ṭav`an ev kerhâ. ḳâletâ eteynâ ṭâi`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'feḳaḍâhünne seb`a semâvâtin fî yevmeyni veevḥâ fî külli semâin emrahâ. vezeyyenne-ssemâe-ddünyâ bimeṣâbîḥ. veḥifżâ. ẕâlike taḳdîru-l`azîzi-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'fein a`raḍû feḳul enẕertüküm ṣâ`iḳatem miŝle ṣâ`iḳati `âdiv veŝemûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'iẕ câethümü-rrusülü mim beyni eydîhim vemin ḫalfihim ellâ ta`büdû ille-llâh. ḳâlû lev şâe rabbünâ leenzele melâiketen feinnâ bimâ ürsiltüm bihî kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'feemmâ `âdün festekberû fi-l''arḍi bigayri-lḥaḳḳi veḳâlû men eşeddü minnâ ḳuvveh. evelem yerav enne-llâhe-lleẕî ḫaleḳahüm hüve eşeddü minhüm ḳuvveh. vekânû biâyâtinâ yecḥadûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'feerselnâ `aleyhim rîḥan ṣarṣaran fî eyyâmin neḥisâtil linüẕîḳahüm `aẕâbe-lḫizyi fi-lḥayâti-ddünyâ. vele`aẕâbü-l''âḫirati aḫzâ vehüm lâ yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'veemmâ ŝemûdü fehedeynâhüm festeḥabbü-l`amâ `ale-lhüdâ feeḫaẕethüm ṣâ`iḳatü-l`aẕâbi-lhûni bimâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'venecceyne-lleẕîne âmenû vekânû yetteḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'veyevme yuḥşeru a`dâü-llâhi ile-nnâri fehüm yûza`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'ḥattâ iẕâ mâ câûhâ şehide `aleyhim sem`uhüm veebṣâruhüm vecülûdühüm bimâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'veḳâlû licülûdihim lime şehittüm `aleynâ. ḳâlû enṭaḳane-llâhü-lleẕî enṭaḳa külle şey''iv vehüve ḫaleḳaküm evvele merrativ veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'vemâ küntüm testetirûne ey yeşhede `aleyküm sem`uküm velâ ebṣâruküm velâ cülûdüküm velâkin żanentüm enne-llâhe lâ ya`lemü keŝîram mimmâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'veẕâliküm żannükümü-lleẕî żanentüm birabbiküm erdâküm feaṣbaḥtüm mine-lḫâsirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'feiy yaṣbirû felnâru meŝvel lehüm. veiy yesta`tibû femâ hüm mine-lmü`tebîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'veḳayyaḍnâ lehüm ḳuranâe fezeyyenû lehüm mâ beyne eydîhim vemâ ḫalfehüm veḥaḳḳa `aleyhimü-lḳavlü fî ümemin ḳad ḫalet min ḳablihim mine-lcinni vel''ins. innehüm kânû ḫâsirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'veḳâle-lleẕîne keferû lâ tesme`û lihâẕe-lḳur''âni velgav fîhi le`alleküm taglibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'felenüẕîḳanne-lleẕîne keferû `aẕâben şedîdev velenecziyennehüm esvee-lleẕî kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'ẕâlike cezâü a`dâi-llâhi-nnâru. lehüm fîhâ dâru-lḫuld. cezâem bimâ kânû biâyâtinâ yecḥadûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'veḳâle-lleẕîne keferû rabbenâ erine-lleẕeyni eḍallânâ mine-lcinni vel''insi nec`alhümâ taḥte aḳdâminâ liyekûnâ mine-l''esfelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'inne-lleẕîne ḳâlû rabbüne-llâhü ŝümme-steḳâmû tetenezzelü `aleyhimü-lmelâiketü ellâ teḫâfû velâ taḥzenû veebşirû bilcenneti-lletî küntüm tû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'naḥnü evliyâüküm fi-lḥayâti-ddünyâ vefi-l''âḫirah. veleküm fîhâ mâ teştehî enfüsüküm veleküm fîhâ mâ tedde`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'nüzülem min gafûrir raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'vemen aḥsenü ḳavlem mimmen de`â ile-llâhi ve`amile ṣâliḥav veḳâle innenî mine-lmüslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'velâ testevi-lḥasenetü vele-sseyyieh. idfa` billetî hiye aḥsenü feiẕe-lleẕî beyneke vebeynehû `adâvetün keennehû veliyyün ḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'vemâ yüleḳḳâhâ ille-lleẕîne ṣaberû. vemâ yüleḳḳâhâ illâ ẕû ḥażżin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'veimmâ yenzeganneke mine-şşeyṭâni nezgun feste`iẕ billâh. innehû hüve-ssemî`u-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'vemin âyâtihi-lleylü vennehâru veşşemsü velḳamer. lâ tescüdû lişşemsi velâ lilḳameri vescüdû lillâhi-lleẕî ḫaleḳahünne in küntüm iyyâhü ta`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'feini-stekberû felleẕîne `inde rabbike yüsebbiḥûne lehû billeyli vennehâri vehüm lâ yes''emûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'vemin âyâtihî enneke tera-l''arḍa ḫâşi`aten feiẕâ enzelnâ `aleyhe-lmâe-htezzet verabet. inne-lleẕî aḥyâhâ lemuḥyi-lmevtâ. innehû `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'inne-lleẕîne yülḥidûne fî âyâtinâ lâ yaḫfevne `aleynâ. efemey yülḳâ fi-nnâri ḫayrun em mey ye''tî âminey yevme-lḳiyâmeh. i`melû mâ şi''tüm innehû bimâ ta`melûne beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'inne-lleẕîne keferû biẕẕikri lemmâ câehüm. veinnehû lekitâbün `azîz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'lâ ye''tîhi-lbâṭilü mim beyni yedeyhi velâ min ḫalfih. tenzîlüm min ḥakîmin ḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'mâ yüḳâlü leke illâ mâ ḳad ḳîle lirrusüli min ḳablik. inne rabbeke leẕû magfirativ veẕû `iḳâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'velev ce`alnâhü ḳur''ânen a`cemiyyel leḳâlû levlâ füṣṣilet âyâtüh. ea`cemiyyüv ve`arabiyy. ḳul hüve lilleẕîne âmenû hüdev veşifâün. velleẕîne lâ yü''minûne fî âẕânihim vaḳruv vehüve `aleyhim `amâ. ülâike yünâdevne mim mekânim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'veleḳad âteynâ mûse-lkitâbe faḫtülife fîh. velevlâ kelimetün sebeḳat mir rabbike leḳuḍiye beynehüm. veinnehüm lefî şekkim minhü mürîbün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'men `amile ṣâliḥan felinefsihî vemen esâe fe`aleyhâ. vemâ rabbüke biżallâmil lil`abîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'ileyhi yüraddü `ilmü-ssâ`ah. vemâ taḫrucü min ŝemerâtim min ekmâmihâ vemâ taḥmilü min ünŝâ velâ teḍa`u illâ bi`ilmih. veyevme yünâdîhim eyne şürakâî ḳâlû âẕennâke mâ minnâ min şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'veḍalle `anhüm mâ kânû yed`ûne min ḳablü veżannû mâ lehüm mim meḥîṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'lâ yes''emü-l''insânü min dü`âi-lḫayr. veim messehü-şşerru feyeûsün ḳanûṭ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'velein eẕaḳnâhü raḥmetem minnâ mim ba`di ḍarrâe messethü leyeḳûlenne hâẕâ lî vemâ eżunnü-ssâ`ate ḳâimetev veleir ruci`tü ilâ rabbî inne lî `indehû lelḥusnâ. felenünebbienne-lleẕîne keferû bimâ `amilû. velenüẕîḳannehüm min `aẕâbin galîż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'veiẕâ en`amnâ `ale-l''insâni a`raḍa veneâ bicânibih. veiẕâ messehü-şşerru feẕû dü`âin `arîḍ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'ḳul era''eytüm in kâne min `indi-llâhi ŝümme kefertüm bihî men eḍallü mimmen hüve fî şiḳâḳim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'senürîhim âyâtinâ fi-l''âfâḳi vefî enfüsihim ḥattâ yetebeyyene lehüm ennehü-lḥaḳḳ. evelem yekfi birabbike ennehû `alâ külli şey''in şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'elâ innehüm fî miryetim mil liḳâi rabbihim. elâ innehû bikülli şey''im müḥîṭ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, '`ayn-sîn-ḳâf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'keẕâlike yûḥî ileyke veile-lleẕîne min ḳablike-llâhü-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'lehû mâ fi-ssemâvâti vemâ fi-l''arḍ. vehüve-l`aliyyü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'tekâdü-ssemâvâtü yetefeṭṭarne min fevḳihinne velmelâiketü yüsebbiḥûne biḥamdi rabbihim veyestagfirûne limen fi-l''arḍ. elâ inne-llâhe hüve-lgafûru-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'velleẕîne-tteḫaẕû min dûnihî evliyâe-llâhü ḥafîżun `aleyhim. vemâ ente `aleyhim bivekîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'vekeẕâlike evḥaynâ ileyke ḳur''ânen `arabiyyel litünẕira ümme-lḳurâ vemen ḥavlehâ vetünẕira yevme-lcem`i lâ raybe fîh. ferîḳun fi-lcenneti veferîḳun fi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'velev şâe-llâhü lece`alehüm ümmetev vâḥidetev velâkiy yüdḫilü mey yeşâü fî raḥmetih. veżżâlimûne mâ lehüm miv veliyyiv velâ neṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'emi-tteḫaẕû min dûnihî evliyâ''. fellâhü hüve-lveliyyü vehüve yuḥyi-lmevtâ. vehüve `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'veme-ḫteleftüm fîhi min şey''in feḥukmühû ile-llâh. ẕâlikümü-llâhü rabbî `aleyhi tevekkelt. veileyhi ünîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, 'fâṭiru-ssemâvâti vel''arḍ. ce`ale leküm min enfüsiküm ezvâcev vemine-l''en`âmi ezvâcâ. yeẕraüküm fîh. leyse kemiŝlihî şey''. vehüve-ssemî`u-lbeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'lehû meḳâlîdü-ssemâvâti vel''arḍ. yebsüṭu-rrizḳa limey yeşâü veyaḳdir. innehû bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'şera`a leküm mine-ddîni mâ veṣṣâ bihî nûḥav velleẕî evḥaynâ ileyke vemâ veṣṣaynâ bihî ibrâhîme vemûsâ ve`îsâ en eḳîmü-ddîne velâ teteferraḳû fîh. kebüra `ale-lmüşrikîne mâ ted`ûhüm ileyh. allâhü yectebî ileyhi mey yeşâü veyehdî ileyhi mey yünîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'vemâ teferraḳû illâ mim ba`di mâ câehümü-l`ilmü bagyem beynehüm. velevlâ kelimetün sebeḳat mir rabbike ilâ ecelim müsemmel leḳuḍiye beynehüm. veinne-lleẕîne ûriŝü-lkitâbe mim ba`dihim lefî şekkim minhü mürîbün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'feliẕâlike fed`u. vesteḳim kemâ ümirt. velâ tettebi` ehvâehüm. veḳul âmentü bimâ enzele-llâhü min kitâb. veümirtü lia`dile beyneküm. allâhü rabbünâ verabbüküm. lenâ a`mâlünâ veleküm a`mâlüküm. lâ ḥuccete beynenâ vebeyneküm. allâhü yecme`u beynenâ. veileyhi-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'velleẕîne yüḥâccûne fi-llâhi mim ba`di me-stücîbe lehû ḥuccetühüm dâḥiḍatün `inde rabbihim ve`aleyhim gaḍabüv velehüm `aẕâbün şedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'allâhü-lleẕî enzele-lkitâbe bilḥaḳḳi velmîzân. vemâ yüdrîke le`alle-ssâ`ate ḳarîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'yesta`cilü bihe-lleẕîne lâ yü''minûne bihâ. velleẕîne âmenû müşfiḳûne minhâ veya`lemûne ennehe-lḥaḳḳ. elâ inne-lleẕîne yümârûne fi-ssâ`ati lefî ḍalâlim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'allâhü leṭîfüm bi`ibâdihî yerzüḳu mey yeşâ''. vehüve-lḳaviyyü-l`azîz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'men kâne yürîdü ḥarŝe-l''âḫirati nezid lehû fî ḥarŝih. vemen kâne yürîdü ḥarŝe-ddünyâ nü''tihî minhâ vemâ lehû fi-l''âḫirati min neṣîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'em lehüm şürakâü şera`û lehüm mine-ddîni mâ lem ye''ẕem bihi-llâh. velevlâ kelimetü-lfaṣli leḳuḍiye beynehüm. veinne-żżâlimîne lehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'tera-żżâlimîne müşfiḳîne mimmâ kesebû vehüve vâḳi`um bihim. velleẕîne âmenû ve`amilu-ṣṣâliḥâti fî ravḍâti-lcennât. lehüm mâ yeşâûne `inde rabbihim. ẕâlike hüve-lfaḍlü-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'ẕâlike-lleẕî yübeşşiru-llâhü `ibâdehü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti. ḳul lâ es''elüküm `aleyhi ecran ille-lmeveddete fi-lḳurbâ. vemey yaḳterif ḥaseneten nezid lehû fîhâ ḥusnâ. inne-llâhe gafûrun şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'em yeḳûlûne-fterâ `ale-llâhi keẕibâ. feiy yeşei-llâhü yaḫtim `alâ ḳalbik. veyemḥu-llâhü-lbâṭile veyüḥiḳḳu-lḥaḳḳa bikelimâtih. innehû `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'vehüve-lleẕî yaḳbelü-ttevbete `an `ibâdihî veya`fû `ani-sseyyiâti veya`lemü mâ tef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'veyestecîbü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti veyezîdühüm min faḍlih. velkâfirûne lehüm `aẕâbün şedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'velev beseṭa-llâhü-rrizḳa li`ibâdihî lebegav fi-l''arḍi velâkiy yünezzilü biḳaderim mâ yeşâ''. innehû bi`ibâdihî ḫabîrum beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'vehüve-lleẕî yünezzilü-lgayŝe mim ba`di mâ ḳaneṭû veyenşüru raḥmeteh. vehüve-lveliyyü-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'vemin âyâtihî ḫalḳu-ssemâvâti vel''arḍi vemâ beŝŝe fîhimâ min dâbbeh. vehüve `alâ cem`ihim iẕâ yeşâü ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'vemâ eṣâbeküm mim müṣîbetin febimâ kesebet eydîküm veya`fû `an keŝîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'vemâ entüm bimü`cizîne fi-l''arḍ. vemâ leküm min dûni-llâhi miv veliyyiv velâ neṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'vemin âyâtihi-lcevâri fi-lbaḥri kel''a`lâm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'iy yeşe'' yüskini-rrîḥa feyażlelne ravâkide `alâ żahrih. inne fî ẕâlike leâyâtil likülli ṣabbârin şekûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'ev yûbiḳhünne bimâ kesebû veya`fü `an keŝîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'veya`leme-lleẕîne yücâdilûne fî âyâtinâ. mâ lehüm mim meḥîṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'femâ ûtîtüm min şey''in femetâ`u-lḥayâti-ddünyâ. vemâ `inde-llâhi ḫayruv veebḳâ lilleẕîne âmenû ve`alâ rabbihim yetevekkelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'velleẕîne yectenibûne kebâira-l''iŝmi velfevâḥişe veiẕâ mâ gaḍibû hüm yagfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'velleẕîne-stecâbû lirabbihim veeḳâmu-ṣṣalâh. veemruhüm şûrâ beynehüm. vemimmâ razaḳnâhüm yünfiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'velleẕîne iẕâ eṣâbehümü-lbagyü hüm yenteṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'vecezâü seyyietin seyyietüm miŝlühâ. femen `afâ veaṣleḥa feecruhû `ale-llâh. innehû lâ yüḥibbu-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'velemeni-nteṣara ba`de żulmihî feülâike mâ `aleyhim min sebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'inneme-ssebîlü `ale-lleẕîne yażlimûne-nnâse veyebgûne fi-l''arḍi bigayri-lḥaḳḳ. ülâike lehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'velemen ṣabera vegafera inne ẕâlike lemin `azmi-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'vemey yuḍlili-llâhü femâ lehû miv veliyyim mim ba`dih. vetera-żżâlimîne lemmâ raevu-l`aẕâbe yeḳûlûne hel ilâ meraddim min sebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'veterâhüm yü`raḍûne `aleyhâ ḫâşi`îne mine-ẕẕülli yenżurûne min ṭarfin ḫafiyy. veḳâle-lleẕîne âmenû inne-lḫâsirîne-lleẕîne ḫasirû enfüsehüm veehlîhim yevme-lḳiyâmeh. elâ inne-żżâlimîne fî `aẕâbim müḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'vemâ kâne lehüm min evliyâe yenṣurûnehüm min dûni-llâh. vemey yuḍlili-llâhü femâ lehû min sebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'istecîbû lirabbiküm min ḳabli ey ye''tiye yevmül lâ meradde lehû mine-llâh. mâ leküm mim melceiy yevmeiẕiv vemâ leküm min nekîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'fein a`raḍû femâ erselnâke `aleyhim ḥafîżâ. in `aleyke ille-lbelâg. veinnâ iẕâ eẕaḳne-l''insâne minnâ raḥmeten feriḥa bihâ. vein tüṣibhüm seyyietüm bimâ ḳaddemet eydîhim feinne-l''insâne kefûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'lillâhi mülkü-ssemâvâti vel''arḍ. yaḫlüḳu mâ yeşâ''. yehebü limey yeşâü inâŝev veyehebü limey yeşâü-ẕẕükûra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'ev yüzevvicühüm ẕükrânev veinâŝâ. veyec`alü mey yeşâü `aḳîmâ. innehû `alîmün ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'vemâ kâne libeşerin ey yükellimehü-llâhü illâ vaḥyen ev miv verâi ḥicâbin ev yürsile rasûlen feyûḥiye biiẕnihî mâ yeşâ''. innehû `aliyyün ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'vekeẕâlike evḥaynâ ileyke rûḥam min emrinâ. mâ künte tedrî me-lkitâbü vele-l''îmânü velâkin ce`alnâhü nûran nehdî bihî men neşâü min `ibâdinâ. veinneke letehdî ilâ ṣirâṭim müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'ṣirâṭi-llâhi-lleẕî lehû mâ fi-ssemâvâti vemâ fi-l''arḍ. elâ ile-llâhi teṣîru-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'velkitâbi-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'innâ ce`alnâhü ḳur''ânen `arabiyyel le`alleküm ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'veinnehû fî ümmi-lkitâbi ledeynâ le`aliyyün ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'efenaḍribü `ankümü-ẕẕikra ṣafḥan en küntüm ḳavmem müsrifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'vekem erselnâ min nebiyyin fi-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'vemâ ye''tîhim min nebiyyin illâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'feehleknâ eşedde minhüm baṭşev vemeḍâ meŝelü-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'velein seeltehüm men ḫaleḳa-ssemâvâti vel''arḍa leyeḳûlünne ḫaleḳahünne-l`azîzü-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, 'elleẕî ce`ale lekümü-l''arḍa mehdev vece`ale leküm fîhâ sübülel le`alleküm tehtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'velleẕî nezzele mine-ssemâi mâem biḳader. feenşernâ bihî beldetem meytâ. keẕâlike tuḫracûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'velleẕî ḫaleḳa-l''ezvâce küllehâ vece`ale leküm mine-lfülki vel''en`âmi mâ terkebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'litestevû `alâ żuhûrihî ŝümme teẕkürû ni`mete rabbiküm iẕe-steveytüm `aleyhi veteḳûlû sübḥâne-lleẕî seḫḫara lenâ hâẕâ vemâ künnâ lehû muḳrinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'veinnâ ilâ rabbinâ lemünḳalibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'vece`alû lehû min `ibâdihî cüz''â. inne-l''insâne lekefûrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'emi-tteḫaẕe mimmâ yaḫlüḳu benâtiv veaṣfâküm bilbenîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'veiẕâ büşşira eḥadühüm bimâ ḍarabe lirraḥmâni meŝelen żalle vechühû müsveddev vehüve keżîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'evemey yüneşşeü fi-lḥilyeti vehüve fi-lḫiṣâmi gayru mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'vece`alü-lmelâikete-lleẕîne hüm `ibâdü-rraḥmâni inâŝâ. eşehidû ḫalḳahüm. setüktebü şehâdetühüm veyüs''elûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'veḳâlû lev şâe-rraḥmânü mâ `abednâhüm. mâ lehüm biẕâlike min `ilm. in hüm illâ yaḫruṣûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'em âteynâhüm kitâbem min ḳablihî fehüm bihî müstemsikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'bel ḳâlû innâ vecednâ âbâenâ `alâ ümmetiv veinnâ `alâ âŝârihim mühtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'vekeẕâlike mâ erselnâ min ḳablike fî ḳaryetim min neẕîrin illâ ḳâle mütrafûhâ innâ vecednâ âbâenâ `alâ ümmetiv veinnâ `alâ âŝârihim muḳtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, 'ḳâle evelev ci''tüküm biehdâ mimmâ vecettüm `aleyhi âbâeküm. ḳâlû innâ bimâ ürsiltüm bihî kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'fenteḳamnâ minhüm fenżur keyfe kâne `âḳibetü-lmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'veiẕ ḳâle ibrâhîmü liebîhi veḳavmihî innenî berâüm mimmâ ta`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'ille-lleẕî feṭaranî feinnehû seyehdîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'vece`alehâ kelimetem bâḳiyeten fî `aḳibihî le`allehüm yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'bel metta`tü hâülâi veâbâehüm ḥattâ câehümü-lḥaḳḳu verasûlüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'velemmâ câehümü-lḥaḳḳu ḳâlû hâẕâ siḥruv veinnâ bihî kâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'veḳâlû levlâ nüzzile hâẕe-lḳur''ânü `alâ racülim mine-lḳaryeteyni `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'ehüm yaḳsimûne raḥmete rabbik. naḥnü ḳasemnâ beynehüm me`îşetehüm fi-lḥayâti-ddünyâ verafa`nâ ba`ḍahüm fevḳa ba`ḍin deracâtil liyetteḫiẕe ba`ḍuhüm ba`ḍan suḫriyyâ. veraḥmetü rabbike ḫayrum mimmâ yecme`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'velevlâ ey yekûne-nnâsü ümmetev vâḥidetel lece`alnâ limey yekfüru birraḥmâni libüyûtihim süḳufem min fiḍḍativ veme`ârice `aleyhâ yażherûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'velibüyûtihim ebvâbev vesüruran `aleyhâ yettekiûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'vezuḫrufâ. vein küllü ẕâlike lemmâ metâ`u-lḥayâti-ddünyâ. vel''âḫiratü `inde rabbike lilmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'vemey ya`şü `an ẕikri-rraḥmâni nüḳayyiḍ lehû şeyṭânen fehüve lehû ḳarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'veinnehüm leyeṣuddûnehüm `ani-ssebîli veyaḥsebûne ennehüm mühtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'ḥattâ iẕâ câenâ ḳâle yâ leyte beynî vebeyneke bü`de-lmeşriḳayni febi''se-lḳarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'veley yenfe`akümü-lyevme iż żalemtüm enneküm fi-l`aẕâbi müşterikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'efeente tüsmi`u-ṣṣumme ev tehdi-l`umye vemen kâne fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'feimmâ neẕhebenne bike feinnâ minhüm münteḳimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'ev nüriyenneke-lleẕî ve`adnâhüm feinnâ `aleyhim muḳtedirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'festemsik billeẕî ûḥiye ileyk. inneke `alâ ṣirâṭim müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'veinnehû leẕikrul leke veliḳavmik. vesevfe tüs''elûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'ves''el men erselnâ min ḳablike mir rusülinâ. ece`alnâ min dûni-rraḥmâni âlihetey yü`bedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'veleḳad erselnâ mûsâ biâyâtinâ ilâ fir`avne vemeleihî feḳâle innî rasûlü rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'felemmâ câehüm biâyâtinâ iẕâ hüm minhâ yaḍḥakûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'vemâ nürîhim min âyetin illâ hiye ekberu min uḫtihâ. veeḫaẕnâhüm bil`aẕâbi le`allehüm yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'veḳâlû yâ eyyühe-ssâḥiru-d`u lenâ rabbeke bimâ `ahide `indeke innenâ lemühtedûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'felemmâ keşefnâ `anhümü-l`aẕâbe iẕâ hüm yenküŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'venâdâ fir`avnü fî ḳavmihî ḳâle yâ ḳavmi eleyse lî mülkü miṣra vehâẕihi-l''enhâru tecrî min taḥtî. efelâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'em ene ḫayrum min hâẕe-lleẕî hüve mehînüv velâ yekâdü yübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'felevlâ ülḳiye `aleyhi esviratüm min ẕehebin ev câe me`ahü-lmelâiketü muḳterinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'festeḫaffe ḳavmehû feeṭâ`ûh. innehüm kânû ḳavmen fâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'felemmâ âsefûne-nteḳamnâ minhüm feagraḳnâhüm ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'fece`alnâhüm selefev vemeŝelel lil''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'velemmâ ḍuribe-bnü meryeme meŝelen iẕâ ḳavmüke minhü yeṣiddûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'veḳâlû eâlihetünâ ḫayrun em hû. mâ ḍarabûhü leke illâ cedelâ. bel hüm ḳavmün ḫasimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'in hüve illâ `abdün en`amnâ `aleyhi vece`alnâhü meŝelel libenî isrâîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'velev neşâü lece`alnâ minküm melâiketen fi-l''arḍi yaḫlüfûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'veinnehû le`ilmül lissâ`ati felâ temterunne bihâ vettebi`ûn. hâẕâ ṣirâṭum müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'velâ yeṣuddennekümü-şşeyṭân. innehû leküm `adüvvüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'velemmâ câe `îsâ bilbeyyinâti ḳâle ḳad ci''tüküm bilḥikmeti veliübeyyine leküm ba`ḍa-lleẕî taḫtelifûne fîh. fetteḳu-llâhe veeṭî`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'inne-llâhe hüve rabbî verabbüküm fa`büdûh. hâẕâ ṣirâṭum müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'faḫtelefe-l''aḥzâbü mim beynihim. feveylül lilleẕîne żalemû min `aẕâbi yevmin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'hel yenżurûne ille-ssâ`ate en te''tiyehüm bagtetev vehüm lâ yeş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'el''eḫillâü yevmeiẕim ba`ḍuhüm liba`ḍin `adüvvün ille-lmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, 'yâ `ibâdi lâ ḫavfün `aleykümü-lyevme velâ entüm taḥzenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, 'elleẕîne âmenû biâyâtinâ vekânû müslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'üdḫulü-lcennete entüm veezvâcüküm tuḥberûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'yüṭâfü `aleyhim biṣiḥâfim min ẕehebiv veekvâb. vefîhâ mâ teştehîhi-l''enfüsü veteleẕẕü-l''a`yün. veentüm fîhâ ḫâlidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'vetilke-lcennetü-lletî ûriŝtümûhâ bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'leküm fîhâ fâkihetün keŝîratüm minhâ te''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'inne-lmücrimîne fî `aẕâbi cehenneme ḫâlidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'lâ yüfetteru `anhüm vehüm fîhi müblisûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'vemâ żalemnâhüm velâkin kânû hümu-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'venâdev yâ mâlikü liyaḳḍi `aleynâ rabbük. ḳâle inneküm mâkiŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'leḳad ci''nâküm bilḥaḳḳi velâkinne ekŝeraküm lilḥaḳḳi kârihûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'em ebramû emran feinnâ mübrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'em yaḥsebûne ennâ lâ nesme`u sirrahüm venecvâhüm. belâ verusülünâ ledeyhim yektübûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'ḳul in kâne lirraḥmâni veled. feenâ evvelü-l`âbidîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'sübḥâne rabbi-ssemâvâti vel''arḍi rabbi-l`arşi `ammâ yeṣifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'feẕerhüm yeḫûḍû veyel`abû ḥattâ yülâḳû yevmehümü-lleẕî yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'vehüve-lleẕî fi-ssemâi ilâhüv vefi-l''arḍi ilâhün. vehüve-lḥakîmü-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'vetebârake-lleẕî lehû mülkü-ssemâvâti vel''arḍi vemâ beynehümâ. ve`indehû `ilmü-ssâ`ah. veileyhi türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'velâ yemlikü-lleẕîne yed`ûne min dûnihi-şşefâ`ate illâ men şehide bilḥaḳḳi vehüm ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'velein seeltehüm men ḫaleḳahüm leyeḳûlünne-llâhü feennâ yü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'veḳîlihî yâ rabbi inne hâülâi ḳavmül lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'faṣfaḥ `anhüm veḳul selâm. fesevfe ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'velkitâbi-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'innâ enzelnâhü fî leyletim mübâraketin innâ künnâ münẕirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'fîhâ yüfraḳu küllü emrin ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'emram min `indinâ. innâ künnâ mürsilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'raḥmetem mir rabbik. innehû hüve-ssemî`u-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'rabbi-ssemâvâti vel''arḍi vemâ beynehümâ. in küntüm mûḳinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'lâ ilâhe illâ hüve yuḥyî veyümît. rabbüküm verabbü âbâikümü-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'bel hüm fî şekkiy yel`abûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'ferteḳib yevme te''ti-ssemâü bidüḫânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'yagşe-nnâs. hâẕâ `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, 'rabbene-kşif `anne-l`aẕâbe innâ mü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'ennâ lehümü-ẕẕikrâ veḳad câehüm rasûlüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'ŝümme tevellev `anhü veḳâlû mü`allemüm mecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'innâ kâşifü-l`aẕâbi ḳalîlen inneküm `âidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'yevme nebṭişü-lbaṭşete-lkübrâ. innâ münteḳimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'veleḳad fetennâ ḳablehüm ḳavme fir`avne vecâehüm rasûlün kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, 'en eddû ileyye `ibâde-llâh. innî leküm rasûlün emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'veel lâ ta`lû `ale-llâh. innî âtîküm bisülṭânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'veinnî `uẕtü birabbî verabbiküm en tercümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'veil lem tü''minû lî fa`tezilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'fede`â rabbehû enne hâülâi ḳavmüm mücrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, 'feesri bi`ibâdî leylen inneküm müttebe`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'vetruki-lbaḥra rahvâ. innehüm cündüm mugraḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'kem terakû min cennâtiv ve`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'vezürû`iv vemeḳâmin kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'vena`metin kânû fîhâ fâkihîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'keẕâlik. veevraŝnâhâ ḳavmen âḫarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'femâ beket `aleyhimü-ssemâü vel''arḍu vemâ kânû münżarîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'veleḳad necceynâ benî isrâîle mine-l`aẕâbi-lmühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'min fir`avn. innehû kâne `âliyem mine-lmüsrifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'veleḳadi-ḫternâhüm `alâ `ilmin `ale-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'veâteynâhüm mine-l''âyâti mâ fîhi belâüm mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'inne hâülâi leyeḳûlûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, 'in hiye illâ mevtetüne-l''ûlâ vemâ naḥnü bimünşerîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'fe''tû biâbâinâ in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'ehüm ḫayrun em ḳavmü tübbe`iv velleẕîne min ḳablihim. ehleknâhüm. innehüm kânû mücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'vemâ ḫalaḳne-ssemâvâti vel''arḍa vemâ beynehümâ lâ`ibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'mâ ḫalaḳnâhümâ illâ bilḥaḳḳi velâkinne ekŝerahüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'inne yevme-lfaṣli mîḳâtühüm ecme`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'yevme lâ yugnî mevlen `am mevlen şey''ev velâ hüm yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'illâ mer raḥime-llâh. innehû hüve-l`azîzü-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'inne şecerate-zzeḳḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'ṭa`âmü-l''eŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'kelmühl. yaglî fi-lbüṭûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'kegalyi-lḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, 'ḫuẕûhü fa`tilûhü ilâ sevâi-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'ŝümme ṣubbû fevḳa ra''sihî min `aẕâbi-lḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, 'ẕuḳ. inneke ente-l`azîzü-lkerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'inne hâẕâ mâ küntüm bihî temterûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'inne-lmütteḳîne fî meḳâmin emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'fî cennâtiv ve`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'yelbesûne min sündüsiv veistebraḳim müteḳâbilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'keẕâlik. vezevvecnâhüm biḥûrin `în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'yed`ûne fîhâ bikülli fâkihetin âminîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'lâ yeẕûḳûne fîhe-lmevte ille-lmevtete-l''ûlâ. veveḳâhüm `aẕâbe-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'faḍlem mir rabbik. ẕâlike hüve-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'feinnemâ yessernâhü bilisânike le`allehüm yeteẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'ferteḳib innehüm mürteḳibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'tenzîlü-lkitâbi mine-llâhi-l`azîzi-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'inne fi-ssemâvâti vel''arḍi leâyâtil lilmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'vefî ḫalḳiküm vemâ yebüŝŝü min dâbbetin âyâtül liḳavmiy yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'vaḫtilâfi-lleyli vennehâri vemâ enzele-llâhü mine-ssemâi mir rizḳin feaḥyâ bihi-l''arḍa ba`de mevtihâ vetaṣrîfi-rriyâḥi âyâtül liḳavmiy ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'tilke âyâtü-llâhi netlûhâ `aleyke bilḥaḳḳ. febieyyi ḥadîŝim ba`de-llâhi veâyâtihî yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'veylül likülli effâkin eŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'yesme`u âyâti-llâhi tütlâ `aleyhi ŝümme yüṣirru müstekbiran keel lem yesma`hâ. febeşşirhü bi`aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'veiẕâ `alime min âyâtinâ şey''en-tteḫaẕehâ hüzüvâ. ülâike lehüm `aẕâbüm mühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'miv verâihim cehennem. velâ yugnî `anhüm mâ kesebû şey''ev velâ me-tteḫaẕû min dûni-llâhi evliyâ''. velehüm `aẕâbün `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'hâẕâ hüdâ. velleẕîne keferû biâyâti rabbihim lehüm `aẕâbüm mir riczin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'allâhü-lleẕî seḫḫara lekümü-lbaḥra litecriye-lfülkü fîhi biemrihî velitebtegû min faḍlihî vele`alleküm teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'veseḫḫara leküm mâ fi-ssemâvâti vemâ fi-l''arḍi cemî`am minh. inne fî ẕâlike leâyâtil liḳavmiy yetefekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'ḳul lilleẕîne âmenû yagfirû lilleẕîne lâ yercûne eyyâme-llâhi liyecziye ḳavmem bimâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'men `amile ṣâliḥan felinefsih. vemen esâe fe`aleyhâ. ŝümme ilâ rabbiküm türce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'veleḳad âteynâ benî isrâîle-lkitâbe velḥukme vennübüvvete verazaḳnâhüm mine-ṭṭayyibâti vefeḍḍalnâhüm `ale-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'veâteynâhüm beyyinâtim mine-l''emr. feme-ḫtelefû illâ mim ba`di mâ câehümü-l`ilmü bagyem beynehüm. inne rabbeke yaḳḍî beynehüm yevme-lḳiyâmeti fîmâ kânû fîhi yaḫtelifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'ŝümme ce`alnâke `alâ şerî`atim mine-l''emri fettebi`hâ velâ tettebi` ehvâe-lleẕîne lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'innehüm ley yugnû `anke mine-llâhi şey''â. veinne-żżâlimîne ba`ḍuhüm evliyâü ba`ḍ. vellâhü veliyyü-lmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'hâẕâ beṣâiru linnâsi vehüdev veraḥmetül liḳavmiy yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'em ḥasibe-lleẕîne-cteraḥü-sseyyiâti en nec`alehüm kelleẕîne âmenû ve`amilu-ṣṣâliḥâti sevâem maḥyâhüm vememâtühüm. sâe mâ yaḥkümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'veḫaleḳa-llâhü-ssemâvâti vel''arḍa bilḥaḳḳi velitüczâ küllü nefsim bimâ kesebet vehüm lâ yużlemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'eferaeyte meni-tteḫaẕe ilâhehû hevâhü veeḍallehü-llâhü `alâ `ilmiv veḫateme `alâ sem`ihî veḳalbihî vece`ale `alâ beṣarihî gişâveh. femey yehdîhi mim ba`di-llâh. efelâ teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'veḳâlû mâ hiye illâ ḥayâtüne-ddünyâ nemûtü venaḥyâ vemâ yühlikünâ ille-ddehr. vemâ lehüm biẕâlike min `ilmin. in hüm illâ yeżunnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'veiẕâ tütlâ `aleyhim âyâtünâ beyyinâtim mâ kâne ḥuccetehüm illâ en ḳâlü-''tû biâbâinâ in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'ḳuli-llâhü yuḥyîküm ŝümme yümîtüküm ŝümme yecme`uküm ilâ yevmi-lḳiyâmeti lâ raybe fîhi velâkinne ekŝera-nnâsi lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'velillâhi mülkü-ssemâvâti vel''arḍ. veyevme teḳûmü-ssâ`atü yevmeiẕiy yaḫseru-lmübṭilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'veterâ külle ümmetin câŝiyeh. küllü ümmetin tüd`â ilâ kitâbihâ. elyevme tüczevne mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'hâẕâ kitâbünâ yenṭiḳu `aleyküm bilḥaḳḳ. innâ künnâ nestensiḫu mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'feemme-lleẕîne âmenû ve`amilu-ṣṣâliḥâti feyüdḫilühüm rabbühüm fî raḥmetih. ẕâlike hüve-lfevzü-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'veemme-lleẕîne keferû. efelem tekün âyâtî tütlâ `aleyküm festekbertüm veküntüm ḳavmem mücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'veiẕâ ḳîle inne va`de-llâhi ḥaḳḳuv vessâ`atü lâ raybe fîhâ ḳultüm mâ nedrî me-ssâ`atü in neżunnü illâ żannâ vemâ naḥnü bimüsteyḳinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'vebedâ lehüm seyyietü mâ `amilû veḥâḳa bihim mâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'veḳîle-lyevme nensâküm kemâ nesîtüm liḳâe yevmiküm hâẕâ veme''vâküm-nnâru vemâ leküm min nâṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'ẕâliküm biennekümü-tteḫaẕtüm âyâti-llâhi hüzüvev vegarratkümü-lḥayâtü-ddünyâ. felyevme lâ yuḫracûne minhâ velâ hüm yüsta`tebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'felillâhi-lḥamdü rabbi-ssemâvâti verabbi-l''arḍi rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'velehü-lkibriyâü fi-ssemâvâti vel''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'ḥâ-mîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'tenzîlü-lkitâbi mine-llâhi-l`azîzi-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'mâ ḫalaḳne-ssemâvâti vel''arḍa vemâ beynehümâ illâ bilḥaḳḳi veecelim müsemmâ. velleẕîne keferû `ammâ ünẕirû mü`riḍûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'ḳul era''eytüm mâ ted`ûne min dûni-llâhi erûnî mâẕâ ḫaleḳû mine-l''arḍi em lehüm şirkün fi-ssemâvât. îtûnî bikitâbim min ḳabli hâẕâ ev eŝâratim min `ilmin in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'vemen eḍallü mimmey yed`û min dûni-llâhi mel lâ yestecîbü lehû ilâ yevmi-lḳiyâmeti vehüm `an dü`âihim gâfilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'veiẕâ ḥuşira-nnâsü kânû lehüm a`dâev vekânû bi`ibâdetihim kâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'veiẕâ tütlâ `aleyhim âyâtünâ beyyinâtin ḳâle-lleẕîne keferû lilḥaḳḳi lemmâ câehüm hâẕâ siḥrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'em yeḳûlûne-fterâh. ḳul ini-fteraytühû felâ temlikûne lî mine-llâhi şey''â. hüve a`lemü bimâ tüfîḍûne fîh. kefâ bihî şehîdem beynî vebeyneküm. vehüve-lgafûru-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'ḳul mâ küntü bid`am mine-rrusüli vemâ edrî mâ yüf`alü bî velâ biküm. in ettebi`u illâ mâ yûḥâ ileyye vemâ ene illâ neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'ḳul era''eytüm in kâne min `indi-llâhi vekefertüm bihî veşehide şâhidüm mim benî isrâîle `alâ miŝlihî feâmene vestekbertüm. inne-llâhe lâ yehdi-lḳavme-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'veḳâle-lleẕîne keferû lilleẕîne âmenû lev kâne ḫayram mâ sebeḳûnâ ileyh. veiẕ lem yehtedû bihî feseyeḳûlûne hâẕâ ifkün ḳadîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'vemin ḳablihî kitâbü mûsâ imâmev veraḥmeh. vehâẕâ kitâbüm müṣaddiḳul lisânen `arabiyyel liyünẕira-lleẕîne żalemû. vebüşrâ lilmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'inne-lleẕîne ḳâlû rabbüne-llâhü ŝümme-steḳâmû felâ ḫavfün `aleyhim velâ hüm yaḥzenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'ülâike aṣḥâbü-lcenneti ḫâlidîne fîhâ. cezâem bimâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'veveṣṣayne-l''insâne bivâlideyhi iḥsânâ. ḥamelethü ümmühû kürhev veveḍa`athü kürhâ. veḥamlühû vefiṣâlühû ŝelâŝûne şehrâ. ḥattâ iẕâ belega eşüddehû vebelega erbe`îne seneten ḳâle rabbi evzi`nî en eşküra ni`meteke-lletî en`amte `aleyye ve`alâ vâlideyye veen a`mele ṣâliḥan tarḍâhü veaṣliḥ lî fî ẕürriyyetî. innî tübtü ileyke veinnî mine-lmüslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'ülâike-lleẕîne neteḳabbelü `anhüm aḥsene mâ `amilû venetecâvezü `an seyyiâtihim fî aṣḥâbi-lcenneh. va`de-ṣṣidḳi-lleẕî kânû yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'velleẕî ḳâle livâlideyhi üffil lekümâ eta`idâninî en uḫrace veḳad ḫaleti-lḳurûnü min ḳablî vehümâ yestegîŝâni-llâhe veyleke âmin. inne va`de-llâhi ḥaḳḳun. feyeḳûlü mâ hâẕâ illâ esâṭîru-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'ülâike-lleẕîne ḥaḳḳa `aleyhimü-lḳavlü fî ümemin ḳad ḫalet min ḳablihim mine-lcinni vel''ins. innehüm kânû ḫâsirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'veliküllin deracâtüm mimmâ `amilû. veliyüveffiyehüm a`mâlehüm vehüm lâ yużlemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'veyevme yü`raḍu-lleẕîne keferû `ale-nnâr. eẕhebtüm ṭayyibâtiküm fî ḥayâtikümü-ddünyâ vestemta`tüm bihâ. felyevme tüczevne `aẕâbe-lhûni bimâ küntüm testekbirûne fi-l''arḍi bigayri-lḥaḳḳi vebimâ küntüm tefsüḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'veẕkür eḫâ `âdin. iẕ enẕera ḳavmehû bil''aḥḳâfi veḳad ḫaleti-nnüẕüru mim beyni yedeyhi vemin ḫalfihî ellâ ta`büdû ille-llâh. innî eḫâfü `aleyküm `aẕâbe yevmin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'ḳâlû eci''tenâ lite''fikenâ `an âlihetinâ. fe''tinâ bimâ te`idünâ in künte mine-ṣṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, 'ḳâle inneme-l`ilmü `inde-llâh. veübelliguküm mâ ürsiltü bihî velâkinnî erâküm ḳavmen techelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'felemmâ raevhü `âriḍam müstaḳbile evdiyetihim ḳâlû hâẕâ `âriḍum mümṭirunâ. bel hüve me-sta`celtüm bih. rîḥun fîhâ `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'tüdemmiru külle şey''im biemri rabbihâ feaṣbeḥû lâ yürâ illâ mesâkinühüm. keẕâlike neczi-lḳavme-lmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'veleḳad mekkennâhüm fîmâ im mekkennâküm fîhi vece`alnâ lehüm sem`av veebṣârav veef''ideh. femâ agnâ `anhüm sem`uhüm velâ ebṣâruhüm velâ ef''idetühüm min şey''in iẕ kânû yecḥadûne biâyâti-llâhi veḥâḳa bihim mâ kânû bihî yestehziûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'veleḳad ehleknâ mâ ḥavleküm mine-lḳurâ veṣarrafne-l''âyâti le`allehüm yerci`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'felevlâ neṣarahümü-lleẕîne-tteḫaẕû min dûni-llâhi ḳurbânen âliheh. bel ḍallû `anhüm. veẕâlike ifkühüm vemâ kânû yefterûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'veiẕ ṣarafnâ ileyke neferam mine-lcinni yestemi`ûne-lḳur''ân. felemmâ ḥaḍarûhü ḳâlû enṣitû. felemmâ ḳuḍiye vellev ilâ ḳavmihim münẕirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'ḳâlû yâ ḳavmenâ innâ semi`nâ kitâben ünzile mim ba`di mûsâ müṣaddiḳal limâ beyne yedeyhi yehdî ile-lḥaḳḳi veilâ ṭarîḳim müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'yâ ḳavmenâ ecîbû dâ`iye-llâhi veâminû bihî yagfir leküm min ẕünûbiküm veyücirküm min `aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'vemel lâ yücib dâ`iye-llâhi feleyse bimü`cizin fi-l''arḍi veleyse lehû min dûnihî evliyâ''. ülâike fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'evelem yerav enne-llâhe-lleẕî ḫaleḳa-ssemâvâti vel''arḍa velem ya`ye biḫalḳihinne biḳâdirin `alâ ey yuḥyiye-lmevtâ. belâ innehû `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'veyevme yü`raḍu-lleẕîne keferû `ale-nnâr. eleyse hâẕâ bilḥaḳḳ. ḳâlû belâ verabbinâ. ḳâle feẕûḳu-l`aẕâbe bimâ küntüm tekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'faṣbir kemâ ṣabera ülü-l`azmi mine-rrusüli velâ testa`cil lehüm. keennehüm yevme yeravne mâ yû`adûne lem yelbeŝû illâ sâ`atem min nehâr. belâg. fehel yühlekü ille-lḳavmü-lfâsiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'elleẕîne keferû veṣaddû `an sebîli-llâhi eḍalle a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'velleẕîne âmenû ve`amilu-ṣṣâliḥâti veâmenû bimâ nüzzile `alâ müḥammediv vehüve-lḥaḳḳu mir rabbihim keffera `anhüm seyyiâtihim veaṣleḥa bâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'ẕâlike bienne-lleẕîne keferü-ttebe`ü-lbâṭile veenne-lleẕîne âmenü-ttebe`ü-lḥaḳḳa mir rabbihim. keẕâlike yaḍribü-llâhü linnâsi emŝâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'feiẕâ leḳîtümü-lleẕîne keferû feḍarbe-rriḳâb. ḥattâ iẕâ eŝḫantümûhüm feşüddü-lveŝâḳa feimmâ mennem ba`dü veimmâ fidâen ḥattâ teḍa`a-lḥarbü evzârahâ. ẕâlik. velev yeşâü-llâhü lenteṣara minhüm velâkil liyeblüve ba`ḍaküm biba`ḍ. velleẕîne ḳutilû fî sebîli-llâhi feley yüḍille a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'seyehdîhim veyuṣliḥu bâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'veyüdḫilühümü-lcennete `arrafehâ lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'yâ eyyühe-lleẕîne âmenû in tenṣurü-llâhe yenṣurküm veyüŝebbit aḳdâmeküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'velleẕîne keferû feta`sel lehüm veeḍalle a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'ẕâlike biennehüm kerihû mâ enzele-llâhü feaḥbeṭa a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'efelem yesîrû fi-l''arḍi feyenżurû keyfe kâne `âḳibetü-lleẕîne min ḳablihim. demmera-llâhü `aleyhim. velilkâfirîne emŝâlühâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'ẕâlike bienne-llâhe mevle-lleẕîne âmenû veenne-lkâfirîne lâ mevlâ lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'inne-llâhe yüdḫilü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti cennâtin tecrî min taḥtihe-l''enhâr. velleẕîne keferû yetemette`ûne veye''külûne kemâ te''külü-l''en`âmü vennâru meŝvel lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'vekeeyyim min ḳaryetin hiye eşeddü ḳuvvetem min ḳaryetike-lletî aḫracetk. ehleknâhüm felâ nâṣira lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'efemen kâne `alâ beyyinetim mir rabbihî kemen züyyine lehû sûü `amelihî vettebe`û ehvâehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'meŝelü-lcenneti-lletî vu`ide-lmütteḳûn. fîhâ enhârum mim mâin gayri âsin. veenhârum mil lebenil lem yetegayyer ṭa`müh. veenhârum min ḫamril leẕẕetil lişşâribîn. veenhârum min `aselim müṣaffâ. velehüm fîhâ min külli-ŝŝemerâti vemagfiratüm mir rabbihim. kemen hüve ḫâlidün fi-nnâri vesüḳû mâen ḥamîmen feḳaṭṭa`a em`âehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'veminhüm mey yestemi`u ileyk. ḥattâ iẕâ ḫaracû min `indike ḳâlû lilleẕîne ûtü-l`ilme mâẕâ ḳâle ânifâ. ülâike-lleẕîne ṭabe`a-llâhü `alâ ḳulûbihim vettebe`û ehvâehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'velleẕîne-htedev zâdehüm hüdev veâtâhüm taḳvâhüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'fehel yenżurûne ille-ssâ`ate en te''tiyehüm bagteten. feḳad câe eşrâṭuhâ. feennâ lehüm iẕâ câethüm ẕikrâhüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'fa`lem ennehû lâ ilâhe ille-llâhü vestagfir liẕembike velilmü''minîne velmü''minât. vellâhü ya`lemü müteḳallebeküm vemeŝvâküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'veyeḳûlü-lleẕîne âmenû levlâ nüzzilet sûratün. feiẕâ ünzilet sûratüm muḥkemetüv veẕükira fîhe-lḳitâlü raeyte-lleẕîne fî ḳulûbihim meraḍuy yenżurûne ileyke neżara-lmagşiyyi `aleyhi mine-lmevt. feevlâ lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'ṭâ`atüv veḳavlüm ma`rûfün. feiẕâ `azeme-l''emr. felev ṣadeḳu-llâhe lekâne ḫayral lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'fehel `aseytüm in tevelleytüm en tüfsidû fi-l''arḍi vetüḳaṭṭi`û erḥâmeküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'ülâike-lleẕîne le`anehümü-llâhü feeṣammehüm vea`mâ ebṣârahüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'efelâ yetedebberûne-lḳur''âne em `alâ ḳulûbin aḳfâlühâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'inne-lleẕîne-rteddû `alâ edbârihim mim ba`di mâ tebeyyene lehümü-lhüde-şşeyṭânü sevvele lehüm. veemlâ lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'ẕâlike biennehüm ḳâlû lilleẕîne kerihû mâ nezzele-llâhü senüṭî`uküm fî ba`ḍi-l''emr. vellâhü ya`lemü isrârahüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'fekeyfe iẕâ teveffethümü-lmelâiketü yaḍribûne vucûhehüm veedbârahüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'ẕâlike biennehümü-ttebe`û mâ esḫaṭa-llâhe vekerihû riḍvânehû feaḥbeṭa a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'em ḥasibe-lleẕîne fî ḳulûbihim meraḍun el ley yuḫrice-llâhü aḍgânehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'velev neşâü leeraynâkehüm fele`araftehüm bisîmâhüm. veleta`rifennehüm fî laḥni-lḳavl. vellâhü ya`lemü a`mâleküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'veleneblüvenneküm ḥattâ na`leme-lmücâhidîne minküm veṣṣâbirîne veneblüve aḫbâraküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'inne-lleẕîne keferû veṣaddû `an sebîli-llâhi veşâḳḳu-rrasûle mim ba`di mâ tebeyyene lehümü-lhüdâ ley yeḍurrü-llâhe şey''â. veseyuḥbiṭu a`mâlehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'yâ eyyühe-lleẕîne âmenû eṭî`ü-llâhe veeṭî`ü-rrasûle velâ tübṭilû a`mâleküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'inne-lleẕîne keferû veṣaddû `an sebîli-llâhi ŝümme mâtû vehüm küffârun feley yagfira-llâhü lehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'felâ tehinû veted`û ile-sselm. veentümü-l''a`levn. vellâhü me`aküm veley yetiraküm a`mâleküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'inneme-lḥayâtü-ddünyâ le`ibüv velehv. vein tü''minû vetetteḳû yü''tiküm ücûraküm velâ yes''elküm emvâleküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'iy yes''elkümûhâ feyuḥfiküm tebḫalû veyuḫric aḍgâneküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'hâentüm hâülâi tüd`avne litünfiḳû fî sebîli-llâh. feminküm mey yebḫal. vemey yebḫal feinnemâ yebḫalü `an nefsih. vellâhü-lganiyyü veentümü-lfüḳarâ''. vein tetevellev yestebdil ḳavmen gayraküm ŝümme lâ yekûnû emŝâleküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'innâ fetaḥnâ leke fetḥam mübînâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'liyagfira leke-llâhü mâ teḳaddeme min ẕembike vemâ teeḫḫara veyütimme ni`metehû `aleyke veyehdiyeke ṣirâṭam müsteḳîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'veyenṣurake-llâhü naṣran `azîzâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'hüve-lleẕî enzele-ssekînete fî ḳulûbi-lmü''minîne liyezdâdû îmânem me`a îmânihim. velillâhi cünûdü-ssemâvâti vel''arḍ. vekâne-llâhü `alîmen ḥakîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'liyüdḫile-lmü''minîne velmü''minâti cennâtin tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ veyükeffira `anhüm seyyiâtihim. vekâne ẕâlike `inde-llâhi fevzen `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'veyü`aẕẕibe-lmünâfiḳîne velmünâfiḳâti velmüşrikîne velmüşrikâti-żżânnîne billâhi żanne-ssev''. `aleyhim dâiratü-ssev''. vegaḍibe-llâhü `aleyhim vele`anehüm vee`adde lehüm cehennem. vesâet meṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'velillâhi cünûdü-ssemâvâti vel''arḍ. vekâne-llâhü `azîzen ḥakîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'innâ erselnâke şâhidev vemübeşşirav veneẕîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'litü''minû billâhi verasûlihî vetü`azzirûhü vetüveḳḳirûh. vetüsebbiḥûhü bükratev veeṣîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'inne-lleẕîne yübâyi`ûneke innemâ yübâyi`ûne-llâh. yedü-llâhi fevḳa eydîhim. femen nekeŝe feinnemâ yenküŝü `alâ nefsih. vemen evfâ bimâ `âhede `aleyhü-llâhe feseyü''tîhi ecran `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'seyeḳûlü leke-lmüḫallefûne mine-l''a`râbi şegaletnâ emvâlünâ veehlûnâ festagfir lenâ. yeḳûlûne bielsinetihim mâ leyse fî ḳulûbihim. ḳul femey yemlikü leküm mine-llâhi şey''en in erâde biküm ḍarran ev erâde biküm nef`â. bel kâne-llâhü bimâ ta`melûne ḫabîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'bel żanentüm el ley yenḳalibe-rrasûlü velmü''minûne ilâ ehlîhim ebedev vezüyyine ẕâlike fî ḳulûbiküm veżanentüm żanne-ssev''. veküntüm ḳavmem bûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'vemel lem yü''mim billâhi verasûlihî feinnâ a`tednâ lilkâfirîne se`îrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'velillâhi mülkü-ssemâvâti vel''arḍ. yagfiru limey yeşâü veyü`aẕẕibü mey yeşâ''. vekâne-llâhü gafûrar raḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'seyeḳûlü-lmüḫallefûne iẕe-nṭalaḳtüm ilâ megânime lite''ḫuẕûhâ ẕerûnâ nettebi`küm. yürîdûne ey yübeddilû kelâme-llâh. ḳul len tettebi`ûnâ keẕâliküm ḳâle-llâhü min ḳabl. feseyeḳûlûne bel taḥsüdûnenâ. bel kânû lâ yefḳahûne illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'ḳul lilmüḫallefîne mine-l''a`râbi setüd`avne ilâ ḳavmin ülî be''sin şedîdin tüḳâtilûnehüm ev yüslimûn. fein tüṭî`û yü''tikümü-llâhü ecran ḥasenâ. vein tetevellev kemâ tevelleytüm min ḳablü yü`aẕẕibküm `aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'leyse `ale-l''a`mâ ḥaracüv velâ `ale-l''a`raci ḥaracüv velâ `ale-lmerîḍi ḥarac. vemey yüṭi`i-llâhe verasûlehû yüdḫilhü cennâtin tecrî min taḥtihe-l''enhâr. vemey yetevelle yü`aẕẕibhü `aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'leḳad raḍiye-llâhü `ani-lmü''minîne iẕ yübâyi`ûneke taḥte-şşecerati fe`alime mâ fî ḳulûbihim feenzele-ssekînete `aleyhim veeŝâbehüm fetḥan ḳarîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'vemegânime keŝîratey ye''ḫuẕûnehâ. vekâne-llâhü `azîzen ḥakîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 've`adekümü-llâhü megânime keŝîraten te''ḫuẕûnehâ fe`accele leküm hâẕihî vekeffe eydiye-nnâsi `anküm. velitekûne âyetel lilmü''minîne veyehdiyeküm ṣirâṭam müsteḳîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'veuḫrâ lem taḳdirû `aleyhâ ḳad eḥâṭa-llâhü bihâ. vekâne-llâhü `alâ külli şey''in ḳadîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'velev ḳâtelekümü-lleẕîne keferû levellevu-l''edbâra ŝümme lâ yecidûne veliyyev velâ neṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'sünnete-llâhi-lletî ḳad ḫalet min ḳabl. velen tecide lisünneti-llâhi tebdîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'vehüve-lleẕî keffe eydiyehüm `anküm veeydiyeküm `anhüm bibaṭni mekkete mim ba`di en ażferaküm `aleyhim. vekâne-llâhü bimâ ta`melûne beṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'hümü-lleẕîne keferû veṣaddûküm `ani-lmescidi-lḥarâmi velhedye ma`kûfen ey yeblüga meḥilleh. velevlâ ricâlüm mü''minûne venisâüm mü''minâtül lem ta`lemûhüm en teṭaûhüm fetüṣîbeküm minhüm me`arratüm bigayri `ilmin. liyüdḫile-llâhü fî raḥmetihî mey yeşâ''. lev tezeyyelû le`aẕẕebne-lleẕîne keferû minhüm `aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'iẕ ce`ale-lleẕîne keferû fî ḳulûbihimü-lḥamiyyete ḥamiyyete-lcâhiliyyeti feenzele-llâhü sekînetehû `alâ rasûlihî ve`ale-lmü''minîne veelzemehüm kelimete-ttaḳvâ vekânû eḥaḳḳa bihâ veehlehâ. vekâne-llâhü bikülli şey''in `alîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'leḳad ṣadeḳa-llâhü rasûlehü-rru''yâ bilḥaḳḳ. letedḫulünne-lmescide-lḥarâme in şâe-llâhü âminîne müḥalliḳîne ruûseküm vemüḳaṣṣirîne lâ teḫâfûn. fe`alime mâ lem ta`lemû fece`ale min dûni ẕâlike fetḥan ḳarîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'hüve-lleẕî ersele rasûlehû bilhüdâ vedîni-lḥaḳḳi liyużhirahû `ale-ddîni küllih. vekefâ billâhi şehîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'müḥammedür rasûlü-llâh. velleẕîne me`ahû eşiddâü `ale-lküffâri ruḥamâü beynehüm terâhüm rukke`an süccedey yebtegûne faḍlem mine-llâhi veriḍvânâ. sîmâhüm fî vucûhihim min eŝeri-ssücûd. ẕâlike meŝelühüm fi-ttevrâh. vemeŝelühüm fi-l''incîl. kezer`in aḫrace şaṭ''ehû feâzerahû festagleża festevâ `alâ sûḳihî yü`cibü-zzürrâ`a liyegîża bihimü-lküffâr. ve`ade-llâhü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti minhüm magfiratev veecran `ażîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'yâ eyyühe-lleẕîne âmenû lâ tüḳaddimû beyne yedeyi-llâhi verasûlihî vetteḳu-llâh. inne-llâhe semî`un `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'yâ eyyühe-lleẕîne âmenû lâ terfe`û aṣvâteküm fevḳa ṣavti-nnebiyyi velâ techerû lehû bilḳavli kecehri ba`ḍiküm liba`ḍin en taḥbeṭa a`mâlüküm veentüm lâ teş`urûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'inne-lleẕîne yeguḍḍûne aṣvâtehüm `inde rasûli-llâhi ülâike-lleẕîne-mteḥane-llâhü ḳulûbehüm littaḳvâ. lehüm magfiratüv veecrun `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'inne-lleẕîne yünâdûneke miv verâi-lḥucürâti ekŝeruhüm lâ ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'velev ennehüm ṣaberû ḥattâ taḫruce ileyhim lekâne ḫayral lehüm. vellâhü gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'yâ eyyühe-lleẕîne âmenû in câeküm fâsiḳum binebein fetebeyyenû en tüṣîbû ḳavmem bicehâletin fetuṣbiḥû `alâ mâ fe`altüm nâdimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'va`lemû enne fîküm rasûle-llâh. lev yüṭî`uküm fî keŝîrim mine-l''emri le`anittüm velâkinne-llâhe ḥabbebe ileykümü-l''îmâne vezeyyenehû fî ḳulûbiküm vekerrahe ileykümü-lküfra velfüsûḳa vel`iṣyân. ülâike hümü-rrâşidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'faḍlem mine-llâhi veni`meh. vellâhü `alîmün ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'vein ṭâifetâni mine-lmü''minîne-ḳtetelû feaṣliḥû beynehümâ. feim begat iḥdâhümâ `ale-l''uḫrâ feḳâtilü-lletî tebgî ḥattâ tefîe ilâ emri-llâh. fein fâet feaṣliḥû beynehümâ bil`adli veaḳsiṭû. inne-llâhe yüḥibbü-lmuḳsiṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'inneme-lmü''minûne iḫvetün feaṣliḥû beyne eḫaveyküm vetteḳu-llâhe le`alleküm türḥamûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'yâ eyyühe-lleẕîne âmenû lâ yesḫar ḳavmüm min ḳavmin `asâ ey yekûnû ḫayram minhüm velâ nisâüm min nisâin `asâ ey yekünne ḫayram minhünn. velâ telmizû enfüseküm velâ tenâbezû bil''elḳâb. bi''se-lismü-lfüsûḳu ba`de-l''îmân. vemel lem yetüb feülâike hümu-żżâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'yâ eyyühe-lleẕîne âmenü-ctenibû keŝîram mine-żżann. inne ba`ḍa-żżanni iŝmüv velâ tecessesû velâ yagteb ba`ḍuküm ba`ḍâ. eyüḥibbü eḥadüküm ey ye''küle laḥme eḫîhi meyten fekerihtümûh. vetteḳu-llâh. inne-llâhe tevvâbür raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'yâ eyyühe-nnâsü innâ ḫalaḳnâküm min ẕekeriv veünŝâ vece`alnâküm şu`ûbev veḳabâile lite`ârafû. inne ekrameküm `inde-llâhi etḳâküm. inne-llâhe `alîmün ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'ḳâleti-l''a`râbü âmennâ. ḳul lem tü''minû velâkin ḳûlû eslemnâ velemmâ yedḫuli-l''îmânü fî ḳulûbiküm. vein tüṭî`ü-llâhe verasûlehû lâ yelitküm min a`mâliküm şey''â. inne-llâhe gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'inneme-lmü''minûne-lleẕîne âmenû billâhi verasûlihî ŝümme lem yertâbû vecâhedû biemvâlihim veenfüsihim fî sebîli-llâh. ülâike hümu-ṣṣâdiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'ḳul etü`allimûne-llâhe bidîniküm vellâhü ya`lemü mâ fi-ssemâvâti vemâ fi-l''arḍ. vellâhü bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'yemünnûne `aleyke en eslemû. ḳul lâ temünnû `aleyye islâmeküm. beli-llâhü yemünnü `aleyküm en hedâküm lil''îmâni in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'inne-llâhe ya`lemü gaybe-ssemâvâti vel''arḍ. vellâhü beṣîrum bimâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'ḳâf. velḳur''âni-lmecîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'bel `acibû en câehüm münẕirum minhüm feḳâle-lkâfirûne hâẕâ şey''ün `acîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'eiẕâ mitnâ vekünnâ türâbâ. ẕâlike rac`um be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'ḳad `alimnâ mâ tenḳuṣu-l''arḍu minhüm. ve`indenâ kitâbün ḥafîż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'bel keẕẕebû bilḥaḳḳi lemmâ câehüm fehüm fî emrim merîc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'efelem yenżurû ile-ssemâi fevḳahüm keyfe beneynâhâ vezeyyennâhâ vemâ lehâ min fürûc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'vel''arḍa medednâhâ veelḳaynâ fîhâ ravâsiye veembetnâ fîhâ min külli zevcim behîc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'tebṣiratev veẕikrâ likülli `abdim münîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'venezzelnâ mine-ssemâi mâem mübâraken feembetnâ bihî cennâtiv veḥabbe-lḥaṣîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'vennaḫle bâsiḳâtil lehâ ṭal`un neḍîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'rizḳal lil`ibâdi veaḥyeynâ bihî beldetem meytâ. keẕâlike-lḫurûc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'keẕẕebet ḳablehüm ḳavmü nûḥiv veaṣḥâbü-rrassi veŝemûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 've`âdüv vefir`avnü veiḫvânü lûṭ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'veaṣḥâbü-l''eyketi veḳavmü tübba`. küllün keẕẕebe-rrusüle feḥaḳḳa ve`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'efe`ayînâ bilḫalḳi-l''evvel. bel hüm fî lebsim min ḫalḳin cedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'veleḳad ḫalaḳne-l''insâne vena`lemü mâ tüvesvisü bihî nefsüh. venaḥnü aḳrabü ileyhi min ḥabli-lverîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'iẕ yeteleḳḳe-lmüteleḳḳiyâni `ani-lyemîni ve`ani-şşimâli ḳa`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'mâ yelfiżu min ḳavlin illâ ledeyhi raḳîbün `atîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'vecâet sekratü-lmevt bilḥaḳḳ. ẕâlike mâ künte minhü teḥîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'venüfiḫa fi-ṣṣûr. ẕâlike yevmü-lve`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'vecâet küllü nefsim me`ahâ sâiḳuv veşehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, 'leḳad künte fî gafletim min hâẕâ fekeşefnâ `anke giṭâeke febeṣaruke-lyevme ḥadîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'veḳâle ḳarînühû hâẕâ mâ ledeyye `atîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'elḳiyâ fî cehenneme külle keffârin `anîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'mennâ`il lilḫayri mü`tedim mürîbün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'elleẕî ce`ale me`a-llâhi ilâhen âḫara feelḳiyâhü fi-l`aẕâbi-şşedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'ḳâle ḳarînühû rabbenâ mâ aṭgaytühû velâkin kâne fî ḍalâlim be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, 'ḳâle lâ taḫteṣimû ledeyye veḳad ḳaddemtü ileyküm bilve`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'mâ yübeddelü-lḳavlü ledeyye vemâ ene biżallâmil lil`abîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'yevme neḳûlü licehenneme heli-mtele''ti veteḳûlü hel mim mezîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'veüzlifeti-lcennetü lilmütteḳîne gayra be`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, 'hâẕâ mâ tû`adûne likülli evvâbin ḥafîż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'men ḫaşiye-rraḥmâne bilgaybi vecâe biḳalbim münîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'üdḫulûhâ biselâm. ẕâlike yevmü-lḫulûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'lehüm mâ yeşâûne fîhâ veledeynâ mezîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'vekem ehleknâ ḳablehüm min ḳarnin hüm eşeddü minhüm baṭşen feneḳḳabû fi-lbilâd. hel mim meḥîṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'inne fî ẕâlike leẕikrâ limen kâne lehû ḳalbün ev elḳa-ssem`a vehüve şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'veleḳad ḫalaḳne-ssemâvâti vel''arḍa vemâ beynehümâ fî sitteti eyyâm. vemâ messenâ mil lügûb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'faṣbir `alâ mâ yeḳûlûne vesebbiḥ biḥamdi rabbike ḳable ṭulû`i-şşemsi veḳable-lgurûb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'vemine-lleyli fesebbiḥhü veedbâra-ssücûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'vestemi` yevme yünâdi-lmünâdi mim mekânin ḳarîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'yevme yesme`ûne-ṣṣayḥate bilḥaḳḳ. ẕâlike yevmü-lḫurûc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'innâ naḥnü nuḥyî venümîtü veileyne-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'yevme teşeḳḳaḳu-l''arḍu `anhüm sirâ`â. ẕâlike ḥaşrun `aleynâ yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'naḥnü a`lemü bimâ yeḳûlûne vemâ ente `aleyhim bicebbârin feẕekkir bilḳur''âni mey yeḫâfü ve`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'veẕẕâriyâti ẕervâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'felḥâmilâti viḳrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'felcâriyâti yüsrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'felmüḳassimâti emrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'innemâ tû`adûne leṣâdiḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'veinne-ddîne levâḳi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'vessemâi ẕâti-lḥubük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'inneküm lefî ḳavlim muḫtelif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'yü''fekü `anhü men üfik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'ḳutile-lḫarrâṣûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'elleẕîne hüm fî gamratin sâhûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'yes''elûne eyyâne yevmü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'yevme hüm `ale-nnâri yüftenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, 'ẕûḳû fitneteküm. hâẕe-lleẕî küntüm bihî testa`cilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'inne-lmütteḳîne fî cennâtiv ve`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'âḫiẕîne mâ âtâhüm rabbühüm. innehüm kânû ḳable ẕâlike muḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'kânû ḳalîlem mine-lleyli mâ yehce`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'vebil''esḥâri hüm yestagfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'vefî emvâlihim ḥaḳḳul lissâili velmaḥrûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'vefi-l''arḍi âyâtül lilmûḳinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'vefî enfüsiküm. efelâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'vefi-ssemâi rizḳuküm vemâ tû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'feverabbi-ssemâi vel''arḍi innehû leḥaḳḳum miŝle mâ enneküm tenṭiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'hel etâke ḥadîŝü ḍayfi ibrâhîme-lmükramîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'iẕ deḫalû `aleyhi feḳâlû selâmâ. ḳâle selâm. ḳavmüm münkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'ferâga ilâ ehlihî fecâe bi`iclin semîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'feḳarrabehû ileyhim ḳâle elâ te''külûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'feevcese minhüm ḫîfeh. ḳâlû lâ teḫaf. vebeşşerûhü bigulâmin `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'feaḳbeleti-mraetühû fî ṣarratin feṣakket vechehâ veḳâlet `acûzün `aḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, 'ḳâlû keẕâliki ḳâle rabbük. innehû hüve-lḥakîmü-l`alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, 'ḳâle femâ ḫaṭbüküm eyyühe-lmürselûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, 'ḳâlû innâ ürsilnâ ilâ ḳavmim mücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'linürsile `aleyhim ḥicâratem min ṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'müsevvemeten `inde rabbike lilmüsrifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'feaḫracnâ men kâne fîhâ mine-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'femâ vecednâ fîhâ gayra beytim mine-lmüslimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'veteraknâ fîhâ âyetel lilleẕîne yeḫâfûne-l`aẕâbe-l''elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, 'vefî mûsâ iẕ erselnâhü ilâ fir`avne bisülṭânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'fetevellâ biruknihî veḳâle sâḥirun ev mecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'feeḫaẕnâhü vecünûdehû fenebeẕnâhüm fi-lyemmi vehüve mülîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, 'vefî `âdin iẕ erselnâ `aleyhimü-rrîḥa-l`aḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'mâ teẕeru min şey''in etet `aleyhi illâ ce`alethü kelramîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'vefî ŝemûde iẕ ḳîle lehüm temette`û ḥattâ ḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'fe`atev `an emri rabbihim feeḫaẕethümu-ṣṣâ`iḳatü vehüm yenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'feme-steṭâ`û min ḳiyâmiv vemâ kânû münteṣirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'veḳavme nûḥim min ḳabl. innehüm kânû ḳavmen fâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'vessemâe beneynâhâ bieydiv veinnâ lemûsi`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'vel''arḍa feraşnâhâ feni`me-lmâhidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'vemin külli şey''in ḫalaḳnâ zevceyni le`alleküm teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'fefirrû ile-llâh. innî leküm minhü neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'velâ tec`alû me`a-llâhi ilâhen âḫar. innî leküm minhü neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'keẕâlike mâ ete-lleẕîne min ḳablihim mir rasûlin illâ ḳâlû sâḥirun ev mecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'etevâṣav bih. bel hüm ḳavmün ṭâgûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'fetevelle `anhüm femâ ente bimelûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'veẕekkir feinne-ẕẕikrâ tenfe`u-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'vemâ ḫalaḳtü-lcinne vel''inse illâ liya`büdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'mâ ürîdü minhüm mir rizḳiv vemâ ürîdü ey yuṭ`imûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'inne-llâhe hüve-rrazzâḳu ẕü-lḳuvveti-lmetîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'feinne lilleẕîne żalemû ẕenûbem miŝle ẕenûbi aṣḥâbihim felâ yesta`cilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'feveylül lilleẕîne keferû miy yevmihimü-lleẕî yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'veṭṭûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'vekitâbim mesṭûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'fî raḳḳim menşûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'velbeyti-lma`mûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'vessaḳfi-lmerfû`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'velbaḥri-lmescûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'inne `aẕâbe rabbike levâḳi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'mâ lehû min dâfi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'yevme temûru-ssemâü mevrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'vetesîru-lcibâlü seyrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'feveylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'elleẕîne hüm fî ḫavḍiy yel`abûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'yevme yüde``ûne ilâ nâri cehenneme da``â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, 'hâẕihi-nnâru-lletî küntüm bihâ tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'efesiḥrun hâẕâ em entüm lâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'iṣlevhâ faṣbirû ev lâ taṣbirû. sevâün `aleyküm. innemâ tüczevne mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'inne-lmütteḳîne fî cennâtiv vene`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'fâkihîne bimâ âtâhüm rabbühüm. veveḳâhüm rabbühüm `aẕâbe-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, 'külû veşrabû henîem bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'müttekiîne `alâ sürurim maṣfûfeh. vezevvecnâhüm biḥûrin `în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'velleẕîne âmenû vettebe`athüm ẕürriyyetühüm biîmânin elḥaḳnâ bihim ẕürriyyetehüm vemâ eletnâhüm min `amelihim min şey''. küllü-mriim bimâ kesebe rahîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'veemdednâhüm bifâkihetiv velaḥmim mimmâ yeştehûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'yetenâza`ûne fîhâ ke''sel lâ lagvun fîhâ velâ te''ŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'veyeṭûfü `aleyhim gilmânül lehüm keennehüm lü''lüüm meknûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'veaḳbele ba`ḍuhüm `alâ ba`ḍiy yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'ḳâlû innâ künnâ ḳablü fî ehlinâ müşfiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'femenne-llâhü `aleynâ veveḳânâ `aẕâbe-ssemûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'innâ künnâ min ḳablü ned`ûh. innehû hüve-lberru-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'feẕekkir femâ ente bini`meti rabbike bikâhiniv velâ mecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'em yeḳûlûne şâ`irun neterabbeṣu bihî raybe-lmenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, 'ḳul terabbeṣû feinnî me`aküm mine-lmüterabbiṣîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'em te''müruhüm aḥlâmühüm bihâẕâ em hüm ḳavmün ṭâgûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'em yeḳûlûne teḳavveleh. bel lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'felye''tû biḥadîŝim miŝlihî in kânû ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'em ḫuliḳû min gayri şey''in em hümü-lḫâliḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'em ḫaleḳu-ssemâvâti vel''arḍ. bel lâ yûḳinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'em `indehüm ḫazâinü rabbike em hümü-lmüṣayṭirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'em lehüm süllemüy yestemi`ûne fîh. felye''ti müstemi`uhüm bisülṭânim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'em lehü-lbenâtü velekümü-lbenûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'em tes''elühüm ecran fehüm mim magramim müŝḳalûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'em `indehümü-lgaybü fehüm yektübûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'em yürîdûne keydâ. felleẕîne keferû hümü-lmekîdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'em lehüm ilâhün gayru-llâh. sübḥâne-llâhi `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'veiy yerav kisfem mine-ssemâi sâḳiṭay yeḳûlû seḥâbüm merkûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'feẕerhüm ḥattâ yülâḳû yevmehümü-lleẕî fîhi yuṣ`aḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'yevme lâ yugnî `anhüm keydühüm şey''ev velâ hüm yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'veinne lilleẕîne żalemû `aẕâben dûne ẕâlike velâkinne ekŝerahüm lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'vaṣbir liḥukmi rabbike feinneke bia`yüninâ vesebbiḥ biḥamdi rabbike ḥîne teḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'vemine-lleyli fesebbiḥhü veidbâra-nnücûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'vennecmi iẕâ hevâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'mâ ḍalle ṣâḥibüküm vemâ gavâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'vemâ yenṭiḳu `ani-lhevâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'in hüve illâ vaḥyüy yûḥâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, '`allemehû şedîdü-lḳuvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'ẕû mirrah. festevâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'vehüve bil''üfüḳi-l''a`lâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'ŝümme denâ fetedellâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'fekâne ḳâbe ḳavseyni ev ednâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'feevḥâ ilâ `abdihî mâ evḥâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'mâ keẕebe-lfüâdü mâ raâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'efetümârûnehû `alâ mâ yerâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'veleḳad raâhü nezleten uḫrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, '`inde sidrati-lmüntehâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, '`indehâ cennetü-lme''vâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'iẕ yagşe-ssidrate mâ yagşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'mâ zâga-lbeṣaru vemâ ṭagâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'leḳad raâ min âyâti rabbihi-lkübrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'eferaeytümü-llâte vel`uzzâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'vemenâte-ŝŝâliŝete-l''uḫrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'elekümü-ẕẕekeru velehü-l''ünŝâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'tilke iẕen ḳismetün ḍîzâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'in hiye illâ esmâün semmeytümûhâ entüm veâbâüküm mâ enzele-llâhü bihâ min sülṭân. iy yettebi`ûne ille-żżanne vemâ tehve-l''enfüs. veleḳad câehüm mir rabbihimü-lhüdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'em lil''insâni mâ temennâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'felillâhi-l''âḫiratü vel''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'vekem mim melekin fi-ssemâvâti lâ tugnî şefâ`atühüm şey''en illâ mim ba`di ey ye''ẕene-llâhü limey yeşâü veyerḍâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'inne-lleẕîne lâ yü''minûne bil''âḫirati leyüsemmûne-lmelâikete tesmiyete-l''ünŝâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'vemâ lehüm bihî min `ilm. iy yettebi`ûne ille-żżanne. veinne-żżanne lâ yugnî mine-lḥaḳḳi şey''â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'fea`riḍ `am men tevellâ `an ẕikrinâ velem yürid ille-lḥayâte-ddünyâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'ẕâlike mebleguhüm mine-l`ilm. inne rabbeke hüve a`lemü bimen ḍalle `an sebîlihî vehüve a`lemü bimeni-htedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'velillâhi mâ fi-ssemâvâti vemâ fi-l''arḍi liyecziye-lleẕîne esâü bimâ `amilû veyecziye-lleẕîne aḥsenû bilḥusnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'elleẕîne yectenibûne kebâira-l''iŝmi velfevâḥişe ille-llemem. inne rabbeke vâsi`u-lmagfirah. hüve a`lemü biküm iẕ enşeeküm mine-l''arḍi veiẕ entüm ecinnetün fî büṭûni ümmehâtiküm. felâ tüzekkû enfüseküm. hüve a`lemü bimeni-tteḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'eferaeyte-lleẕî tevellâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'vea`ṭâ ḳalîlev veekdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'e`indehû `ilmü-lgaybi fehüve yerâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'em lem yünebbe'' bimâ fî ṣuḥufi mûsâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'veibrâhime-lleẕî veffâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'ellâ teziru vâziratüv vizra uḫrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'veel leyse lil''insâni illâ mâ se`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'veenne sa`yehû sevfe yürâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'ŝümme yüczâhü-lcezâe-l''evfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'veenne ilâ rabbike-lmüntehâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'veennehû hüve aḍḥake veebkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'veennehû hüve emâte veaḥyâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'veennehû ḫaleḳa-zzevceyni-ẕẕekera vel''ünŝâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'min nuṭfetin iẕâ tümnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'veenne `aleyhi-nneş''ete-l''uḫrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'veennehû hüve agnâ veaḳnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'veennehû hüve rabbü-şşi`râ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'veennehû ehleke `âden-l''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'veŝemûde femâ ebḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'veḳavme nûḥim min ḳabl. innehüm kânû hüm ażleme veaṭgâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'velmü''tefikete ehvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'fegaşşâhâ mâ gaşşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'febieyyi âlâi rabbike tetemârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'hâẕâ neẕîrum mine-nnüẕüri-l''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'ezifeti-l''âzifeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'leyse lehâ min dûni-llâhi kâşifeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'efemin hâẕe-lḥadîŝi ta`cebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'vetaḍḥakûne velâ tebkûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'veentüm sâmidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'fescüdû lillâhi va`büdû.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'iḳterabeti-ssâ`atü venşeḳḳa-lḳamer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'veiy yerav âyetey yü`riḍû veyeḳûlû siḥrum müstemirr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'vekeẕẕebû vettebe`û ehvâehüm veküllü emrim müsteḳirr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'veleḳad câehüm mine-l''embâi mâ fîhi müzdecer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, 'ḥikmetüm bâligatün femâ tugni-nnüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'fetevelle `anhüm. yevme yed`u-ddâ`i ilâ şey''in nükür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 'ḫuşşe`an ebṣâruhüm yaḫrucûne mine-l''ecdâŝi keennehüm cerâdüm münteşir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'mühti`îne ile-ddâ`. yeḳûlü-lkâfirûne hâẕâ yevmün `asir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'keẕẕebet ḳablehüm ḳavmü nûḥin fekeẕẕebû `abdenâ veḳâlû mecnûnüv vezdücira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'fede`â rabbehû ennî maglûbün fenteṣir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'fefetaḥnâ ebvâbe-ssemâi bimâim münhemir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'vefeccerne-l''arḍa `uyûnen felteḳe-lmâü `alâ emrin ḳad ḳudir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'veḥamelnâhü `alâ ẕâti elvâḥiv vedüsür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'tecrî bia`yüninâ. cezâel limen kâne küfira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'veleḳat teraknâhâ âyeten fehel mim müddekir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'fekeyfe kâne `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'veleḳad yesserne-lḳur''âne liẕẕikri fehel mim müddekir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'keẕẕebet `âdün fekeyfe kâne `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'innâ erselnâ `aleyhim rîḥan ṣarṣaran fî yevmi naḥsim müstemirr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'tenzi`u-nnâse keennehüm a`câzü naḫlim münḳa`ir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'fekeyfe kâne `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'veleḳad yesserne-lḳur''âne liẕẕikri fehel mim müddekir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'keẕẕebet ŝemûdü binnüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'feḳâlû ebeşeram minnâ vâḥiden nettebi`uhû innâ iẕel lefî ḍalâliv vesü`ur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'eülḳiye-ẕẕikru `aleyhi mim beyninâ bel hüve keẕẕâbün eşir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'seya`lemûne gadem meni-lkeẕẕâbü-l''eşir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'innâ mürsilü-nnâḳati fitnetel lehüm ferteḳibhüm vaṣṭabir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'venebbi''hüm enne-lmâe ḳismetüm beynehüm. küllü şirbim muḥteḍar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'fenâdev ṣâḥibehüm fete`âṭâ fe`aḳara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'fekeyfe kâne `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'innâ erselnâ `aleyhim ṣayḥatev vâḥideten fekânû keheşîmi-lmuḥteżir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'veleḳad yesserne-lḳur''âne liẕẕikri fehel mim müddekir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'keẕẕebet ḳavmü lûṭim binnüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'innâ erselnâ `aleyhim ḥâṣiben illâ âle lûṭ. necceynâhüm biseḥar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'ni`metem min `indinâ. keẕâlike neczî men şekera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'veleḳad enẕerahüm baṭşetenâ fetemârav binnüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'veleḳad râvedûhü `an ḍayfihî feṭamesnâ a`yünehüm feẕûḳû `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'veleḳad ṣabbeḥahüm bükraten `aẕâbüm müsteḳirr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'feẕûḳû `aẕâbî venüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'veleḳad yesserne-lḳur''âne liẕẕikri fehel mim müddekir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'veleḳad câe âle fir`avne-nnüẕür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'keẕẕebû biâyâtinâ küllihâ feeḫaẕnâhüm aḫẕe `azîzim muḳtedir.', '');
