INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'inne-lmücrimîne fî ḍalâliv vesü`ur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'yevme yüsḥabûne fi-nnâri `alâ vucûhihim. ẕûḳû messe seḳara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'innâ külle şey''in ḫalaḳnâhü biḳader.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'vemâ emrunâ illâ vâḥidetün kelemḥim bilbeṣar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'veleḳad ehleknâ eşyâ`aküm fehel mim müddekir.', '');
