INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'fî cennâti-nne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'ŝülletüm mine-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'veḳalîlüm mine-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, '`alâ sürurim mevḍûneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'müttekiîne `aleyhâ müteḳâbilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'yeṭûfü `aleyhim vildânüm müḫalledûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'biekvâbiv veebârîḳa veke''sim mim me`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'lâ yüṣadde`ûne `anhâ velâ yünzifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'vefâkihetim mimmâ yeteḫayyerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'velaḥmi ṭayrim mimmâ yeştehûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'veḥûrun `în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'keemŝâli-llü''lüi-lmeknûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'cezâem bimâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'lâ yesme`ûne fîhâ lagvev velâ te''ŝîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'illâ ḳîlen selâmen selâmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'veaṣḥâbü-lyemîni mâ aṣḥâbü-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, 'fî sidrim maḫḍûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'veṭalḥim menḍûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'veżillim memdûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'vemâim meskûb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'vefâkihetin keŝîrah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'lâ maḳṭû`ativ velâ memnû`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'vefüruşim merfû`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'innâ enşe''nâhünne inşââ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'fece`alnâhünne ebkârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, '`uruben etrâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'liaṣḥâbi-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'ŝülletüm mine-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'veŝülletüm mine-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'veaṣḥâbü-şşimâli mâ aṣḥâbü-şşimâl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'fî semûmiv veḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'veżillim miy yaḥmûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'lâ bâridiv velâ kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'innehüm kânû ḳable ẕâlike mütrafîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'vekânû yüṣirrûne `ale-lḥinŝi-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'vekânû yeḳûlûne eiẕâ mitnâ vekünnâ türâbev ve`iżâmen einnâ lemeb`ûŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'eveâbâüne-l''evvelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'ḳul inne-l''evvelîne vel''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'lemecmû`ûne ilâ mîḳâti yevmim ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'ŝümme inneküm eyyühe-ḍḍâllûne-lmükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'leâkilûne min şecerim min zeḳḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'femâliûne minhe-lbüṭûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'feşâribûne `aleyhi mine-lḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'feşâribûne şürbe-lhîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'hâẕâ nüzülühüm yevme-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'naḥnü ḫalaḳnâküm felevlâ tüṣaddiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'eferaeytüm mâ tümnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'eentüm taḫlüḳûnehû em naḥnü-lḫâliḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'naḥnü ḳaddernâ beynekümü-lmevte vemâ naḥnü bimesbûḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, '`alâ en nübeddile emŝâleküm venünşieküm fî mâ lâ ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'veleḳad `alimtümü-nneş''ete-l''ûlâ felevlâ teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'eferaeytüm mâ taḥruŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'eentüm tezra`ûnehû em naḥnü-zzâri`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'lev neşâü lece`alnâhü ḥuṭâmen feżaltüm tefekkehûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, 'innâ lemugramûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'bel naḥnü maḥrûmûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'eferaeytümü-lmâe-lleẕî teşrabûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'eentüm enzeltümûhü mine-lmüzni em naḥnü-lmünzilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'lev neşâü ce`alnâhü ücâcen felevlâ teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'eferaeytümü-nnâra-lletî tûrûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'eentüm enşe''tüm şeceratehâ em naḥnü-lmünşiûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'naḥnü ce`alnâhâ teẕkiratev vemetâ`al lilmuḳvîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'fesebbiḥ bismi rabbike-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'felâ uḳsimü bimevâḳi`i-nnücûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'veinnehû leḳasemül lev ta`lemûne `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'innehû leḳur''ânün kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'fî kitâbim meknûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'lâ yemessühû ille-lmüṭahherûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'tenzîlüm mir rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'efebihâẕe-lḥadîŝi entüm müdhinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'vetec`alûne rizḳaküm enneküm tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'felevlâ iẕâ belegati-lḥulḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'veentüm ḥîneiẕin tenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'venaḥnü aḳrabü ileyhi minküm velâkil lâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'felevlâ in küntüm gayra medînîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'terci`ûnehâ in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'feemmâ in kâne mine-lmüḳarrabîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'feravḥuv verayḥânüv vecennâtü ne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'veemmâ in kâne min aṣḥâbi-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'feselâmül leke min aṣḥâbi-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'veemmâ in kâne mine-lmükeẕẕibîne-ḍḍâllîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'fenüzülüm min ḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'vetaṣliyetü ceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'inne hâẕâ lehüve ḥaḳḳu-lyeḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'fesebbiḥ bismi rabbike-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'sebbeḥa lillâhi mâ fi-ssemâvâti vel''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'lehû mülkü-ssemâvâti vel''arḍ. yuḥyî veyümît. vehüve `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'hüve-l''evvelü vel''âḫiru veżżâhiru velbâṭin. vehüve bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'hüve-lleẕî ḫaleḳa-ssemâvâti vel''arḍa fî sitteti eyyâmin ŝümme-stevâ `ale-l`arş. ya`lemü mâ yelicü fi-l''arḍi vemâ yaḫrucü minhâ vemâ yenzilü mine-ssemâi vemâ ya`rucü fîhâ. vehüve me`aküm eyne mâ küntüm. vellâhü bimâ ta`melûne beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'lehû mülkü-ssemâvâti vel''arḍ. veile-llâhi türce`u-l''ümûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'yûlicü-lleyle fi-nnehâri veyûlicü-nnehâra fi-lleyl. vehüve `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'âminû billâhi verasûlihî veenfiḳû mimmâ ce`aleküm müstaḫlefîne fîh. felleẕîne âmenû minküm veenfeḳû lehüm ecrun kebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'vemâ leküm lâ tü''minûne billâh. verrasûlü yed`ûküm litü''minû birabbiküm veḳad eḫaẕe mîŝâḳaküm in küntüm mü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'hüve-lleẕî yünezzilü `alâ `abdihî âyâtim beyyinâtil liyuḫriceküm mine-żżulümâti ile-nnûr. veinne-llâhe biküm leraûfür raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'vemâ leküm ellâ tünfiḳû fî sebîli-llâhi velillâhi mîrâŝü-ssemâvâti vel''arḍ. lâ yestevî minküm men enfeḳa min ḳabli-lfetḥi veḳâtel. ülâike a`żamü deracetem mine-lleẕîne enfeḳû mim ba`dü veḳâtelû. veküllev ve`ade-llâhü-lḥusnâ. vellâhü bimâ ta`melûne ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'men ẕe-lleẕî yuḳriḍu-llâhe ḳarḍan ḥasenen feyüḍâ`ifehû lehû velehû ecrun kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'yevme tera-lmü''minîne velmü''minâti yes`â nûruhüm beyne eydîhim vebieymânihim büşrâkümü-lyevme cennâtün tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ. ẕâlike hüve-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'yevme yeḳûlü-lmünâfiḳûne velmünâfiḳâtü lilleẕîne âmenü-nżurûnâ naḳtebis min nûriküm ḳîle-rci`û verâeküm feltemisû nûrâ. feḍuribe beynehüm bisûril lehû bâb. bâṭinühû fîhi-rraḥmetü veżâhiruhû min ḳibelihi-l`aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, 'yünâdûnehüm elem neküm me`aküm. ḳâlû belâ velâkinneküm fetentüm enfüseküm veterabbaṣtüm vertebtüm vegarratkümü-l''emâniyyü ḥattâ câe emru-llâhi vegarraküm billâhi-lgarûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'felyevme lâ yü''ḫaẕü minküm fidyetüv velâ mine-lleẕîne keferû. me''vâkümü-nnâr. hiye mevlâküm. vebi''se-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'elem ye''ni lilleẕîne âmenû en taḫşe`a ḳulûbühüm liẕikri-llâhi vemâ nezele mine-lḥaḳḳi velâ yekûnû kelleẕîne ûtü-lkitâbe min ḳablü feṭâle `aleyhimü-l''emedü feḳaset ḳulûbühüm. vekeŝîrum minhüm fâsiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'i`lemû enne-llâhe yuḥyi-l''arḍa ba`de mevtihâ. ḳad beyyennâ lekümü-l''âyâti le`alleküm ta`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'inne-lmüṣṣaddiḳîne velmüṣṣaddiḳâti veaḳraḍu-llâhe ḳarḍan ḥaseney yüḍâ`afü lehüm velehüm ecrun kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'velleẕîne âmenû billâhi verusülihî ülâike hümu-ṣṣiddîḳûn. veşşühedâü `inde rabbihim. lehüm ecruhüm venûruhüm. velleẕîne keferû vekeẕẕebû biâyâtinâ ülâike aṣḥâbü-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'i`lemû enneme-lḥayâtü-ddünyâ le`ibüv velehvüv vezînetüv vetefâḫurum beyneküm vetekâŝürun fi-l''emvâli vel''evlâd. kemeŝeli gayŝin a`cebe-lküffâra nebâtühû ŝümme yehîcü feterâhü muṣferran ŝümme yekûnü ḥuṭâmâ. vefi-l''âḫirati `aẕâbün şedîdüv vemagfiratüm mine-llâhi veriḍvân. veme-lḥayâtü-ddünyâ illâ metâ`u-lgurûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'sâbiḳû ilâ magfiratim mir rabbiküm vecennetin `arḍuhâ ke`arḍi-ssemâi vel''arḍi ü`iddet lilleẕîne âmenû billâhi verusülih. ẕâlike faḍlü-llâhi yü''tîhi mey yeşâ''. vellâhü ẕü-lfaḍli-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'mâ eṣâbe mim müṣîbetin fi-l''arḍi velâ fî enfüsiküm illâ fî kitâbim min ḳabli en nebraehâ. inne ẕâlike `ale-llâhi yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'likeylâ te''sev `alâ mâ fâteküm velâ tefraḥû bimâ âtâküm. vellâhü lâ yüḥibbü külle muḫtâlin feḫûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'elleẕîne yebḫalûne veye''mürûne-nnâse bilbuḫl. vemey yetevelle feinne-llâhe hüve-lganiyyü-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'leḳad erselnâ rusülenâ bilbeyyinâti veenzelnâ me`ahümü-lkitâbe velmîzâne liyeḳûme-nnâsü bilḳisṭ. veenzelne-lḥadîde fîhi be''sün şedîdüv vemenâfi`u linnâsi veliya`leme-llâhü mey yenṣuruhû verusülehû bilgayb. inne-llâhe ḳaviyyün `azîz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'veleḳad erselnâ nûḥav veibrâhime vece`alnâ fî ẕürriyyetihime-nnübüvvete velkitâbe feminhüm mühted. vekeŝîrum minhüm fâsiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'ŝümme ḳaffeynâ `alâ âŝârihim birusülinâ veḳaffeynâ bi`îse-bni meryeme veâteynâhü-l''incîle vece`alnâ fî ḳulûbi-lleẕîne-ttebe`ûhü ra''fetev veraḥmeh. verahbâniyyeten-btede`ûhâ mâ ketebnâhâ `aleyhim ille-btigâe riḍvâni-llâhi femâ ra`avhâ ḥaḳḳa ri`âyetihâ. feâteyne-lleẕîne âmenû minhüm ecrahüm. vekeŝîrum minhüm fâsiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'yâ eyyühe-lleẕîne âmenü-tteḳu-llâhe veâminû birasûlihî yü''tiküm kifleyni mir raḥmetihî veyec`al leküm nûran temşûne bihî veyagfir leküm. vellâhü gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'liellâ ya`leme ehlü-lkitâbi ellâ yaḳdirûne `alâ şey''im min faḍli-llâhi veenne-lfaḍle biyedi-llâhi yü''tîhi mey yeşâ''. vellâhü ẕü-lfaḍli-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'ḳad semi`a-llâhü ḳavle-lletî tücâdilüke fi zevcihâ veteştekî ile-llâh. vellâhü yesme`u teḥâvurakümâ. inne-llâhe semî`um beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'elleẕîne yüżâhirûne minküm min nisâihim mâ hünne ümmehâtihim. in ümmehâtühüm ille-llâî velednâhüm. veinnehüm leyeḳûlûne münkeram mine-lḳavli vezûrâ. veinne-llâhe le`afüvvun gafûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'velleẕîne yüżâhirûne min nisâihim ŝümme ye`ûdûne limâ ḳâlû fetaḥrîru raḳabetim min ḳabli ey yetemâssâ. ẕâliküm tû`ażûne bih. vellâhü bimâ ta`melûne ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'femel lem yecid feṣiyâmü şehrayni mütetâbi`ayni min ḳabli ey yetemâssâ. femel lem yesteṭi` feiṭ`âmü sittîne miskînâ. ẕâlike litü''minû billâhi verasûlih. vetilke ḥudûdü-llâh. velilkâfirîne `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'inne-lleẕîne yüḥâddûne-llâhe verasûlehû kübitû kemâ kübite-lleẕîne min ḳablihim veḳad enzelnâ âyâtim beyyinât. velilkâfirîne `aẕâbüm mühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'yevme yeb`aŝühümü-llâhü cemî`an feyünebbiühüm bimâ `amilû. aḥṣâhü-llâhü venesûh. vellâhü `alâ külli şey''in şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'elem tera enne-llâhe ya`lemü mâ fi-ssemâvâti vemâ fi-l''arḍ. mâ yekûnü min necvâ ŝelâŝetin illâ hüve râbi`uhüm velâ ḫamsetin illâ hüve sâdisühüm velâ ednâ min ẕâlike velâ ekŝera illâ hüve me`ahüm eyne mâ kânû. ŝümme yünebbiühüm bimâ `amilû yevme-lḳiyâmeh. inne-llâhe bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'elem tera ile-lleẕîne nühû `ani-nnecvâ ŝümme ye`ûdûne limâ nühû `anhü veyetenâcevne bil''iŝmi vel`udvâv vema`ṣiyeti-rrasûl. veiẕâ câûke ḥayyevke bimâ lem yüḥayyike bihi-llâhü veyeḳûlûne fî enfüsihim levlâ yü`aẕẕibüne-llâhü bimâ neḳûl. ḥasbühüm cehennem. yaṣlevnehâ. febi''se-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'yâ eyyühe-lleẕîne âmenû iẕâ tenâceytüm felâ tetenâcev bil''iŝmi vel`udvâni vema`ṣiyeti-rrasûli vetenâcev bilbirri vettaḳvâ. vetteḳu-llâhe-lleẕî ileyhi tuḥşerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'inneme-nnecvâ mine-şşeyṭâni liyaḥzüne-lleẕîne âmenû veleyse biḍârrihim şey''en illâ biiẕni-llâh. ve`ale-llâhi felyetevekkeli-lmü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'yâ eyyühe-lleẕîne âmenû iẕâ ḳîle leküm tefesseḥû fi-lmecâlisi fefseḥû yefseḥi-llâhü leküm. veiẕâ ḳîle-nşüzû fenşüzû yerfe`i-llâhü-lleẕîne âmenû minküm velleẕîne ûtü-l`ilme deracât. vellâhü bimâ ta`melûne ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'yâ eyyühe-lleẕîne âmenû iẕâ nâceytümü-rrasûle feḳaddimû beyne yedey necvâküm ṣadeḳaten. ẕâlike ḫayrul leküm veaṭher. feil lem tecidû feinne-llâhe gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'eeşfaḳtüm en tüḳaddimû beyne yedey necvâküm ṣadeḳât. feiẕ lem tef`alû vetâbe-llâhü `aleyküm feeḳîmu-ṣṣalâte veâtü-zzekâte veeṭî`ü-llâhe verasûleh. vellâhü ḫabîrum bimâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'elem tera ile-lleẕîne tevellev ḳavmen gaḍibe-llâhü `aleyhim. mâ hüm minküm velâ minhüm veyaḥlifûne `ale-lkeẕibi vehüm ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'e`adde-llâhü lehüm `aẕâben şedîdâ. innehüm sâe mâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'itteḫaẕû eymânehüm cünneten feṣaddû `an sebîli-llâhi felehüm `aẕâbüm mühîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'len tugniye `anhüm emvâlühüm velâ evlâdühüm mine-llâhi şey''â. ülâike aṣḥâbü-nnâr. hüm fîhâ ḫâlidûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'yevme yeb`aŝühümü-llâhü cemî`an feyaḥlifûne lehû kemâ yaḥlifûne leküm veyaḥsebûne ennehüm `alâ şey''. elâ innehüm hümü-lkâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'istaḥveẕe `aleyhimü-şşeyṭânü feensâhüm ẕikra-llâh. ülâike ḥizbü-şşeyṭân. elâ inne ḥizbe-şşeyṭâni hümü-lḫâsirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'inne-lleẕîne yüḥâddûne-llâhe verasûlehû ülâike fi-l''eẕellîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'ketebe-llâhü leaglibenne ene verusülî. inne-llâhe ḳaviyyün `azîz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'lâ tecidü ḳavmey yü''minûne billâhi velyevmi-l''âḫiri yüvâddûne men ḥâdde-llâhe verasûlehû velev kânû âbâehüm ev ebnâehüm ev iḫvânehüm ev `aşîratehüm. ülâike ketebe fî ḳulûbihimü-l''îmâne veeyyedehüm birûḥim minh. veyüdḫilühüm cennâtin tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ. raḍiye-llâhü `anhüm veraḍû `anh. ülâike ḥizbü-llâh. elâ inne ḥizbe-llâhi hümü-lmüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'sebbeḥa lillâhi mâ fi-ssemâvâti vemâ fi-l''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'hüve-lleẕî aḫrace-lleẕîne keferû min ehli-lkitâbi min diyârihim lievveli-lḥaşr. mâ żanentüm ey yaḫrucû veżannû ennehüm mâni`atühüm ḥuṣûnühüm mine-llâhi feetâhümü-llâhü min ḥayŝü lem yaḥtesibû veḳaẕefe fî ḳulûbihimü-rru`be yuḫribûne büyûtehüm bieydîhim veeydi-lmü''minîne fa`tebirû yâ ûli-l''ebṣâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'velevlâ en ketebe-llâhü `aleyhimü-lcelâe le`aẕẕebehüm fi-ddünyâ. velehüm fi-l''âḫirati `aẕâbü-nnâr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'ẕâlike biennehüm şâḳḳu-llâhe verasûleh. vemey yüşâḳḳi-llâhe feinne-llâhe şedîdü-l`iḳâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'mâ ḳata`tüm mil lînetin ev teraktümûhâ ḳâimeten `alâ üṣûlihâ febiiẕni-llâhi veliyuḫziye-lfâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'vemâ efâe-llâhü `alâ rasûlihî minhüm femâ evceftüm `aleyhi min ḫayliv velâ rikâbiv velâkinne-llâhe yüselliṭu rusülehû `alâ mey yeşâ''. vellâhü `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'mâ efâe-llâhü `alâ rasûlihî min ehli-lḳurâ felillâhi velirrasûli veliẕi-lḳurbâ velyetâmâ velmesâkîni vebni-ssebîli key lâ yekûne dûletem beyne-l''agniyâi minküm. vemâ âtâkümü-rrasûlü feḫuẕûhü vemâ nehâküm `anhü fentehû. vetteḳu-llâh. inne-llâhe şedîdü-l`iḳâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'lilfüḳarâi-lmühâcirîne-lleẕîne uḫricû min diyârihim veemvâlihim yebtegûne faḍlem mine-llâhi veriḍvânev veyenṣurûne-llâhe verasûleh. ülâike hümu-ṣṣâdiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'velleẕîne tebevveü-ddâra vel''îmâne min ḳablihim yüḥibbûne men hâcera ileyhim velâ yecidûne fî ṣudûrihim ḥâcetem mimmâ ûtû veyü''ŝirûne `alâ enfüsihim velev kâne bihim ḫaṣâṣah. vemey yûḳa şüḥḥa nefsihî feülâike hümü-lmüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'velleẕîne câû mim ba`dihim yeḳûlûne rabbene-gfir lenâ veliiḫvânine-lleẕîne sebeḳûnâ bil''îmâni velâ tec`al fî ḳulûbinâ gillel lilleẕîne âmenû rabbenâ inneke raûfür raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'elem tera ile-lleẕîne nâfeḳû yeḳûlûne liiḫvânihimü-lleẕîne keferû min ehli-lkitâbi lein uḫrictüm lenaḫrucenne me`aküm velâ nüṭî`u fîküm eḥaden ebedev vein ḳûtiltüm lenenṣuranneküm. vellâhü yeşhedü innehüm lekâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'lein uḫricû lâ yaḫrucûne me`ahüm. velein ḳûtilû lâ yenṣurûnehüm. velein neṣarûhüm leyüvellünne-l''edbâr. ŝümme lâ yünṣarûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'leentüm eşeddü rahbeten fî ṣudûrihim mine-llâh. ẕâlike biennehüm ḳavmül lâ yefḳahûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'lâ yüḳâtilûneküm cemî`an illâ fî ḳuram müḥaṣṣanetin ev miv verâi cüdür. be''sühüm beynehüm şedîd. taḥsebühüm cemî`av veḳulûbühüm şettâ. ẕâlike biennehüm ḳavmül lâ ya`ḳilûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, 'kemeŝeli-lleẕîne min ḳablihim ḳarîben ẕâḳû vebâle emrihim. velehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'kemeŝeli-şşeyṭâni iẕ ḳâle lil''insâni-kfür. felemmâ kefera ḳâle innî berîüm minke innî eḫâfü-llâhe rabbe-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'fekâne `âḳibetehümâ ennehümâ fi-nnâri ḫâlideyni fîhâ. veẕâlike cezâu-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'yâ eyyühe-lleẕîne âmenü-tteḳu-llâhe veltenżur nefsüm mâ ḳaddemet ligad. vetteḳu-llâh. inne-llâhe ḫabîrum bimâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'velâ tekûnû kelleẕîne nesü-llâhe feensâhüm enfüsehüm. ülâike hümü-lfâsiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'lâ yestevî aṣḥâbü-nnâri veaṣḥâbü-lcenneh. aṣḥâbü-lcenneti hümü-lfâizûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'lev enzelnâ hâẕe-lḳur''âne `alâ cebelil lera''eytehû ḫâşi`am müteṣaddi`am min ḫaşyeti-llâh. vetilke-l''emŝâlü naḍribühâ linnâsi le`allehüm yetefekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'hüve-llâhü-lleẕî lâ ilâhe illâ hû. `âlimü-lgaybi veşşehâdeh. hüve-rraḥmânü-rraḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'hüve-llâhü-lleẕî lâ ilâhe illâ hû. elmelikü-lḳuddûsü-sselâmü-lmü''minü-lmüheyminü-l`azîzü-lcebbâru-lmütekebbir. sübḥâne-llâhi `ammâ yüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'hüve-llâhü-lḫâliḳu-lbâriü-lmüṣavviru lehü-l''esmâü-lḥusnâ. yüsebbiḥu lehû mâ fi-ssemâvâti vel''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'yâ eyyühe-lleẕîne âmenû lâ tetteḫiẕû `adüvvî ve`adüvveküm evliyâe tülḳûne ileyhim bilmeveddeti veḳad keferû bimâ câeküm mine-lḥaḳḳ. yuḫricûne-rrasûle veiyyâküm en tü''minû billâhi rabbiküm. in küntüm ḫaractüm cihâden fî sebîlî vebtigâe merḍâtî tüsirrûne ileyhim bilmeveddeh. veenâ a`lemü bimâ aḫfeytüm vemâ a`lentüm. vemey yef`alhü minküm feḳad ḍalle sevâe-ssebîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'iy yeŝḳafûküm yekûnû leküm a`dâev veyebsüṭû ileyküm eydiyehüm veelsinetehüm bissûi veveddû lev tekfürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'len tenfe`aküm erḥâmüküm velâ evlâdüküm. yevme-lḳiyâmeh. yefṣilü beyneküm. vellâhü bimâ ta`melûne beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'ḳad kânet leküm üsvetün ḥasenetün fî ibrâhîme velleẕîne me`ah. iẕ ḳâlû liḳavmihim innâ büraâü minküm vemimmâ ta`büdûne min dûni-llâh. kefernâ biküm vebedâ beynenâ vebeynekümü-l`adâvetü vebagḍâü ebeden ḥattâ tü''minû billâhi vaḥdehû illâ ḳavle ibrâhîme liebîhi leestagfiranne leke vemâ emlikü leke mine-llâhi min şey''. rabbenâ `aleyke tevekkelnâ veileyke enebnâ veileyke-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'rabbenâ lâ tec`alnâ fitnetel lilleẕîne keferû vagfir lenâ rabbenâ. inneke ente-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'leḳad kâne leküm fîhim üsvetün ḥasenetül limen kâne yercü-llâhe velyevme-l''âhir. vemey yetevelle feinne-llâhe hüve-lganiyyü-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, '`asa-llâhü ey yec`ale beyneküm vebeyne-lleẕîne `âdeytüm minhüm meveddeh. vellâhü ḳadîr. vellâhü gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'lâ yenhâkümü-llâhü `ani-lleẕîne lem yüḳâtilûküm fi-ddîni velem yuḫricûküm min diyâriküm en teberrûhüm vetuḳsiṭû ileyhim. inne-llâhe yüḥibbü-lmuḳsiṭîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'innemâ yenhâkümü-llâhü `ani-lleẕîne ḳâtelûküm fi-ddîni veaḫracûküm min diyâriküm veżâherû `alâ iḫrâciküm en tevellevhüm. vemey yetevellehüm feülâike hümu-żżâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'yâ eyyühe-lleẕîne âmenû iẕâ câekümü-lmü''minâtü mühâcirâtin femteḥinûhünn. allâhü a`lemü biîmânihinn. fein `alimtümûhünne mü''minâtin felâ terci`ûhünne ile-lküffâr. lâ hünne ḥillül lehüm velâ hüm yeḥillûne lehünn. veâtûhüm mâ enfeḳû. velâ cünâḥa `aleyküm en tenkiḥûhünne iẕâ âteytümûhünne ücûrahünn. velâ tümsikû bi`iṣami-lkevâfiri ves''elû mâ enfaḳtüm velyes''elû mâ enfeḳû. ẕâliküm ḥukmü-llâh. yaḥkümü beyneküm. vellâhü `alîmün ḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'vein fâteküm şey''üm min ezvâciküm ile-lküffâri fe`âḳabtüm feâtü-lleẕîne ẕehebet ezvâcühüm miŝle mâ enfeḳû. vetteḳu-llâhe-lleẕî entüm bihî mü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'yâ eyyühe-nnebiyyü iẕâ câeke-lmü''minâtü yübâyi`neke `alâ el lâ yüşrikne billâhi şey''ev velâ yesriḳne velâ yeznîne velâ yaḳtülne evlâdehünne velâ ye''tîne bibühtâniy yefterînehû beyne eydîhinne veercülihinne velâ ya`ṣîneke fî ma`rûfin febâyi`hünne vestagfir lehünne-llâh. inne-llâhe gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'yâ eyyühe-lleẕîne âmenû lâ tetevellev ḳavmen gaḍibe-llâhü `aleyhim ḳad yeisû mine-l''âḫirati kemâ yeise-lküffâru min aṣḥâbi-lḳubûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'sebbeḥa lillâhi mâ fi-ssemâvâti vemâ fi-l''arḍ. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'yâ eyyühe-lleẕîne âmenû lime teḳûlûne mâ lâ tef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'kebüra maḳten `inde-llâhi en teḳûlû mâ lâ tef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'inne-llâhe yüḥibbü-lleẕîne yüḳâtilûne fî sebîlihî ṣaffen keennehüm bünyânüm merṣûṣ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'veiẕ ḳâle mûsâ liḳavmihî yâ ḳavmi lime tü''ẕûnenî veḳat ta`lemûne ennî rasûlü-llâhi ileyküm. felemmâ zâgû ezâga-llâhü ḳulûbehüm. vellâhü lâ yehdi-lḳavme-lfâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'veiẕ ḳâle `îse-bnü meryeme yâ benî isrâîle innî rasûlü-llâhi ileyküm müṣaddiḳal limâ beyne yedeyye mine-ttevrâti vemübeşşiram birasûliy ye''tî mim ba`di-smühû aḥmed. felemmâ câehüm bilbeyyinâti ḳâlû hâẕâ siḥrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'vemen ażlemü mimmeni-fterâ `ale-llâhi-lkeẕibe vehüve yüd`â ile-l''islâm. vellâhü lâ yehdi-lḳavme-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'yürîdûne liyuṭfiû nûra-llâhi biefvâhihim vellâhü mütimmü nûrihî velev kerihe-lkâfirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'hüve-lleẕî ersele rasûlehû bilhüdâ vedîni-lḥaḳḳi liyużhirahû `ale-ddîni küllihî velev kerihe-lmüşrikûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'yâ eyyühe-lleẕîne âmenû hel edüllüküm `alâ ticâratin tüncîküm min `aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'tü''minûne billâhi verasûlihî vetücâhidûne fî sebîli-llâhi biemvâliküm veenfüsiküm. ẕâliküm ḫayrul leküm in küntüm ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, 'yagfir leküm ẕünûbeküm veyüdḫilküm cennâtin tecrî min taḥtihe-l''enhâru vemesâkine ṭayyibeten fî cennâti `adn. ẕâlike-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'veuḫrâ tüḥibbûnehâ. naṣrum mine-llâhi vefetḥun ḳarîb. vebeşşiri-lmü''minîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'yâ eyyühe-lleẕîne âmenû kûnû enṣâra-llâhi kemâ ḳâle `îse-bnü meryeme lilḥavâriyyîne men enṣârî ile-llâh. ḳâle-lḥavâriyyûne naḥnü enṣâru-llâhi feâmeneṭ ṭâifetüm mim benî isrâîle vekeferaṭ ṭâifeh. feeyyedne-lleẕîne âmenû `alâ `adüvvihim feaṣbeḥû żâhirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'yüsebbiḥu lillâhi mâ fi-ssemâvâti vemâ fi-l''arḍi-lmeliki-lḳuddûsi-l`azîzi-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'hüve-lleẕî be`aŝe fi-l''ümmiyyîne rasûlem minhüm yetlû `aleyhim âyâtihî veyüzekkîhim veyü`allimühümü-lkitâbe velḥikmeh. vein kânû min ḳablü lefî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'veâḫarîne minhüm lemmâ yelḥaḳû bihim. vehüve-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'ẕâlike faḍlü-llâhi yü''tîhi mey yeşâ''. vellâhü ẕü-lfaḍli-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'meŝelü-lleẕîne ḥummilü-ttevrâte ŝümme lem yaḥmilûhâ kemeŝeli-lḥimâri yaḥmilü esfârâ. bi''se meŝelü-lḳavmi-lleẕîne keẕẕebû biâyâti-llâh. vellâhü lâ yehdi-lḳavme-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'ḳul yâ eyyühe-lleẕîne hâdû in za`amtüm enneküm evliyâü lillâhi min dûni-nnâsi fetemennevu-lmevte in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'velâ yetemennevnehû ebedem bimâ ḳaddemet eydîhim. vellâhü `alîmüm biżżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'ḳul inne-lmevte-lleẕî tefirrûne minhü feinnehû mülâḳîküm ŝümme türaddûne ilâ `âlimi-lgaybi veşşehâdeti feyünebbiüküm bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'yâ eyyühe-lleẕîne âmenû iẕâ nûdiye liṣṣalâti miy yevmi-lcümü`ati fes`av ilâ ẕikri-llâhi veẕerü-lbey`. ẕâliküm ḫayrul leküm in küntüm ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'feiẕâ ḳuḍiyeti-ṣṣâletü fenteşirû fi-l''arḍi vebtegû min faḍli-llâhi veẕkürü-llâhe keŝîral le`alleküm tüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'veiẕâ raev ticâraten ev lehven-nfeḍḍû ileyhâ veterakûke ḳâimâ. ḳul mâ `inde-llâhi ḫayrum mine-llehvi vemine-tticârah. vellâhü ḫayru-rrâziḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'iẕâ câeke-lmünâfiḳûne ḳâlû neşhedü inneke lerasûlü-llâh. vellâhü ya`lemü inneke lerasûlüh. vellâhü yeşhedü inne-lmünâfiḳîne lekâẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'itteḫaẕû eymânehüm cünneten feṣaddû `an sebîli-llâh. innehüm sâe mâ kânû ya`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'ẕâlike biennehüm âmenû ŝümme keferû feṭubi`a `alâ ḳulûbihim fehüm lâ yefḳahûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'veiẕâ raeytehüm tü`cibüke ecsâmühüm. veiy yeḳûlû tesma` liḳavlihim. keennehüm ḫuşübüm müsennedeh. yaḥsebûne külle ṣayḥatin `aleyhim. hümü-l`adüvvu faḥẕerhüm. ḳâtelehümü-llâh. ennâ yü''fekûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'veiẕâ ḳîle lehüm te`âlev yestagfir leküm rasûlü-llâhi levvev ruûsehüm veraeytehüm yeṣuddûne vehüm müstekbirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'sevâün `aleyhim estagferte lehüm em lem testagfir lehüm. ley yagfira-llâhü lehüm. inne-llâhe lâ yehdi-lḳavme-lfâsiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'hümü-lleẕîne yeḳûlûne lâ tünfiḳû `alâ men `inde rasûli-llâhi ḥattâ yenfeḍḍû. velillâhi ḫazâinü-ssemâvâti vel''arḍi velâkinne-lmünâfiḳîne lâ yefḳahûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'yeḳûlûne leir raca`nâ ile-lmedîneti leyuḫricenne-l''e`azzü minhe-l''eẕell. velillâhi-l`izzetü velirasûlihî velilmü''minîne velâkinne-lmünâfiḳîne lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'yâ eyyühe-lleẕîne âmenû lâ tülhiküm emvâlüküm velâ evlâdüküm `an ẕikri-llâh. vemey yef`al ẕâlike feülâike hümü-lḫâsirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'veenfiḳû mimmâ razaḳnâküm min ḳabli ey ye''tiye eḥadekümü-lmevtü feyeḳûle rabbi levlâ eḫḫartenî ilâ ecelin ḳarîbin feeṣṣaddeḳa veeküm mine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'veley yü''eḫḫira-llâhü nefsen iẕâ câe ecelühâ. vellâhü ḫabîrum bimâ ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'yüsebbiḥu lillâhi mâ fi-ssemâvâti vemâ fi-l''arḍ. lehü-lmülkü velehü-lḥamd. vehüve `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'hüve-lleẕî ḫaleḳaküm feminküm kâfiruv veminküm mü''min. vellâhü bimâ ta`melûne beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'ḫaleḳa-ssemâvâti vel''arḍa bilḥaḳḳi veṣavveraküm feaḥsene ṣuveraküm. veileyhi-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'ya`lemü mâ fi-ssemâvâti vel''arḍi veya`lemü mâ tüsirrûne vemâ tü`linûn. vellâhü `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'elem ye''tiküm nebeü-lleẕîne keferû min ḳabl. feẕâḳû vebâle emrihim velehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'ẕâlike biennehû kânet te''tîhim rusülühüm bilbeyyinâti feḳâlû ebeşeruy yehdûnenâ. fekeferû vetevellev vestagne-llâh. vellâhü ganiyyün ḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'za`ame-lleẕîne keferû el ley yüb`aŝû. ḳul belâ verabbî letüb`aŝünne ŝümme letünebbeünne bimâ `amiltüm. veẕâlike `ale-llâhi yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'feâminû billâhi verasûlihî vennûri-lleẕî enzelnâ. vellâhü bimâ ta`melûne ḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'yevme yecme`uküm liyevmi-lcem`i ẕâlike yevmü-ttegâbün. vemey yü''mim billâhi veya`mel ṣâliḥay yükeffir `anhü seyyiâtihî veyüdḫilhü cennâtin tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ ebedâ. ẕâlike-lfevzü-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'velleẕîne keferû vekeẕẕebû biâyâtinâ ülâike aṣḥâbü-nnâri ḫâlidîne fîhâ. vebi''se-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'mâ eṣâbe mim müṣîbetin illâ biiẕni-llâh. vemey yü''mim billâhi yehdi ḳalbeh. vellâhü bikülli şey''in `alîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'veeṭî`ü-llâhe veeṭî`ü-rrasûl. fein tevelleytüm feinnemâ `alâ rasûline-lbelâgu-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'allâhü lâ ilâhe illâ hû. ve`ale-llâhi felyetevekkeli-lmü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'yâ eyyühe-lleẕîne âmenû inne min ezvâciküm veevlâdiküm `adüvvel leküm faḥẕerûhüm. vein ta`fû vetaṣfeḥû vetagfirû feinne-llâhe gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'innemâ emvâlüküm veevlâdüküm fitnetün. vellâhü `indehû ecrun `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'fetteḳu-llâhe me-steṭa`tüm vesme`û veeṭî`û veenfiḳû ḫayral lienfüsiküm. vemey yûḳa şüḥḥa nefsihî feülâike hümü-lmüfliḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'in tuḳriḍü-llâhe ḳarḍan ḥaseney yüḍâ`ifhü leküm veyagfir leküm. vellâhü şekûrun ḥalîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, '`âlimü-lgaybi veşşehâdeti-l`azîzü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'yâ eyyühe-nnebiyyü iẕâ ṭallaḳtümü-nnisâe feṭalliḳûhünne li`iddetihinne veaḥṣü-l`iddeh. vetteḳu-llâhe rabbeküm. lâ tuḫricûhünne mim büyûtihinne velâ yaḫrucne illâ ey ye''tîne bifâḥişetim mübeyyineh. vetilke ḥudûdü-llâh. vemey yete`adde ḥudûde-llâhi feḳad żaleme nefseh. lâ tedrî le`alle-llâhe yuḥdiŝü ba`de ẕâlike emrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'feiẕâ belagne ecelehünne feemsikûhünne bima`rûfin ev fâriḳûhünne bima`rûfiv veeşhidû ẕevey `adlim minküm veeḳîmü-şşehâdete lillâh. ẕâliküm yû`ażu bihî men kâne yü''minü billâhi velyevmi-l''âḫir. vemey yetteḳi-llâhe yec`al lehû maḫracâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'veyerzuḳhü min ḥayŝü lâ yaḥtesib. vemey yetevekkel `ale-llâhi fehüve ḥasbüh. inne-llâhe bâligu emrih. ḳad ce`ale-llâhü likülli şey''in ḳadrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'vellâî yeisne mine-lmeḥîḍi min nisâiküm ini-rtebtüm fe`iddetühünne ŝelâŝetü eşhüriv vellâî lem yeḥiḍn. veülâtü-l''aḥmâli ecelühünne ey yeḍa`ne ḥamlehünn. vemey yetteḳi-llâhe yec`al lehû min emrihî yüsrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'ẕâlike emru-llâhi enzelehû ileyküm. vemey yetteḳi-llâhe yükeffir `anhü seyyiâtihî veyü`żim lehû ecrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'eskinûhünne min ḥayŝü sekentüm miv vucdiküm velâ tüḍârrûhünne litüḍayyiḳû `aleyhinn. vein künne ülâti ḥamlin feenfiḳû `aleyhinne ḥattâ yeḍa`ne ḥamlehünn. fein erḍa`ne leküm feâtûhünne ücûrahünn. ve''temirû beyneküm bima`rûf. vein te`âsertüm fesetürḍi`u lehû uḫrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'liyünfiḳ ẕû se`atim min se`atih. vemen ḳudira `aleyhi rizḳuhû felyünfiḳ mimmâ âtâhü-llâh. lâ yükellifü-llâhü nefsen illâ mâ âtâhâ. seyec`alü-llâhü ba`de `usriy yüsrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'vekeeyyim min ḳaryetin `atet `an emri rabbihâ verusülihî feḥâsebnâhâ ḥisâben şedîdev ve`aẕẕebnâhâ `aẕâben nükrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'feẕâḳat vebâle emrihâ vekâne `âḳibetü emrihâ ḫusrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'e`adde-llâhü lehüm `aẕâben şedîden fetteḳu-llâhe yâ ûli-l''elbâb. elleẕîne âmenû. ḳad enzele-llâhü ileyküm ẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'rasûley yetlû `aleyküm âyâti-llâhi mübeyyinâtil liyuḫrice-lleẕîne âmenû ve`amilu-ṣṣâliḥâti mine-żżulümâti ile-nnûr. vemey yü''mim billâhi veya`mel ṣâliḥay yüdḫilhü cennâtin tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ ebedâ. ḳad aḥsene-llâhü lehû rizḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'allâhü-lleẕî ḫaleḳa seb`a semâvâtiv vemine-l''arḍi miŝlehünn. yetenezzelü-l''emru beynehünne lita`lemû enne-llâhe `alâ külli şey''in ḳadîruv veenne-llâhe ḳad eḥâṭa bikülli şey''in `ilmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'yâ eyyühe-nnebiyyü lime tüḥarrimü mâ eḥalle-llâhü leke. tebtegî merḍâte ezvâcik. vellâhü gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'ḳad feraḍa-llâhü leküm teḥillete eymâniküm. vellâhü mevlâküm. vehüve-l`alîmü-lḥakîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'veiẕ eserra-nnebiyyü ilâ ba`ḍi ezvâcihî ḥadîŝâ. felemmâ nebbeet bihî veażherahü-llâhü `aleyhi `arrafe ba`ḍahû vea`raḍa `am ba`ḍ. felemmâ nebbeehâ bihî ḳâlet men embeeke hâẕâ. ḳâle nebbeeniye-l`alîmü-lḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'in tetûbâ ile-llâhi feḳad ṣagat ḳulûbükümâ. vein teżâherâ `aleyhi feinne-llâhe hüve mevlâhü vecibrîlü veṣâliḥu-lmü''minîn. velmelâiketü ba`de ẕâlike żahîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, '`asâ rabbühû in ṭalleḳakünne ey yübdilehû ezvâcen ḫayram minkünne müslimâtim mü''minâtin ḳânitâtin tâibâtin `âbidâtin sâiḥâtin ŝeyyibâtiv veebkârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'yâ eyyühe-lleẕîne âmenû ḳû enfüseküm veehlîküm nârav veḳûdühe-nnâsü velḥicâratü `aleyhâ melâiketün gilâżun şidâdül lâ ya`ṣûne-llâhe mâ emerahüm veyef`alûne mâ yü''merûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, 'yâ eyyühe-lleẕîne keferû lâ ta`teẕirü-lyevm. innemâ tüczevne mâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'yâ eyyühe-lleẕîne âmenû tûbû ile-llâhi tevbeten neṣûḥâ. `asâ rabbüküm ey yükeffira `anküm seyyiâtiküm veyüdḫileküm cennâtin tecrî min taḥtihe-l''enhâru yevme lâ yuḫzi-llâhü-nnebiyye velleẕîne âmenû me`ah. nûruhüm yes`â beyne eydîhim vebieymânihim yeḳûlûne rabbenâ etmim lenâ nûranâ vagfir lenâ. inneke `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'yâ eyyühe-nnebiyyü câhidi-lküffâra velmünâfiḳîne vagluż `aleyhim. veme''vâhüm cehennem. vebi''se-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'ḍarabe-llâhü meŝelel lilleẕîne keferü-mraete nûḥiv vemraete lûṭ. kânetâ taḥte `abdeyni min `ibâdinâ ṣâliḥayni feḫânetâhümâ felem yugniyâ `anhümâ mine-llâhi şey''ev veḳîle-dḫule-nnâra me`a-ddâḫilîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'veḍarabe-llâhü meŝelel lilleẕîne âmenü-mraete fir`avn. iẕ ḳâlet rabbi-bni lî `indeke beyten fi-lcenneti veneccinî min fir`avne ve`amelihî veneccinî mine-lḳavmi-żżâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'vemeryeme-bnete `imrâne-lletî aḥṣanet fercehâ fenefaḫnâ fîhi mir rûḥinâ veṣaddeḳat bikelimâti rabbihâ vekütübihî vekânet mine-lḳânitîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'tebârake-lleẕî biyedihi-lmülk. vehüve `alâ külli şey''in ḳadîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'elleẕî ḫaleḳa-lmevte velḥayâte liyeblüveküm eyyüküm aḥsenü `amelâ. vehüve-l`azîzü-lgafûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'elleẕî ḫaleḳa seb`a semâvâtin ṭibâḳâ. mâ terâ fî ḫalḳi-rraḥmâni min tefâvüt. ferci`i-lbeṣara hel terâ min füṭûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'ŝümme-rci`i-lbeṣara kerrateyni yenḳalib ileyke-lbeṣaru ḫâsiev vehüve ḥasîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'veleḳad zeyyenne-ssemâe-ddünyâ bimeṣâbîḥa vece`alnâhâ rucûmel lişşeyâṭîni vea`tednâ lehüm `aẕâbe-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'velilleẕîne keferû birabbihim `aẕâbü cehennem. vebi''se-lmeṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'iẕâ ülḳû fîhâ semi`û lehâ şehîḳav vehiye tefûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'tekâdü temeyyezü mine-lgayż. küllemâ ülḳiye fîhâ fevcün seelehüm ḫazenetühâ elem ye''tiküm neẕîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'ḳâlû belâ ḳad câenâ neẕîrun fekeẕẕebnâ veḳulnâ mâ nezzele-llâhü min şey''. in entüm illâ fî ḍalâlin kebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'veḳâlû lev künnâ nesme`u ev na`ḳilü mâ künnâ fî aṣḥâbi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'fa`terafû biẕembihim. fesuḥḳal liaṣḥâbi-sse`îr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'inne-lleẕîne yaḫşevne rabbehüm bilgaybi lehüm magfiratüv veecrun kebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'veesirrû ḳavleküm evi-cherû bih. innehû `alîmüm biẕâti-ṣṣudûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'elâ ya`lemü men ḫaleḳ. vehüve-lleṭîfü-lḫabîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'hüve-lleẕî ce`ale lekümü-l''arḍa ẕelûlen femşû fî menâkibihâ vekülû mir rizḳih. veileyhi-nnüşûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'eemintüm men fi-ssemâi ey yaḫsife bikümü-l''arḍa feiẕâ hiye temûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'em emintüm men fi-ssemâi ey yürsile `aleyküm ḥâṣibâ. feseta`lemûne keyfe neẕîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'veleḳad keẕẕebe-lleẕîne min ḳablihim fekeyfe kâne nekîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'evelem yerav ile-ṭṭayri fevḳahüm ṣâffâtiv veyaḳbiḍn. mâ yümsikühünne ille-rraḥmân. innehû bikülli şey''im beṣîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'emmen hâẕe-lleẕî hüve cündül leküm yenṣuruküm min dûni-rraḥmân. ini-lkâfirûne illâ fî gurûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'emmen hâẕe-lleẕî yerzüḳuküm in emseke rizḳah. bel leccû fî `utüvviv venüfûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'efemey yemşî mükibben `alâ vechihî ehdâ emmey yemşî seviyyen `alâ ṣirâṭim müsteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'ḳul hüve-lleẕî enşeeküm vece`ale lekümü-ssem`a vel''ebṣâra vel''ef''ideh. ḳalîlem mâ teşkürûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'ḳul hüve-lleẕî ẕera''eküm fi-l''arḍi veileyhi tuḥşerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'veyeḳûlûne metâ hâẕe-lva`dü in küntüm ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'ḳul inneme-l`ilmü `inde-llâh. veinnemâ ene neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'felemmâ raevhü zülfeten sîet vucûhü-lleẕîne keferû veḳîle hâẕe-lleẕî küntüm bihî tedde`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'ḳul era''eytüm in ehlekeniye-llâhü vemem me`iye ev raḥimenâ femey yücîru-lkâfirîne min `aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'ḳul hüve-rraḥmânü âmennâ bihî ve`aleyhi tevekkelnâ. feseta`lemûne men hüve fî ḍalâlim mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'ḳul era''eytüm in aṣbeḥa mâüküm gavran femey ye''tîküm bimâim me`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'nûn. velḳalemi vemâ yesṭurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'mâ ente bini`meti rabbike bimecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'veinne leke leecran gayra memnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'veinneke le`alâ ḫulüḳin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'fesetübṣiru veyübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'bieyyikümü-lmeftûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'inne rabbeke hüve a`lemü bimen ḍalle `an sebîlih. vehüve a`lemü bilmühtedîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'felâ tüṭi`i-lmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'veddû lev tüdhinü feyüdhinûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'velâ tüṭi` külle ḥallâfim mehîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'hemmâzim meşşâim binemîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'mennâ`il lilḫayri mü`tedin eŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, '`utüllim ba`de ẕâlike zenîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'en kâne ẕâ mâliv vebenîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'iẕâ tütlâ `aleyhi âyâtünâ ḳâle esâṭîru-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'senesimühû `ale-lḫurṭûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'innâ belevnâhüm kemâ belevnâ aṣḥâbe-lcenneh. iẕ aḳsemû leyaṣrimünnehâ muṣbiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'velâ yesteŝnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'feṭâfe `aleyhâ ṭâifüm mir rabbike vehüm nâimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'feaṣbeḥat keṣṣarîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'fetenâdev muṣbiḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, 'eni-gdû `alâ ḥarŝiküm in küntüm ṣârimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'fenṭaleḳû vehüm yeteḫâfetûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, 'el lâ yedḫulennehe-lyevme `aleyküm miskîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'vegadev `alâ ḥardin ḳâdirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'felemmâ raevhâ ḳâlû innâ leḍâllûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'bel naḥnü maḥrûmûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'ḳâle evseṭuhüm elem eḳul leküm levlâ tüsebbiḥûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, 'ḳâlû sübḥâne rabbinâ innâ künnâ żâlimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'feaḳbele ba`ḍuhüm `alâ ba`ḍiy yetelâvemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'ḳâlû yâ veylenâ innâ künnâ ṭâgîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, '`asâ rabbünâ ey yübdilenâ ḫayram minhâ innâ ilâ rabbinâ râgibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'keẕâlike-l`aẕâb. vele`aẕâbü-l''âḫirati ekber. lev kânû ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'inne lilmütteḳîne `inde rabbihim cennâti-nne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'efenec`alü-lmüslimîne kelmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'mâ leküm. keyfe taḥkümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'em leküm kitâbün fîhi tedrusûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'inne leküm fîhi lemâ teḫayyerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'em leküm eymânün `aleynâ bâligatün ilâ yevmi-lḳiyâmeti inne leküm lemâ taḥkümûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'selhüm eyyühüm biẕâlike za`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'em lehüm şürakâ''. felye''tû bişürakâihim in kânû ṣâdiḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'yevme yükşefü `an sâḳiv veyüd`avne ile-ssücûdi felâ yesteṭî`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'ḫâşi`aten ebṣâruhüm terheḳuhüm ẕilleh. veḳad kânû yüd`avne ile-ssücûdi vehüm sâlimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'feẕernî vemey yükeẕẕibü bihâẕe-lḥadîŝ. senestedricühüm min ḥayŝü lâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'veümlî lehüm. inne keydî metîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'em tes''elühüm ecran fehüm mim magramim müŝḳalûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'em `indehümü-lgaybü fehüm yektübûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'faṣbir liḥukmi rabbike velâ tekün keṣâḥibi-lḥût. iẕ nâdâ vehüve mekżûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'levlâ en tedârakehû ni`metüm mir rabbihî lenübiẕe bil`arâi vehüve meẕmûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'fectebâhü rabbühû fece`alehû mine-ṣṣâliḥîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'veiy yekâdü-lleẕîne keferû leyüzliḳûneke biebṣârihim lemmâ semi`ü-ẕẕikra veyeḳûlûne innehû lemecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'vemâ hüve illâ ẕikrul lil`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'elḥâḳḳah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'me-lḥâḳḳah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'vemâ edrâke me-lḥâḳḳah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'keẕẕebet ŝemûdü ve`âdüm bilḳâri`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'feemmâ ŝemûdü feühlikû biṭṭâgiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'veemmâ `âdün feühlikû birîḥin ṣarṣarin `âtiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'seḫḫarahâ `aleyhim seb`a leyâliv veŝemâniyete eyyâmin ḥusûmen fetere-lḳavme fîhâ ṣar`â keennehüm a`câzü naḫlin ḫâviyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'fehel terâ lehüm mim bâḳiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'vecâe fir`avnü vemen ḳablehû velmü''tefikâtü bilḫâṭieh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'fe`aṣav rasûle rabbihim feeḫaẕehüm aḫẕeter râbiyetâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'innâ lemmâ ṭaga-lmâü ḥamelnâküm fi-lcâriyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'linec`alehâ leküm teẕkiratev vete`iyehâ üẕünüv vâ`iyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'feiẕâ nüfiḫa fi-ṣṣûri nefḫatüv vâḥideh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'veḥumileti-l''arḍu velcibâlü fedükketâ dekketev vâḥidetâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'feyevmeiẕiv veḳa`ati-lvâḳi`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'venşeḳḳati-ssemâü fehiye yevmeiẕiv vâhiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'velmelekü `alâ ercâihâ. veyaḥmilü `arşe rabbike fevḳahüm yevmeiẕin ŝemâniyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'yevmeiẕin tü`raḍûne lâ taḫfâ minküm ḫâfiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'feemmâ men ûtiye kitâbehû biyemînihî feyeḳûlü hâümu-ḳraû kitâbiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'innî żanentü ennî mülâḳin ḥisâbiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'fehüve fî `îşetir râḍiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'fî cennetin `âliyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'ḳuṭûfühâ dâniyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, 'külû veşrabû henîem bimâ esleftüm fi-l''eyyâmi-lḫâliyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'veemmâ men ûtiye kitâbehû bişimâlihî feyeḳûlü yâ leytenî lem ûte kitâbiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'velem edri mâ ḥisâbiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'yâ leytehâ kâneti-lḳâḍiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'mâ agnâ `annî mâliyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'heleke `annî sülṭâniyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, 'ḫuẕûhü fegullûh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'ŝümme-lceḥîme ṣallûh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'ŝümme fî silsiletin ẕer`uhâ seb`ûne ẕirâ`an feslükûh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'innehû kâne lâ yü''minü billâhi-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'velâ yeḥuḍḍu `alâ ṭa`âmi-lmiskîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'feleyse lehü-lyevme hâhünâ ḥamîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'velâ ṭa`âmün illâ min gislîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'lâ ye''külühû ille-lḫâṭiûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'felâ uḳsimü bimâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'vemâ lâ tübṣirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'innehû leḳavlü rasûlin kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'vemâ hüve biḳavli şâ`ir. ḳalîlem mâ tü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'velâ biḳavli kâhin. ḳalîlem mâ teẕekkerûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'tenzîlüm mir rabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'velev teḳavvele `aleynâ ba`ḍa-l''eḳâvîl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'leeḫaẕnâ minhü bilyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'ŝümme leḳaṭa`nâ minhü-lvetîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'femâ minküm min eḥadin `anhü ḥâcizîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'veinnehû leteẕkiratül lilmütteḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'veinnâ lena`lemü enne minküm mükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'veinnehû leḥasratün `ale-lkâfirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'veinnehû leḥaḳḳu-lyeḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'fesebbiḥ bismi rabbike-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'seele sâilüm bi`aẕâbiv vâḳi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'lilkâfirîne leyse lehû dâfi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'mine-llâhi ẕi-lme`âric.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'ta`rucü-lmelâiketü verrûḥu ileyhi fî yevmin kâne miḳdâruhû ḫamsîne elfe seneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'faṣbir ṣabran cemîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'innehüm yeravnehû be`îdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'venerâhü ḳarîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'yevme tekûnü-ssemâü kelmühl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'vetekûnü-lcibâlü kel`ihn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'velâ yes''elü ḥamîmün ḥamîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'yübeṣṣarûnehüm. yeveddü-lmücrimü lev yeftedî min `aẕâbi yevmiiẕim bibenîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'veṣâḥibetihî veeḫîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'vefeṣîletihi-lletî tü''vîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'vemen fi-l''arḍi cemî`an ŝümme yüncîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'kellâ. innehâ leżâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'nezzâ`atel lişşevâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'ted`û men edbera vetevellâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'veceme`a feev`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'inne-l''insâne ḫuliḳa helû`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'iẕâ messehü-şşerru cezû`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'veiẕâ messehü-lḫayru menû`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'ille-lmüṣallîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'elleẕîne hüm `alâ ṣalâtihim dâimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'velleẕîne fî emvâlihim ḥaḳḳum ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'lissâili velmaḥrûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'velleẕîne yüṣaddiḳûne biyevmi-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'velleẕîne hüm min `aẕâbi rabbihim müşfiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'inne `aẕâbe rabbihim gayru me''mûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'velleẕîne hüm lifürûcihim ḥâfiżûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'illâ `alâ ezvâcihim ev mâ meleket eymânühüm feinnehüm gayru melûmîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'femeni-btegâ verâe ẕâlike feülâike hümü-l`âdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'velleẕîne hüm liemânâtihim ve`ahdihim râ`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'velleẕîne hüm bişehâdetihim ḳâimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'velleẕîne hüm `alâ ṣalâtihim yüḥâfiżûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'ülâike fî cennâtim mükramûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'femâ lilleẕîne keferû ḳibeleke mühti`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, '`ani-lyemîni ve`ani-şşimâli `izîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'eyaṭme`u küllü-mriim minhüm ey yüdḫale cennete ne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'kellâ. innâ ḫalaḳnâhüm mimmâ ya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'felâ uḳsimü birabbi-lmeşâriḳi velmegâribi innâ leḳâdirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, '`alâ en nübeddile ḫayram minhüm vemâ naḥnü bimesbûḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'feẕerhüm yeḫûḍû veyel`abû ḥattâ yülâḳû yevmehümü-lleẕî yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'yevme yaḫrucûne mine-l''ecdâŝi sirâ`an keennehüm ilâ nüṣubiy yûfiḍûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'ḫâşi`aten ebṣâruhüm terheḳuhüm ẕilleh. ẕâlike-lyevmü-lleẕî kânû yû`adûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'innâ erselnâ nûḥan ilâ ḳavmihî en enẕir ḳavmeke min ḳabli ey ye''tiyehüm `aẕâbün elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, 'ḳâle yâ ḳavmi innî leküm neẕîrum mübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'eni-`büdü-llâhe vetteḳûhü veeṭî`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'yagfir leküm min ẕünûbiküm veyüeḫḫirküm ilâ ecelim müsemmâ. inne ecele-llâhi iẕâ câe lâ yü''eḫḫar. lev küntüm ta`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'ḳâle rabbi innî de`avtü ḳavmî leylev venehârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'felem yezidhüm dü`âî illâ firârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'veinnî küllemâ de`avtühüm litagfira lehüm ce`alû eṣâbi`ahüm fî âẕânihim vestagşev ŝiyâbehüm veeṣarru vestekberü-stikbârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'ŝümme innî de`avtühüm cihârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'ŝümme innî a`lentü lehüm veesrartü lehüm isrârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'feḳultü-stagfirû rabbeküm innehû kâne gaffârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'yürsili-ssemâe `aleyküm midrârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'veyümdidküm biemvâliv vebenîne veyec`al leküm cennâtiv veyec`al leküm enhârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'mâ leküm lâ tercûne lillâhi veḳârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'veḳad ḫaleḳaküm aṭvârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'elem terav keyfe ḫaleḳa-llâhü seb`a semâvâtin ṭibâḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'vece`ale-lḳamera fîhinne nûrav vece`ale-şşemse sirâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'vellâhü embeteküm mine-l''arḍi nebâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'ŝümme yü`îdüküm fîhâ veyuḫricüküm iḫrâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'vellâhü ce`ale lekümü-l''arḍa bisâṭâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'liteslükû minhâ sübülen ficâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'ḳâle nûḥur rabbi innehüm `aṣavnî vettebe`û mel lem yezidhü mâlühû veveledühû illâ ḫasârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'vemekerû mekran kübbârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'veḳâlû lâ teẕerunne âliheteküm velâ teẕerunne veddev velâ süvâ`av velâ yegûŝe veye`ûḳa venesrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'veḳad eḍallû keŝîrâ. velâ tezidi-żżâlimîne illâ ḍalâlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'mimmâ ḫaṭîâtihim ugriḳû feüdḫilû nâran felem yecidû lehüm min dûni-llâhi enṣârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'veḳâle nûḥur rabbi lâ teẕer `ale-l''arḍi mine-lkâfirîne deyyârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'inneke in teẕerhüm yüḍillû `ibâdeke velâ yelidû illâ fâciran keffârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'rabbi-gfir lî velivâlideyye velimen deḫale beytiye mü''minev velilmü''minîne velmü''minât. velâ tezidi-żżâlimîne illâ tebârâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'ḳul ûḥiye ileyye ennehü-steme`a neferum mine-lcinni feḳâlû innâ semi`nâ ḳur''ânen `acebâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'yehdî ile-rruşdi feâmennâ bih. velen nüşrike birabbinâ eḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'veennehû te`âlâ ceddü rabbinâ me-tteḫaẕe ṣâḥibetev velâ veledâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'veennehû kâne yeḳûlü sefîhünâ `ale-llâhi şeṭaṭâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'veennâ żanennâ el len teḳûle-l''insü velcinnü `ale-llâhi keẕibâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'veennehû kâne ricâlüm mine-l''insi ye`ûẕûne biricâlim mine-lcinni fezâdûhüm raheḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'veennehüm żannû kemâ żanentüm el ley yeb`aŝe-llâhü eḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'veennâ lemesne-ssemâe fevecednâhâ müliet ḥarasen şedîdev veşühübâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'veennâ künnâ naḳ`udü minhâ meḳâ`ide lissem`. femey yestemi`i-l''âne yecid lehû şihâber raṣadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'veennâ lâ nedrî eşerrun ürîde bimen fi-l''arḍi em erâde bihim rabbühüm raşedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'veennâ minne-ṣṣâliḥûne veminnâ dûne ẕâlik. künnâ ṭarâiḳa ḳidedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'veennâ żanennâ el len nü`cize-llâhe fi-l''arḍi velen nü`cizehû herabâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'veennâ lemmâ semi`ne-lhüdâ âmennâ bih. femey yü''mim birabbihî felâ yeḫâfü baḫsev velâ raheḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'veennâ minne-lmüslimûne veminne-lḳâsiṭûn. femen esleme feülâike teḥarrav raşedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'veemme-lḳâsiṭûne fekânû licehenneme ḥaṭabâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'veel levi-steḳâmû `ale-ṭṭarîḳati leesḳaynâhüm mâen gadeḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'lineftinehüm fîh. vemey yü`riḍ `an ẕikri rabbihî yeslükhü `aẕâben ṣa`adâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'veenne-lmesâcide lillâhi felâ ted`û me`a-llâhi eḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'veennehû lemmâ ḳâme `abdü-llâhi yed`ûhü kâdû yekûnûne `aleyhi libedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'ḳul innemâ ed`û rabbî velâ üşrikü bihî eḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'ḳul innî lâ emlikü leküm ḍarrav velâ raşedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'ḳul innî ley yücîranî mine-llâhi eḥadüv velen ecide min dûnihî mülteḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'illâ belâgam mine-llâhi verisâlâtih. vemey ya`ṣi-llâhe verasûlehû feinne lehû nâra cehenneme ḫâlidîne fîhâ ebedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'ḥattâ iẕâ raev mâ yû`adûne feseya`lemûne men aḍ`afü nâṣirav veeḳallü `adedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'ḳul in edrî eḳarîbüm mâ tû`adûne em yec`alü lehû rabbî emedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, '`âlimü-lgaybi felâ yużhiru `alâ gaybihî eḥadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'illâ meni-rteḍâ mir rasûlin feinnehû yeslükü mim beyni yedeyhi vemin ḫalfihî raṣadâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'liya`leme en ḳad eblegû risâlâti rabbihim veeḥâṭa bimâ ledeyhim veaḥṣâ külle şey''in `adedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'yâ eyyühe-lmüzzemmil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'ḳumi-lleyle illâ ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'niṣfehû evi-nḳuṣ minhü ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'ev zid `aleyhi verattili-lḳur''âne tertîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'innâ senülḳî `aleyke ḳavlen ŝeḳîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'inne nâşiete-lleyli hiye eşeddü vaṭ''ev veaḳvemü ḳîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'inne leke fi-nnehâri sebḥan ṭavîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'veẕküri-sme rabbike vetebettel ileyhi tebtîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, 'rabbü-lmeşriḳi velmagribi lâ ilâhe illâ hüve fetteḫiẕhü vekîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'vaṣbir `alâ mâ yeḳûlûne vehcürhüm hecran cemîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'veẕernî velmükeẕẕibîne üli-nna`meti vemehhilhüm ḳalîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'inne ledeynâ enkâlev veceḥîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'veṭa`âmen ẕâ guṣṣativ ve`aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'yevme tercüfü-l''arḍu velcibâlü vekâneti-lcibâlü keŝîbem mehîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'innâ erselnâ ileyküm rasûlen şâhiden `aleyküm kemâ erselnâ ilâ fir`avne rasûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'fe`aṣâ fir`avnü-rrasûle feeḫaẕnâhü aḫẕev vebîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'fekeyfe tetteḳûne in kefertüm yevmey yec`alü-lvildâne şîbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'essemâü münfeṭirum bih. kâne va`dühû mef`ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'inne hâẕihî teẕkirah. femen şâe-tteḫaẕe ilâ rabbihî sebîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'inne rabbeke ya`lemü enneke teḳûmü ednâ min ŝülüŝeyi-lleyli veniṣfehû veŝülüŝehû veṭâifetüm mine-lleẕîne me`ak. vellâhü yüḳaddiru-lleyle vennehâr. `alime el len tuḥṣûhü fetâbe `aleyküm faḳraû mâ teyessera mine-lḳur''ân. `alime en seyekûnü minküm merḍâ veâḫarûne yaḍribûne fi-l''arḍi yebtegûne min faḍli-llâhi veâḫarûne yüḳâtilûne fî sebîli-llâh. faḳraû mâ teyessera minhü veeḳîmu-ṣṣalâte veâtü-zzekâte veaḳriḍü-llâhe ḳarḍan ḥasenâ. vemâ tüḳaddimû lienfüsiküm min ḫayrin tecidûhü `inde-llâhi hüve ḫayrav vea`żame ecrâ. vestagfirü-llâh. inne-llâhe gafûrur raḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'yâ eyyühe-lmüddeŝŝir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'ḳum feenẕir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'verabbeke fekebbir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'veŝiyâbeke feṭahhir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'verrucze fehcür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'velâ temnün testekŝir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'velirabbike faṣbir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'feiẕâ nüḳira fi-nnâḳûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'feẕâlike yevmeiẕiy yevmün `asîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, '`ale-lkâfirîne gayru yesîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'ẕernî vemen ḫalaḳtü veḥîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'vece`altü lehû mâlem memdûdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'vebenîne şühûdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'vemehhettü lehû temhîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'ŝümme yaṭme`u en ezîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'kellâ. innehû kâne liâyâtinâ `anîdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'seürhiḳuhû ṣa`ûdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'innehû fekkera veḳaddera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'feḳutile keyfe ḳaddera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'ŝümme ḳutile keyfe ḳaddera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'ŝümme neżara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'ŝümme `abese vebesera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'ŝümme edbera vestekbera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'feḳâle in hâẕâ illâ siḥruy yü''ŝer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'in hâẕâ illâ ḳavlü-lbeşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'seuṣlîhi seḳara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'vemâ edrâke mâ seḳar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'lâ tübḳî velâ teẕer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'levvâḥatül lilbeşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, '`aleyhâ tis`ate `aşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'vemâ ce`alnâ aṣḥâbe-nnâri illâ melâikeh. vemâ ce`alnâ `iddetehüm illâ fitnetel lilleẕîne keferû liyesteyḳine-lleẕîne ûtü-lkitâbe veyezdâde-lleẕîne âmenû îmânev velâ yertâbe-lleẕîne ûtü-lkitâbe velmü''minûne veliyeḳûle-lleẕîne fî ḳulûbihim meraḍuv velkâfirûne mâẕâ erâde-llâhü bihâẕâ meŝelâ. keẕâlike yüḍillü-llâhü mey yeşâü veyehdî mey yeşâ''. vemâ ya`lemü cünûde rabbike illâ hû. vemâ hiye illâ ẕikrâ lilbeşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'kellâ velḳamer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'velleyli iẕ edbera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'veṣṣubḥi iẕâ esfera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'innehâ leiḥde-lküber.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'neẕîral lilbeşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'limen şâe minküm ey yeteḳaddeme ev yeteeḫḫar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'küllü nefsim bimâ kesebet rahîneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'illâ aṣḥâbe-lyemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'fî cennâtin. yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, '`ani-lmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, 'mâ selekeküm fî seḳara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'ḳâlû lem nekü mine-lmüṣallîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'velem nekü nuṭ`imü-lmiskîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'vekünnâ neḫûḍu me`a-lḫâiḍîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'vekünnâ nükeẕẕibü biyevmi-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'ḥattâ etâne-lyeḳîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'femâ tenfe`uhüm şefâ`atü-şşâfi`în.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'femâ lehüm `ani-tteẕkirati mü`riḍîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'keennehüm ḥumürum müstenfirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'ferrat min ḳasverah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'bel yürîdü küllü-mriim minhüm ey yü''tâ ṣuḥufem müneşşerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'kellâ. bel lâ yeḫâfûne-l''âḫirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'kellâ innehû teẕkirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'femen şâe ẕekerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'vemâ yeẕkürûne illâ ey yeşâe-llâh. hüve ehlü-ttaḳvâ veehlü-lmagfirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'lâ uḳsimü biyevmi-lḳiyâmeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'velâ uḳsimü binnefsi-llevvâmeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'eyaḥsebü-l''insânü ellen necme`a `iżâmeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'belâ ḳâdirîne `alâ en nüsevviye benâneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'bel yürîdü-l''insânü liyefcüra emâmeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'yes''elü eyyâne yevmü-lḳiyâmeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'feiẕâ beriḳa-lbeṣar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'veḫasefe-lḳamer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'vecümi`a-şşemsü velḳamer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'yeḳûlü-l''insânü yevmeiẕin eyne-lmeferr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'kellâ lâ vezer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'ilâ rabbike yevmeiẕin-lmüsteḳarr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'yünebbeü-l''insânü yevmeiẕim bimâ ḳaddeme veeḫḫar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'beli-l''insânü `alâ nefsihî beṣîrah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'velev elḳâ me`âẕîrah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'lâ tüḥarrik bihî lisâneke lita`cele bih.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'inne `aleynâ cem`ahû veḳur''âneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'feiẕâ ḳara''nâhü fettebi` ḳur''âneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'ŝümme inne `aleynâ beyâneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'kellâ bel tüḥibbûne-l`âcileh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'veteẕerûne-l''âḫirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'vucûhüy yevmeiẕin nâḍirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'ilâ rabbihâ nâżirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'vevucûhüy yevmeiẕim bâsirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'teżunnü ey yüf`ale bihâ fâḳirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'kellâ iẕâ belegati-tterâḳiy.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'veḳîle men râḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'veżanne ennehü-lfirâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'velteffeti-ssâḳu bissâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'ilâ rabbike yevmeiẕin-lmesâḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'felâ ṣaddeḳa velâ ṣallâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'velâkin keẕẕebe vetevellâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'ŝümme ẕehebe ilâ ehlihî yetemeṭṭâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'evlâ leke feevlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'ŝümme evlâ leke feevlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'eyaḥsebü-l''insânü ey yütrake südâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'elem yekü nuṭfetem mim meniyyiy yümnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'ŝümme kâne `aleḳaten feḫaleḳa fesevvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'fece`ale minhü-zzevceyni-ẕẕekera vel''ünŝâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'eleyse ẕâlike biḳâdirin `alâ ey yuḥyiye-lmevtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'hel etâ `ale-l''insâni ḥînüm mine-ddehri lem yekün şey''em meẕkûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'innâ ḫalaḳne-l''insâne min nuṭfetin emşâc. nebtelîhi fece`alnâhü semî`am beṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'innâ hedeynâhü-ssebîle immâ şâkirav veimmâ kefûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'innâ a`tednâ lilkâfirîne selâsile veaglâlev vese`îrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'inne-l''ebrâra yeşrabûne min ke''sin kâne mizâcühâ kâfûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, '`ayney yeşrabü bihâ `ibâdü-llâhi yüfeccirûnehâ tefcîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'yûfûne binneẕri veyeḫâfûne yevmen kâne şerruhû müsteṭîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'veyuṭ`imûne-ṭṭa`âme `alâ ḥubbihî miskînev veyetîmev veesîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, 'innemâ nuṭ`imüküm livechi-llâhi lâ nürîdü minküm cezâev velâ şükûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'innâ neḫâfü mir rabbinâ yevmen `abûsen ḳamṭarîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'feveḳâhümü-llâhü şerra ẕâlike-lyevmi veleḳḳâhüm naḍratev vesürûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'vecezâhüm bimâ ṣaberû cennetev veḥarîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'müttekiîne fîhâ `ale-l''erâik. lâ yeravne fîhâ şemsev velâ zemherîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'vedâniyeten `aleyhim żilâlühâ veẕüllilet ḳuṭûfühâ teẕlîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'veyüṭâfü `aleyhim biâniyetim min fiḍḍativ veekvâbin kânet ḳavârîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'ḳavârîrae min fiḍḍatin ḳadderûhâ taḳdîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'veyüsḳavne fîhâ ke''sen kâne mizâcühâ zencebîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, '`aynen fîhâ tüsemmâ selsebîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'veyeṭûfü `aleyhim vildânüm müḫalledûn. iẕâ raeytehüm ḥasibtehüm lü''lüem menŝûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'veiẕâ raeyte ŝemme raeyte ne`îmev vemülken kebîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, '`âliyehüm ŝiyâbü sündüsin ḫuḍruv veistebraḳ. veḥullû esâvira min fiḍḍah. veseḳâhüm rabbühüm şerâben ṭahûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, 'inne hâẕâ kâne leküm cezâev vekâne sa`yüküm meşkûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'innâ naḥnü nezzelnâ `aleyke-lḳur''âne tenzîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'faṣbir liḥukmi rabbike velâ tüṭi` minhüm âŝimen ev kefûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'veẕküri-sme rabbike bükratev veeṣîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'vemine-lleyli fescüd lehû vesebbiḥhü leylen ṭavîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'inne hâülâi yüḥibbûne-l`âcilete veyeẕerûne verâehüm yevmen ŝeḳîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'naḥnü ḫalaḳnâhüm veşedednâ esrahüm. veiẕâ şi''nâ beddelnâ emŝâlehüm tebdîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'inne hâẕihî teẕkirah. femen şâe-tteḫaẕe ilâ rabbihî sebîlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'vemâ teşâûne illâ ey yeşâe-llâh. inne-llâhe kâne `alîmen ḥakîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'yüdḫilü mey yeşâü fî raḥmetih. veżżâlimîne e`adde lehüm `aẕâben elîmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'velmürselâti `urfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'fel`âṣifâti `aṣfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'vennâşirâti neşrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'felfâriḳâti ferḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'felmülḳiyâti ẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, '`uẕran ev nüẕrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'innemâ tû`adûne levâḳi`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'feiẕe-nnücûmü ṭumiset.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'veiẕe-ssemâü füricet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'veiẕe-lcibâlü nüsifet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'veiẕe-rrusülü üḳḳitet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'lieyyi yevmin üccilet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'liyevmi-lfaṣl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'vemâ edrâke mâ yevmü-lfaṣl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'elem nühliki-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'ŝümme nütbi`uhümü-l''âḫirîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'keẕâlike nef`alü bilmücrimîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'elem naḫlukküm mim mâim mehîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'fece`alnâhü fî ḳarârim mekîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'ilâ ḳaderim ma`lûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'feḳadernâ. feni`me-lḳâdirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'elem nec`ali-l''arḍa kifâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'aḥyâev veemvâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'vece`alnâ fîhâ ravâsiye şâmiḫâtiv veesḳaynâküm mâen fürâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, 'inṭaliḳû ilâ mâ küntüm bihî tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'inṭaliḳû ilâ żillin ẕî ŝelâŝi şu`ab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'lâ żalîliv velâ yugnî mine-lleheb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'innehâ termî bişerarin kelḳaṣr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'keennehû cimâlâtün ṣufr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'hâẕâ yevmü lâ yenṭiḳûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'velâ yü''ẕenü lehüm feya`teẕirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'hâẕâ yevmü-lfaṣl. cema`nâküm vel''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'fein kâne leküm keydün fekîdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'inne-lmütteḳîne fî żilâliv ve`uyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'vefevâkihe mimmâ yeştehûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, 'külû veşrabû henîem bimâ küntüm ta`melûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'innâ keẕâlike neczi-lmuḥsinîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, 'külû vetemette`û ḳalîlen inneküm mücrimûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'veiẕâ ḳîle lehümü-rke`û lâ yerke`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'febieyyi ḥadîŝim ba`dehû yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, '`amme yetesâelûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, '`ani-nnebei-l`ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'elleẕî hüm fîhi muḫtelifûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'kellâ seya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'ŝümme kellâ seya`lemûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'elem nec`ali-l''arḍa mihâdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'velcibâle evtâdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'veḫalaḳnâküm ezvâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'vece`alnâ nevmeküm sübâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'vece`alne-lleyle libâsâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'vece`alne-nnehâra me`âşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'vebeneynâ fevḳaküm seb`an şidâdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'vece`alnâ sirâcev vehhâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'veenzelnâ mine-lmü`ṣirâti mâen ŝeccâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'linuḫrice bihî ḥabbev venebâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'vecennâtin elfâfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'inne yevme-lfaṣli kâne mîḳâtâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'yevme yünfeḫu fi-ṣṣûri fete''tûne efvâcâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'vefütiḥati-ssemâü fekânet ebvâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'vesüyyirati-lcibâlü fekânet serâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'inne cehenneme kânet mirṣâdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'liṭṭâgîne meâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'lâbiŝîne fîhâ aḥḳâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'lâ yeẕûḳûne fîhâ berdev velâ şerâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'illâ ḥamîmev vegassâḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'cezâev vifâḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'innehüm kânû lâ yercûne ḥisâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'vekeẕẕebû biâyâtinâ kiẕẕâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'vekülle şey''in aḥṣaynâhü kitâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, 'feẕûḳû felen nezîdeküm illâ `aẕâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'inne lilmütteḳîne mefâzâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'ḥadâiḳa vea`nâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'vekevâ`ibe etrâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'veke''sen dihâḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'lâ yesme`ûne fîhâ lagvev velâ kiẕẕâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'cezâem mir rabbike `aṭâen ḥisâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'rabbi-ssemâvâti vel''arḍi vemâ beynehüme-rraḥmâni lâ yemlikûne minhü ḫiṭâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'yevme yeḳûmü-rrûḥu velmelâiketü ṣaffâ. lâ yetekellemûne illâ men eẕine lehü-rraḥmânü veḳâle ṣavâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'ẕâlike-lyevmü-lḥaḳḳ. femen şâe-tteḫaẕe ilâ rabbihî meâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'innâ enẕernâküm `aẕâben ḳarîbâ. yevme yenżuru-lmerü mâ ḳaddemet yedâhü veyeḳûlü-lkâfiru yâ leytenî küntü türâbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'vennâzi`âti garḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'vennâşiṭâti neşṭâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'vessâbiḥâti sebḥâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'fessâbiḳâti sebḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'felmüdebbirâti emrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'yevme tercüfü-rrâcifeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'tetbe`uhe-rrâdifeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'ḳulûbüy yevmeiẕiv vâcifeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'ebṣâruhâ ḫâşi`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'yeḳûlûne einnâ lemerdûdûne fi-lḥâfirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'eiẕâ künnâ `iżâmen neḫirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'ḳâlû tilke iẕen kerratün ḫâsirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'feinnemâ hiye zecratüv vâḥideh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'feiẕâ hüm bissâhirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'hel etâke ḥadîŝü mûsâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'iẕ nâdâhü rabbühû bilvâdi-lmüḳaddesi ṭuvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, 'iẕheb ilâ fir`avne innehû ṭagâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'feḳul hel leke ilâ en tezekkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'veehdiyeke ilâ rabbike fetaḫşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'feerâhü-l''âyete-lkübrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'fekeẕẕebe ve`aṣâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'ŝümme edbera yes`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'feḥaşera fenâdâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'feḳâle ene rabbükümü-l''a`lâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'feeḫaẕehü-llâhü nekâle-l''âḫirati vel''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'inne fî ẕâlike le`ibratel limey yaḫşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'eentüm eşeddü ḫalḳan emi-ssemâü. benâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'rafe`a semkehâ fesevvâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'veagṭaşe leylehâ veaḫrace ḍuḥâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'vel''arḍa ba`de ẕâlike deḥâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'aḫrace minhâ mâehâ vemer`âhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'velcibâle ersâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'metâ`al leküm velien`âmiküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'feiẕâ câeti-ṭṭâmmetü-lkübrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'yevme yeteẕekkeru-l''insânü mâ se`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'vebürrizeti-lceḥîmü limey yerâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'feemmâ men ṭagâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'veâŝera-lḥayâte-ddünyâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'feinne-lceḥîme hiye-lme''vâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'veemmâ men ḫâfe meḳâme rabbihî venehe-nnefse `ani-lhevâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'feinne-lcennete hiye-lme''vâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'yes''elûneke `ani-ssâ`ati eyyâne mürsâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'fîme ente min ẕikrâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'ilâ rabbike müntehâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'innemâ ente münẕiru mey yaḫşâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'keennehüm yevme yeravnehâ lem yelbeŝû illâ `aşiyyeten ev ḍuḥâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, '`abese vetevellâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'en câehü-l''a`mâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'vemâ yüdrîke le`allehû yezzekkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'ev yeẕẕekkeru fetenfe`ahü-ẕẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'emmâ meni-stagnâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'feente lehû teṣaddâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'vemâ `aleyke ellâ yezzekkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'veemmâ men câeke yes`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'vehüve yaḫşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'feente `anhü telehhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'kellâ innehâ teẕkirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'femen şâe ẕekerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'fî ṣuḥufim mükerrameh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'merfû`atim müṭahherah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'bieydî seferah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'kirâmim berarah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'ḳutile-l''insânü mâ ekferah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'min eyyi şey''in ḫaleḳah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'min nuṭfeh. ḫaleḳahû feḳadderah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'ŝümme-ssebîle yesserah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'ŝümme emâtehû feaḳberah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'ŝümme iẕâ şâe enşerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'kellâ lemmâ yaḳḍi mâ emerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'felyenżuri-l''insânü ilâ ṭa`âmih.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'ennâ ṣabebne-lmâe ṣabbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'ŝümme şaḳaḳne-l''arḍa şeḳḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'feembetnâ fîhâ ḥabbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 've`inebev veḳaḍbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'vezeytûnev venaḫlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'veḥadâiḳa gulbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'vefâkihetev veebbâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'metâ`al leküm velien`âmiküm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'feiẕâ câeti-ṣṣâḫḫah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'yevme yefirru-lmerü min eḫîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'veümmihî veebîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'veṣâḥibetihî vebenîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'likülli-mriim minhüm yevmeiẕin şe''nüy yugnîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'vucûhüy yevmeiẕim müsfirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'ḍâḥiketüm müstebşirah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'vevucûhüy yevmeiẕin `aleyhâ gaberah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'terheḳuhâ ḳaterah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'ülâike hümü-lkeferatü-lfecerah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'iẕe-şşemsü küvvirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'veiẕe-nnücûmü-nkederat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'veiẕe-lcibâlü süyyirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'veiẕe-l`işâru `uṭṭilet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'veiẕe-lvuḥûşü ḥuşirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'veiẕe-lbiḥâru süccirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'veiẕe-nnüfûsü züvvicet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'veiẕe-lmev''ûdetü süilet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'bieyyi ẕembin ḳutilet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'veiẕe-ṣṣuḥufü nüşirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'veiẕe-ssemâü küşiṭat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'veiẕe-lceḥîmü sü``irat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'veiẕe-lcennetü üzlifet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, '`alimet nefsüm mâ aḥḍarat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'felâ uḳsimü bilḫunnes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'elcevâri-lkünnes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'velleyli iẕâ `as`as.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'veṣṣubḥi iẕâ teneffes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'innehû leḳavlü rasûlin kerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'ẕî ḳuvvetin `inde ẕi-l`arşi mekîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'müṭâ`in ŝemme emîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'vemâ ṣâḥibüküm bimecnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'veleḳad raâhü bil''üfüḳi-lmübîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'vemâ hüve `ale-lgaybi biḍanîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'vemâ hüve biḳavli şeyṭânir racîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'feeyne teẕhebûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'in hüve illâ ẕikrul lil`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'limen şâe minküm ey yesteḳîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'vemâ teşâûne illâ ey yeşâe-llâhü rabbü-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'iẕe-ssemâü-nfeṭarat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'veiẕe-lkevâkibü-nteŝerat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'veiẕe-lbiḥâru füccirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'veiẕe-lḳubûru bü`ŝirat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, '`alimet nefsüm mâ ḳaddemet veeḫḫarat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'yâ eyyühe-l''insânü mâ garrake birabbike-lkerîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'elleẕî ḫaleḳake fesevvâke fe`adelek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'fî eyyi ṣûratim mâ şâe rakkebek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'kellâ bel tükeẕẕibûne biddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'veinne `aleyküm leḥâfiżîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'kirâmen kâtibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'ya`lemûne mâ tef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'inne-l''ebrâra lefî ne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'veinne-lfüccâra lefî ceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'yaṣlevnehâ yevme-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'vemâ hüm `anhâ bigâibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'vemâ edrâke mâ yevmü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'ŝümme mâ edrâke mâ yevmü-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'yevme lâ temlikü nefsül linefsin şey''â. vel''emru yevmeiẕil lillâh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'veylül lilmüṭaffifîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'elleẕîne iẕe-ktâlû `ale-nnâsi yestevfûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'veiẕâ kâlûhüm ev vezenûhüm yuḫsirûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'elâ yeżunnü ülâike ennehüm meb`ûŝûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'liyevmin `ażîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'yevme yeḳûmü-nnâsü lirabbi-l`âlemîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'kellâ inne kitâbe-lfüccâri lefî siccîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'vemâ edrâke mâ siccîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'kitâbüm merḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'veylüy yevmeiẕil lilmükeẕẕibîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'elleẕîne yükeẕẕibûne biyevmi-ddîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'vemâ yükeẕẕibü bihî illâ küllü mü`tedin eŝîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'iẕâ tütlâ `aleyhi âyâtünâ ḳâle esâṭîru-l''evvelîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'kellâ bel râne `alâ ḳulûbihim mâ kânû yeksibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'kellâ innehüm `ar rabbihim yevmeiẕil lemaḥcûbûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'ŝümme innehüm leṣâlü-lceḥîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'ŝümme yüḳâlü hâẕe-lleẕî küntüm bihî tükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'kellâ inne kitâbe-l''ebrâri lefî `illiyyîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'vemâ edrâke mâ `illiyyûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'kitâbüm merḳûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'yeşhedühü-lmüḳarrabûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'inne-l''ebrâra lefî ne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, '`ale-l''erâiki yenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'ta`rifü fî vucûhihim naḍrate-nne`îm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'yüsḳavne mir raḥîḳim maḫtûm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'ḫitâmühû misk. vefî ẕâlike felyetenâfesi-lmütenâfisûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'vemizâcühû min tesnîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, '`ayney yeşrabü bihe-lmüḳarrabûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'inne-lleẕîne ecramû kânû mine-lleẕîne âmenû yaḍḥakûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'veiẕâ merrû bihim yetegâmezûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'veiẕe-nḳalebû ilâ ehlihimü-nḳalebû fekihîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'veiẕâ raevhüm ḳâlû inne hâülâi leḍâllûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'vemâ ürsilû `aleyhim ḥâfiżîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'felyevme-lleẕîne âmenû mine-lküffâri yaḍḥakûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, '`ale-l''erâiki yenżurûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, 'hel ŝüvvibe-lküffâru mâ kânû yef`alûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'iẕe-ssemâü-nşeḳḳat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'veeẕinet lirabbihâ veḥuḳḳat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'veiẕe-l''arḍu müddet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'veelḳat mâ fîhâ veteḫallet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'veeẕinet lirabbihâ veḥuḳḳat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'yâ eyyühe-l''insânü inneke kâdiḥun ilâ rabbike kedḥan femülâḳîh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'feemmâ men ûtiye kitâbehû biyemînih.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'fesevfe yüḥâsebü ḥisâbey yesîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'veyenḳalibü ilâ ehlihî mesrûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'veemmâ men ûtiye kitâbehû verâe żahrih.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'fesevfe yed`û ŝübûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'veyaṣlâ se`îrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'innehû kâne fî ehlihî mesrûrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'innehû żanne el ley yeḥûr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'belâ. inne rabbehû kâne bihî beṣîrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'felâ uḳsimü bişşefeḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'velleyli vemâ veseḳa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'velḳameri iẕe-tteseḳa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'leterkebünne ṭabeḳan `an ṭabaḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'femâ lehüm lâ yü''minûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'veiẕâ ḳurie `aleyhimü-lḳur''ânü lâ yescüdûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'beli-lleẕîne keferû yükeẕẕibûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'vellâhü a`lemü bimâ yû`ûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'febeşşirhüm bi`aẕâbin elîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'ille-lleẕîne âmenû ve`amilu-ṣṣâliḥâti lehüm ecrun gayru memnûn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'vessemâi ẕâti-lbürûc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'velyevmi-lmev`ûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'veşâhidiv vemeşhûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'ḳutile aṣḥâbü-l''uḫdûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'ennâri ẕâti-lveḳûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'iẕ hüm `aleyhâ ḳu`ûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'vehüm `alâ mâ yef`alûne bilmü''minîne şühûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'vemâ neḳamû minhüm illâ ey yü''minû billâhi-l`azîzi-lḥamîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'elleẕî lehû mülkü-ssemâvâti vel''arḍ. vellâhü `alâ külli şey''in şehîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'inne-lleẕîne fetenü-lmü''minîne velmü''minâti ŝümme lem yetûbû felehüm `aẕâbü cehenneme velehüm `aẕâbü-lḥarîḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'inne-lleẕîne âmenû ve`amilu-ṣṣâliḥâti lehüm cennâtün tecrî min taḥtihe-l''enhâr. ẕâlike-lfevzü-lkebîr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'inne baṭşe rabbike leşedîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'innehû hüve yübdiü veyü`îd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'vehüve-lgafûru-lvedûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'ẕü-l`arşi-lmecîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'fa``âlül limâ yürîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'hel etâke ḥadîŝü-lcünûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'fir`avne veŝemûd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'beli-lleẕîne keferû fî tekẕîb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'vellâhü miv verâihim müḥîṭ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'bel hüve ḳur''ânüm mecîd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'fî levḥim maḥfûż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'vessemâi veṭṭâriḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'vemâ edrâke me-ṭṭâriḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, 'ennecmü-ŝŝâḳib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'in küllü nefsil lemmâ `aleyhâ ḥâfiż.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'felyenżuri-l''insânü mimme ḫuliḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'ḫuliḳa mim mâin dâfiḳ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'yaḫrucü mim beyni-ṣṣulbi vetterâib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'innehû `alâ rac`ihî leḳâdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'yevme tüble-sserâir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'femâ lehû min ḳuvvetiv velâ nâṣir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'vessemâi ẕâti-rrac`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'vel''arḍi ẕâti-ṣṣad`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'innehû leḳavlün faṣl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'vemâ hüve bilhezl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'innehüm yekîdûne keydâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'veekîdü keydâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'femehhili-lkâfirîne emhilhüm ruveydâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'sebbiḥi-sme rabbike-l''a`lâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'elleẕî ḫaleḳa fesevvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'velleẕî ḳaddera fehedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'velleẕî aḫrace-lmer`â.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'fece`alehû guŝâen aḥvâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'senuḳriüke felâ tensâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'illâ mâ şâe-llâh. innehû ya`lemü-lcehra vemâ yaḫfâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'venüyessiruke lilyüsrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'feẕekkir in nefe`ati-ẕẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'seyeẕẕekkeru mey yaḫşâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'veyetecennebühe-l''eşḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'elleẕî yaṣle-nnâra-lkübrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'ŝümme lâ yemûtü fîhâ velâ yaḥyâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'ḳad efleḥa men tezekkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'veẕekera-sme rabbihî feṣallâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'bel tü''ŝirûne-lḥayâte-ddünyâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'vel''âḫiratü ḫayruv veebḳâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'inne hâẕâ lefi-ṣṣuḥufi-l''ûlâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'ṣuḥufi ibrâhîme vemûsâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'hel etâke ḥadîŝü-lgâşiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'vucûhüy yevmeiẕin ḫâşi`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, '`âmiletün nâṣibeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'taṣlâ nâran ḥâmiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'tüsḳâ min `aynin âniyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'leyse lehüm ṭa`âmün illâ min ḍarî`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'lâ yüsminü velâ yugnî min cû`.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'vucûhüy yevmeiẕin nâ`imeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'lisa`yihâ râḍiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'fî cennetin `âliyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'lâ tesme`u fîhâ lâgiyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'fîhâ `aynün câriyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'fîhâ sürurum merfû`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'veekvâbüm mevḍû`ah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'venemâriḳu maṣfûfeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'vezerâbiyyü mebŝûŝeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'efelâ yenżurûne ile-l''ibili keyfe ḫuliḳat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'veile-ssemâi keyfe rufi`at.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'veile-lcibâli keyfe nüṣibet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'veile-l''arḍi keyfe süṭiḥat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'feẕekkir innemâ ente müẕekkir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'leste `aleyhim bimüṣayṭir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'illâ men tevellâ vekefera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'feyü`aẕẕibühü-llâhü-l`aẕâbe-l''ekber.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'inne ileynâ iyâbehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'ŝümme inne `aleynâ ḥisâbehüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'velfecr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'veleyâlin `aşr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'veşşef`i velvetr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'velleyli iẕâ yesr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'hel fî ẕâlike ḳasemül liẕî ḥicr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'elem tera keyfe fe`ale rabbüke bi`âd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'irame ẕâti-l`imâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'elletî lem yuḫlaḳ miŝlühâ fi-lbilâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'veŝemûde-lleẕîne câbu-ṣṣaḫra bilvâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'vefir`avne ẕi-l''evtâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'elleẕîne ṭagav fi-lbilâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'feekŝerû fîhe-lfesâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'feṣabbe `aleyhim rabbüke sevṭa `aẕâb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'inne rabbeke lebilmirṣâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'feemme-l''insânü iẕâ me-btelâhü rabbühû feekramehû vene``amehû feyeḳûlü rabbî ekramen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'veemmâ iẕâ me-btelâhü feḳadera `aleyhi rizḳahû feyeḳûlü rabbî ehânen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'kellâ bel lâ tükrimûne-lyetîm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'velâ teḥâḍḍûne `alâ ṭa`âmi-lmiskîn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'vete''külûne-ttürâŝe eklel lemmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'vetüḥibbûne-lmâle ḥubben cemmâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'kellâ iẕâ dükketi-l''arḍu dekken dekkâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'vecâe rabbüke velmelekü ṣaffen ṣaffâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'vecîe yevmeiẕim bicehenneme yevmeiẕiy yeteẕekkeru-l''insânü veennâ lehü-ẕẕikrâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'yeḳûlü yâ leytenî ḳaddemtü liḥayâtî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'feyevmeiẕil lâ yü`aẕẕibü `aẕâbehû eḥad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'velâ yûŝiḳu veŝâḳahû eḥad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, 'yâ eyyetühe-nnefsü-lmuṭmeinneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'irci`î ilâ rabbiki râḍiyetem merḍiyyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'fedḫulî fî `ibâdî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'vedḫulî cennetî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'lâ uḳsimü bihâẕe-lbeled.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'veente ḥillüm bihâẕe-lbeled.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'vevâlidiv vemâ veled.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'leḳad ḫalaḳne-l''insâne fî kebed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'eyaḥsebü el ley yaḳdira `aleyhi eḥad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'yeḳûlü ehlektü mâlel lübedâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'eyaḥsebü el lem yerahû eḥad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'elem nec`al lehû `ayneyn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'velisânev veşefeteyn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'vehedeynâhü-nnecdeyn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'fele-ḳteḥame-l`aḳabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'vemâ edrâke me-l`aḳabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'fekkü raḳabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'ev iṭ`âmün fî yevmin ẕî mesgabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'yetîmen ẕâ maḳrabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'ev miskînen ẕâ metrabeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'ŝümme kâne mine-lleẕîne âmenû vetevâṣav biṣṣabri vetevâṣav bilmerḥameh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'ülâike aṣḥâbü-lmeymeneh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'velleẕîne keferû biâyâtinâ hüm aṣḥâbü-lmeş''emeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, '`aleyhim nârum mü''ṣadeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'veşşemsi veḍuḥâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'velḳameri iẕâ telâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'vennehâri iẕâ cellâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'velleyli iẕâ yagşâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'vessemâi vemâ benâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'vel''arḍi vemâ ṭaḥâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'venefsiv vemâ sevvâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'feelhemehâ fücûrahâ vetaḳvâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'ḳad efleḥa men zekkâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'veḳad ḫâbe men dessâhâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'keẕẕebet ŝemûdü biṭagvâhâ.', '');
