INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'lem yeküni-lleẕîne keferû min ehli-lkitâbi velmüşrikîne münfekkîne ḥattâ te''tiyehümü-lbeyyineh.', '');
