INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'inne-lleẕîne keferû min ehli-lkitâbi velmüşrikîne fî nâri cehenneme ḫâlidîne fîhâ. ülâike hüm şerru-lberiyyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'inne-lleẕîne âmenû ve`amilu-ṣṣâliḥâti ülâike hüm ḫayru-lberiyyeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'cezâühüm `inde rabbihim cennâtü `adnin tecrî min taḥtihe-l''enhâru ḫâlidîne fîhâ ebedâ. raḍiye-llâhü `anhüm veraḍû `anh. ẕâlike limen ḫaşiye rabbeh.', '');
