INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'meliki-nnâs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'ilâhi-nnâs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'min şerri-lvesvâsi-lḫannâs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'elleẕî yüvesvisü fî ṣudûri-nnâs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'mine-lcinneti vennâs.', '');
